	NAmanage._evtHubClear(hub)
	hub.lpAdd = NAmanage._evtHubDisc(hub.lpAdd)
	hub.lpRem = NAmanage._evtHubDisc(hub.lpRem)
	hub.lpAnc = NAmanage._evtHubDisc(hub.lpAnc)
