NAmanage.GetAttr=function(inst, key)
	if not inst or not key then return nil end
	const actualKey = NAmanage.GetSessionAttrKey(key)
	local ok, value = pcall(function() return inst:GetAttribute(actualKey) end)
	if ok and value ~= nil then
		return value
	end
	ok, value = pcall(function() return inst:GetAttribute(key) end)
	if ok and value ~= nil then
		return value
	end
	local tag = inst:FindFirstChild(NAmanage.GetSessionAttrTagName(key))
	if tag and tag:IsA("ValueBase") then
		return tag.Value
	end
	tag = inst:FindFirstChild("_NAATTR_"..tostring(key))
	if tag and tag:IsA("ValueBase") then
		return tag.Value
	end
	return nil
end

NAmanage.SetAttr=function(inst, key, value)
	if not inst or not key then return end
	const actualKey = NAmanage.GetSessionAttrKey(key)
	const ok = pcall(function() inst:SetAttribute(actualKey, value) end)
	if ok then
		return
	end

	const tagName = NAmanage.GetSessionAttrTagName(key)
	local existing = inst:FindFirstChild(tagName)

	if value == nil then
		if existing then pcall(function() existing:Destroy() end) end
		return
	end

	local class = "StringValue"
	if type(value) == "boolean" then
		class = "BoolValue"
	elseif type(value) == "number" then
		class = "NumberValue"
	end

	if not existing or existing.ClassName ~= class then
		if existing then pcall(function() existing:Destroy() end) end
		existing = Instance.new(class)
		existing.Name = tagName
		existing.Archivable = false
		existing.Parent = inst
	end

	existing.Value = value
end

NAmanage.NewCancelToken = NAmanage.NewCancelToken or function()
	return { cancelled = false }
end

NAmanage.CancelTokenCancel = NAmanage.CancelTokenCancel or function(token)
	if type(token) == "table" then
		token.cancelled = true
	end
end

NAmanage.isLoad = NAmanage.isLoad or function()
	local load = nil
	if type(_G) == "table" then
		load = rawget(_G, "NAAssetsLoading")
	end
	if type(load) ~= "table" then
		load = NAAssetsLoading
	end
	if type(load) ~= "table" then
		return false
	end
	if load._finalized == true then
		return false
	end
	if load._visualClosed == true then
		return true
	end
	const done = load.completed
	if typeof(done) == "Instance" then
		const completedAttr = NAmanage.GetAttr(done, "Completed")
		if type(completedAttr) == "boolean" then
			return completedAttr ~= true
		end
		if done:IsA("BoolValue") then
			return done.Value ~= true
		end
	end
	return load._finalized ~= true
end

NAmanage.lpProf = NAmanage.lpProf or function(baseBud, opts)
	opts = opts or {}
	local bud = math.max(1, math.floor(tonumber(baseBud) or 1))
	local del = tonumber(opts.delay) or 0
	if NAmanage.isLoad and NAmanage.isLoad() then
		local sc = tonumber(opts.ldSc)
		if not sc then
			sc = 0.4
		end
		sc = math.clamp(sc, 0.05, 1)
		bud = math.max(1, math.floor(bud * sc))
		const ld = tonumber(opts.ldDel)
		if ld and ld > del then
			del = ld
		elseif del <= 0 then
			del = 0.01
		end
	end
	return bud, del
end

NAmanage.ForEachDescendantYield = function(root, handler, opts)
	opts = opts or {}
	if typeof(root) ~= "Instance" or type(handler) ~= "function" then
		return 0
	end

	const cancelToken = opts.cancelToken
	const includeRoot = opts.includeRoot == true
	const maxItems = tonumber(opts.maxItems)
	const stopOnResult = opts.stopOnResult == true
	const yieldEvery = tonumber(opts.yieldEvery) or tonumber(opts.batchSize) or 96
	const delayTime = tonumber(opts.delayTime) or tonumber(opts.delay) or 0
	const skipChildren = type(opts.skipChildren) == "function" and opts.skipChildren or nil
	local processed = 0
	const work = {}

	const function run(inst)
		if cancelToken and cancelToken.cancelled then
			return true
		end
		processed += 1
		const result = handler(inst)
		if stopOnResult and result then
			return true
		end
		if maxItems and processed >= maxItems then
			return true
		end
		return false
	end

	const world = Services and Services.Workspace
	const streaming = opts.streaming == true or skipChildren ~= nil or root:IsA("Workspace")
		or root:IsA("DataModel") or (world and root:IsDescendantOf(world))
	if streaming then
		const q = { root }
		local qi, qn = 1, 1
		while qi <= qn do
			if cancelToken and cancelToken.cancelled then
				break
			end
			const inst = q[qi]
			q[qi] = nil
			qi += 1
			if inst and (inst == root or inst.Parent) then
				if includeRoot or inst ~= root then
					if run(inst) then
						break
					end
					if yieldEvery > 0 then NAmanage.WorkBudgetStep(work, yieldEvery, 0.003, delayTime) end
				end
				local shouldSkipChildren = false
				if skipChildren then
					local okSkip, skipResult = pcall(skipChildren, inst)
					shouldSkipChildren = okSkip and skipResult == true
				end
				if not shouldSkipChildren then
					local okChildren, children = pcall(inst.GetChildren, inst)
					if okChildren and type(children) == "table" then
						for i = 1, #children do
							qn += 1
							q[qn] = children[i]
						end
					end
				end
			end
		end
		return processed
	end

	const list = NAmanage.QueryDescendants(root, "Instance")
	if includeRoot then
		if run(root) then
			return processed
		end
		if yieldEvery > 0 then NAmanage.WorkBudgetStep(work, yieldEvery, 0.003, delayTime) end
	end
	for i = 1, #list do
		const inst = list[i]
		list[i] = nil
		if typeof(inst) == "Instance" then
			if run(inst) then
				break
			end
			if yieldEvery > 0 then NAmanage.WorkBudgetStep(work, yieldEvery, 0.003, delayTime) end
		end
	end

	return processed
end

NAmanage.RunAfterSettingsBuild = NAmanage.RunAfterSettingsBuild or function(delaySeconds, callback)
	if type(callback) ~= "function" then
		return
	end
	Spawn(function()
		const deadline = os.clock() + 60
		while os.clock() < deadline do
			const state = NAgui and NAgui.SettingsBuildState
			const running = NAStuff and NAStuff.SettingsBuildRunning == true
			const building = type(state) == "table" and state.building == true
			if not running and not building then
				break
			end
			Wait(0.1)
		end
		const delayValue = tonumber(delaySeconds) or 0
		if delayValue > 0 then
			Wait(delayValue)
		end
		pcall(callback)
	end)
end

NAmanage.ForEachWorkspaceYield = function(handler, opts)
	const RawWorkspace = __lt.gs("Workspace")
	opts = opts or {}
	if type(handler) ~= "function" then
		return 0
	end

	const cancelToken = opts.cancelToken
	const includeRoot = opts.includeRoot == true
	const yieldEvery = tonumber(opts.yieldEvery) or tonumber(opts.batchSize) or 160
	const delayTime = tonumber(opts.delayTime) or tonumber(opts.delay) or 0
	const maxItems = tonumber(opts.maxItems) or 0
	local processed = 0
	const work = {}
	const q = { Services.Workspace }
	local qi, qn = 1, 1

	while qi <= qn do
		if cancelToken and cancelToken.cancelled then
			break
		end
		const inst = q[qi]
		q[qi] = nil
		qi += 1
		if inst and (inst == Services.Workspace or inst == RawWorkspace or inst.Parent) then
			if includeRoot or (inst ~= Services.Workspace and inst ~= RawWorkspace) then
				processed += 1
				handler(inst, processed, nil)
				if maxItems > 0 and processed >= maxItems then
					break
				end
			end
			local ok, children = pcall(inst.GetChildren, inst)
			if ok and type(children) == "table" then
				for i = 1, #children do
					qn += 1
					q[qn] = children[i]
				end
			end
		end
		if yieldEvery > 0 and NAmanage.WorkBudgetStep(work, yieldEvery, 0.003) and delayTime > 0 then
			Wait(delayTime)
		end
	end

	return processed
end

NAmanage.ESP_CancelScanToken = NAmanage.ESP_CancelScanToken or function(key)
	if type(key) ~= "string" or key == "" then
		return
	end
	const tokens = NAStuff.espScanTokens
	if type(tokens) ~= "table" then
		return
	end
	const tok = tokens[key]
	if tok then
		NAmanage.CancelTokenCancel(tok)
		tokens[key] = nil
	end
end

NAmanage.ESP_StartScanToken = NAmanage.ESP_StartScanToken or function(key)
	if type(key) ~= "string" or key == "" then
		return nil
	end
	NAmanage.ESP_CancelScanToken(key)
	const tok = NAmanage.NewCancelToken()
	NAStuff.espScanTokens[key] = tok
	return tok
end

NAmanage.ESP_ListAdd = NAmanage.ESP_ListAdd or function(list, indexMap, item)
	if type(list) ~= "table" or type(indexMap) ~= "table" or item == nil then
		return false
	end
	if indexMap[item] then
		return false
	end
	const n = #list + 1
	list[n] = item
	indexMap[item] = n
	return true
end

NAmanage.ESP_ListRemove = NAmanage.ESP_ListRemove or function(list, indexMap, item)
	if type(list) ~= "table" or type(indexMap) ~= "table" or item == nil then
		return false
	end
	const idx = indexMap[item]
	if not idx then
		return false
	end
	const lastIdx = #list
	const lastItem = list[lastIdx]
	list[lastIdx] = nil
	indexMap[item] = nil
	if idx < lastIdx then
		list[idx] = lastItem
		indexMap[lastItem] = idx
	end
	return true
end

NAmanage.ESP_GetListMeta = NAmanage.ESP_GetListMeta or function(list)
	if type(list) ~= "table" then
		return nil
	end
	local store = NAStuff and NAStuff.genericESPListMeta
	if type(store) ~= "table" then
		store = NAmanage.ensureWeakTable(nil, "k")
		NAStuff.genericESPListMeta = store
	else
		store = NAmanage.ensureWeakTable(store, "k")
		NAStuff.genericESPListMeta = store
	end
	local meta = store[list]
	if type(meta) ~= "table" then
		meta = {
			index = {};
			counts = {};
			objects = {};
		}
		store[list] = meta
	end
	if type(meta.index) ~= "table" then
		meta.index = {}
	end
	if type(meta.counts) ~= "table" then
		meta.counts = {}
	end
	if type(meta.objects) ~= "table" then
		meta.objects = {}
	end
	return meta
end

NAmanage.ESP_GetListMap = NAmanage.ESP_GetListMap or function(list)
	const meta = NAmanage.ESP_GetListMeta(list)
	return meta and meta.index or nil
end

NAmanage.ESP_GetListCountMap = NAmanage.ESP_GetListCountMap or function(list)
	const meta = NAmanage.ESP_GetListMeta(list)
	return meta and meta.counts or nil
end

NAmanage.ESP_GetListObjectMap = NAmanage.ESP_GetListObjectMap or function(list)
	const meta = NAmanage.ESP_GetListMeta(list)
	return meta and meta.objects or nil
end

NAlib.huiGrabber = function()
	if __NAUIProtector and type(__NAUIProtector.huiGrabber) == "function" then
		local ok, hidden = pcall(__NAUIProtector.huiGrabber)
		if ok and typeof(hidden) == "Instance" then
			return hidden
		end
	end
	return (gethui and gethui()) or
		(gethiddenui and gethiddenui()) or
		(gethiddengui and gethiddengui()) or
		(get_hidden_ui and get_hidden_ui()) or
		(get_hidden_gui and get_hidden_gui()) or
		nil
end

NAlib.distinctHuiGrabber = NAlib.distinctHuiGrabber or function(coreRoot)
	return NAlib.huiGrabber and NAlib.huiGrabber() or nil
end


NAmanage.ResolveExperienceService = NAmanage.ResolveExperienceService or function()
	local service = Services.ExperienceService
	if service then
		return service
	end
	local ok, resolved = pcall(function()
		return SafeGetService("ExperienceService")
	end)
	if ok and resolved then
		Services.ExperienceService = resolved
		return resolved
	end
	return nil
end

NAmanage.ExperienceServiceLaunch = NAmanage.ExperienceServiceLaunch or function(params, opts)
	params = type(params) == "table" and params or { placeId = params }
	opts = type(opts) == "table" and opts or {}
	const launchParams = {}
	for key, value in params do
		if value ~= nil then
			launchParams[key] = value
		end
	end
	const service = NAmanage.ResolveExperienceService()
	if not service then
		return false, "ExperienceService unavailable"
	end
	local launchGui
	if type(NAmanage.TeleportGui_Create) == "function" and opts.skipGui ~= true then
		const placeId = launchParams.placeId or launchParams.PlaceId or game.PlaceId
		launchGui = NAmanage.TeleportGui_Create(
			placeId,
			opts.placeName or (type(NAmanage.TeleportGui_GetPlaceName) == "function" and NAmanage.TeleportGui_GetPlaceName(placeId) or nil),
			opts.action or "TELEPORTING",
			opts.detail
		)
	end
	local ok, result = pcall(function()
		if opts.callback and service.LaunchExperienceFromSourceWithCallback then
			return service:LaunchExperienceFromSourceWithCallback(launchParams, opts.source or "NamelessAdmin", opts.callback)
		end
		if opts.source and service.LaunchExperienceFromSource then
			return service:LaunchExperienceFromSource(launchParams, opts.source)
		end
		return service:LaunchExperience(launchParams)
	end)
	if not ok and launchGui and type(NAmanage.TeleportGui_Clear) == "function" then
		pcall(NAmanage.TeleportGui_Clear, launchGui)
	end
	return ok, result
end

NAmanage.TeleportArgsToExperienceParams = NAmanage.TeleportArgsToExperienceParams or function(method, args, meta)
	args = type(args) == "table" and args or {}
	meta = type(meta) == "table" and meta or {}
	const params = {}
	const placeId = tonumber(meta.placeId or args[1])
	if placeId then
		params.placeId = placeId
	end
	if method == "TeleportToPlaceInstance" then
		const instanceId = args[2]
		if instanceId ~= nil and tostring(instanceId) ~= "" then
			params.gameInstanceId = tostring(instanceId)
		end
	elseif method == "TeleportToPrivateServer" then
		const accessCode = args[2]
		if accessCode ~= nil and tostring(accessCode) ~= "" then
			params.reservedServerAccessCode = tostring(accessCode)
		end
	elseif method == "TeleportAsync" then
		const teleportOptions = args[3]
		if typeof(teleportOptions) == "Instance" then
			pcall(function()
				const instanceId = teleportOptions.ServerInstanceId
				if instanceId and tostring(instanceId) ~= "" then
					params.gameInstanceId = tostring(instanceId)
				end
			end)
			pcall(function()
				const accessCode = teleportOptions.ReservedServerAccessCode
				if accessCode and tostring(accessCode) ~= "" then
					params.reservedServerAccessCode = tostring(accessCode)
				end
			end)
		end
	end
	if type(meta.experienceParams) == "table" then
		for key, value in meta.experienceParams do
			if value ~= nil then
				params[key] = value
			end
		end
	end
	if next(params) == nil then
		return nil
	end
	return params
end

NAmanage.RegisterTeleportFallback = NAmanage.RegisterTeleportFallback or function(method, args, meta)
	const params = NAmanage.TeleportArgsToExperienceParams(method, args, meta)
	if not params then
		return nil
	end
	const token = tostring(os.clock())..":"..tostring(math.random(1, 1e9))
	NAStuff.TeleportExperienceFallback = {
		token = token;
		params = params;
		opts = type(meta) == "table" and {
			placeName = meta.placeName;
			action = meta.action;
			detail = meta.detail;
			source = meta.source;
			callback = meta.callback;
		} or {};
		method = method;
		startedAt = os.clock();
	}
	Delay(35, function()
		const pending = NAStuff.TeleportExperienceFallback
		if pending and pending.token == token then
			NAStuff.TeleportExperienceFallback = nil
		end
	end)
	return token
end

NAmanage.TryExperienceFallback = NAmanage.TryExperienceFallback or function(reason, expectedToken)
	const pending = NAStuff.TeleportExperienceFallback
	if type(pending) ~= "table" then
		return false, "No pending ExperienceService fallback"
	end
	if expectedToken and pending.token ~= expectedToken then
		return false, "Teleport fallback token changed"
	end
	if os.clock() - (tonumber(pending.startedAt) or 0) > 35 then
		NAStuff.TeleportExperienceFallback = nil
		return false, "Teleport fallback expired"
	end
	NAStuff.TeleportExperienceFallback = nil
	const opts = type(pending.opts) == "table" and pending.opts or {}
	if reason and tostring(reason) ~= "" then
		opts.detail = opts.detail and (tostring(opts.detail).." | TeleportService failed") or "TeleportService failed"
	end
	local ok, result = NAmanage.ExperienceServiceLaunch(pending.params, opts)
	if ok then
		DebugNotif("TeleportService failed; ExperienceService fallback launched.", 3)
		return true, result
	end
	return false, result
end

NAmanage.LaunchExperience = function(params, opts)
	return NAmanage.ExperienceServiceLaunch(params, opts)
end

NAmanage.ExperienceDebugValue = NAmanage.ExperienceDebugValue or function(value, depth, seen)
	depth = depth or 0
	if depth > 2 then return "..." end
	const valueType = typeof(value)
	if valueType ~= "table" then
		return tostring(value)
	end
	seen = seen or {}
	if seen[value] then return "<cycle>" end
	seen[value] = true
	const parts = {}
	local count = 0
	for key, inner in value do
		count += 1
		if count > 10 then
			parts[#parts + 1] = "..."
			break
		end
		parts[#parts + 1] = tostring(key).."="..NAmanage.ExperienceDebugValue(inner, depth + 1, seen)
	end
	seen[value] = nil
	return "{"..Concat(parts, ", ").."}"
end

NAmanage.ExperienceDebugSnapshot = NAmanage.ExperienceDebugSnapshot or function(label)
	local service = Services.ExperienceService
	if not service then
		local ok, resolved = pcall(function()
			return SafeGetService("ExperienceService")
		end)
		if ok and resolved then
			Services.ExperienceService = resolved
			service = resolved
		end
	end
	if not service then
		DebugNotif((label or "ExperienceService")..": unavailable", 4)
		return false
	end
	const parts = {}
	const probes = {
		{"state", "GetPlaceJoinState"},
		{"queue", "GetQueuePosition"},
		{"pending", "GetPendingJoinAttempt"},
		{"followUserId", "GetFollowUserId"},
	}
	for _, probe in probes do
		const key, method = probe[1], probe[2]
		const fn = service[method]
		if type(fn) == "function" then
			local ok, value = pcall(function()
				return fn(service)
			end)
			parts[#parts + 1] = key.."="..(ok and NAmanage.ExperienceDebugValue(value) or ("ERR:"..tostring(value)))
		end
	end
	local text = (label or "ExperienceService")..": "..(#parts > 0 and Concat(parts, " | ") or "no readable state")
	if text:find("queue=-1", 1, true) then
		text = text.." | queue=-1 means no queue position reported"
	end
	DebugNotif(text, 6)
	return true, text
end

NAmanage.ExperienceDebugRecord = NAmanage.ExperienceDebugRecord or function(name, valuesText)
	NAStuff.ExperienceDebugEvents = NAStuff.ExperienceDebugEvents or {}
	const events = NAStuff.ExperienceDebugEvents
	events[#events + 1] = {
		t = os.clock(),
		name = tostring(name or ""),
		values = tostring(valuesText or ""),
	}
	while #events > 20 do
		table.remove(events, 1)
	end
end

NAmanage.ExperienceDebugConnect = NAmanage.ExperienceDebugConnect or function()
	if NAStuff.ExperienceDebugConnected then
		return true
	end
	local service = Services.ExperienceService
	if not service then
		pcall(function()
			service = SafeGetService("ExperienceService")
		end)
		if service then Services.ExperienceService = service end
	end
	if not service then
		DebugNotif("ExperienceService debug unavailable", 4)
		return false
	end
	NAStuff.ExperienceDebugConnected = true
	const function dbg(name, ...)
		const values = {}
		for i = 1, select("#", ...) do
			values[#values + 1] = NAmanage.ExperienceDebugValue(select(i, ...))
		end
		const valuesText = Concat(values, " | ")
		NAmanage.ExperienceDebugRecord(name, valuesText)
		DebugNotif("[ExperienceDebug] "..name..": "..valuesText, 6)
	end
	const eventNames = {"OnNewJoinAttempt", "PlaceJoinStateChanged", "QueuePositionChanged", "OnCrossExperienceStarted", "OnCrossExperienceStopped"}
	for _, eventName in eventNames do
		const event = service[eventName]
		if event and event.Connect then
			pcall(function()
				NAlib.connect("experience_debug_"..eventName, event:Connect(function(...)
					dbg(eventName, ...)
				end))
			end)
		end
	end
	const registerNames = {"RegisterForExperienceJoin", "RegisterForExperienceLeave"}
	for _, methodName in registerNames do
		const fn = service[methodName]
		if type(fn) == "function" then
			pcall(function()
				const conn = fn(service, function(...)
					dbg(methodName, ...)
				end)
				if conn and conn.Disconnect then
					NAlib.connect("experience_debug_"..methodName, conn)
				end
			end)
		end
	end
	if Services.LogService and Services.LogService.MessageOut then
		pcall(function()
			NAlib.connect("experience_debug_log", Services.LogService.MessageOut:Connect(function(message, messageType)
				const lowerMessage = Lower(tostring(message or ""))
				if lowerMessage:find("experience") or lowerMessage:find("launch") or lowerMessage:find("queue") or lowerMessage:find("notificationtype") then
					dbg("LogService", tostring(message), tostring(messageType))
				end
			end))
		end)
	end
	DebugNotif("ExperienceService debug hooks enabled.", 4)
	NAmanage.ExperienceDebugSnapshot("ExperienceDebug connected")
	return true
end

NAmanage.GetDataPingStat = NAmanage.GetDataPingStat or function()
	local ok, pingStat = pcall(function()
		if not Services.Stats then
			return nil
		end

		const network = Services.Stats:FindFirstChild("Network")
		if not network then
			return nil
		end

		const serverStats = network:FindFirstChild("ServerStatsItem")
		if serverStats then
			const nested = serverStats:FindFirstChild("Data Ping")
			if nested then
				return nested
			end
		end

		return network:FindFirstChild("Data Ping")
	end)

	if ok then
		return pingStat
	end

	return nil
end

NAmanage.GetDataPingMs = NAmanage.GetDataPingMs or function()
	const pingStat = NAmanage.GetDataPingStat()
	if not pingStat then
		return nil
	end

	local okValue, value = pcall(function()
		if pingStat.GetValue then
			return pingStat:GetValue()
		end
	end)
	if okValue and type(value) == "number" then
		return math.max(0, math.floor(value + 0.5))
	end

	local okString, str = pcall(function()
		if pingStat.GetValueString then
			return pingStat:GetValueString()
		end
	end)
	if okString and type(str) == "string" then
		const num = tonumber((str:gsub("[^%d%.]", "")))
		if num then
			return math.max(0, math.floor(num + 0.5))
		end
	end

	return nil
end

NAmanage.GetDataPingText = NAmanage.GetDataPingText or function()
	const pingStat = NAmanage.GetDataPingStat()
	if not pingStat then
		return nil
	end

	const ms = NAmanage.GetDataPingMs()
	if type(ms) == "number" then
		return Format("%d ms", math.floor(ms + 0.5)), ms
	end

	local okString, str = pcall(function()
		if pingStat.GetValueString then
			return pingStat:GetValueString()
		end
	end)
	if okString and type(str) == "string" and str ~= "" then
		return str, nil
	end

	return nil
end

NAmanage.StreamerEscapePattern = function(value)
	return tostring(value or ""):gsub("([%%%^%$%(%)%.%[%]%*%+%-%?])", "%%%1")
end

NAmanage.StreamerGetState = function()
	local state = NAStuff.StreamerModeState
	if type(state) ~= "table" then
		state = {}
		NAStuff.StreamerModeState = state
	end
	if not state.ready then
		state.cache = NAmanage.ensureWeakTable(state.cache, "k")
		state.overlays = NAmanage.ensureWeakTable(nil, "k")
		state.names = {}
		state.nameTokens = {}
		state.trie = {}
		state.rev = 0
		state.ready = true
	end
	return state
end

NAmanage.StreamerSetPlayerListHidden = function(hidden)
	const state = NAmanage.StreamerGetState()
	if hidden then
		if state.playerListOriginal == nil then
			const ok, value = pcall(__lt.cm, "StarterGui", "GetCoreGuiEnabled", Enum.CoreGuiType.PlayerList)
			if not ok then return false end
			state.playerListOriginal = value
		end
		const ok = pcall(__lt.cm, "StarterGui", "SetCoreGuiEnabled", Enum.CoreGuiType.PlayerList, false)
		state.playerListHidden = ok
		return ok
	end
	if state.playerListOriginal ~= nil then
		const ok = pcall(__lt.cm, "StarterGui", "SetCoreGuiEnabled", Enum.CoreGuiType.PlayerList, state.playerListOriginal)
		if not ok then return false end
	end
	state.playerListOriginal = nil
	state.playerListHidden = nil
	return true
end

NAmanage.StreamerCacheCount = function(cache)
	local count = 0
	for _ in cache or {} do count += 1 end
	return count
end

NAmanage.StreamerIsRunActive = function(token)
	return NAStuff.StreamerModeEnabled == true and (token == nil or (not token.cancelled and NAmanage.StreamerGetState().token == token))
end

NAmanage.StreamerGetRecord = function(inst)
	if typeof(inst) ~= "Instance" then return end
	const cache = NAmanage.StreamerGetState().cache
	local rec = cache[inst]
	if not rec then
		rec = { props = {}, links = {} }
		cache[inst] = rec
	end
	rec.props = rec.props or {}
	rec.links = rec.links or {}
	return rec
end

NAmanage.StreamerAddName = function(name)
	if type(name) ~= "string" or name == "" then return false end
	const state = NAmanage.StreamerGetState()
	const key = string.lower(name)
	if state.names[key] then return false end
	state.names[key] = true
	state.nameTokens[#state.nameTokens + 1] = key
	local node = state.trie
	for i = 1, #key do
		const byte = string.byte(key, i)
		node[byte] = node[byte] or {}
		node = node[byte]
	end
	node.done = true
	state.rev += 1
	return true
end

NAmanage.StreamerTrackIdentity = function(info)
	if not NAStuff.StreamerModeEnabled or type(info) ~= "table" then return end
	local changed = false
	for _, key in { "username", "displayName", "authorUsername", "moderationUsername", "fromName" } do
		if NAmanage.StreamerAddName(info[key]) then changed = true end
	end
	if type(info.reply) == "table" then
		if NAmanage.StreamerAddName(info.reply.username) then changed = true end
		if NAmanage.StreamerAddName(info.reply.displayName) then changed = true end
	end
	if changed then NAmanage.StreamerScheduleNameRefresh(true) end
end

NAmanage.StreamerRefreshNameTokens = function(chat)
	if Services.Players then
		for _, plr in __lt.cm("Players", "GetPlayers") do
			NAmanage.StreamerAddName(plr.Name)
			NAmanage.StreamerAddName(plr.DisplayName)
		end
	end
	if chat ~= false and type(NAmanage.StreamerGetChatNames) == "function" then
		pcall(NAmanage.StreamerGetChatNames, NAmanage.StreamerAddName)
	end
	return NAmanage.StreamerGetState().nameTokens
end

NAmanage.StreamerScheduleNameRefresh = function(refresh)
	const state = NAmanage.StreamerGetState()
	const token = state.token
	if not NAmanage.StreamerIsRunActive(token) then return end
	if refresh then state.refresh = true end
	if state.nameJob then return end
	const job = {}
	state.nameJob = job
	Delay(0.05, function()
		if state.nameJob ~= job then return end
		state.nameJob = nil
		if not NAmanage.StreamerIsRunActive(token) then return end
		NAmanage.StreamerRefreshNameTokens(false)
		if state.refresh then
			state.refresh = false
			NAmanage.StreamerRefreshCachedTargets()
		end
	end)
end

NAmanage.StreamerRefreshCachedTargets = function()
	const state = NAmanage.StreamerGetState()
	const token = state.token
	if not NAmanage.StreamerIsRunActive(token) then return end
	if state.refreshJob then state.refreshAgain = true; return end
	const job = {}
	state.refreshJob = job
	Spawn(function()
		repeat
			state.refreshAgain = false
			const work = {}
			for inst in state.cache do
				if not NAmanage.StreamerIsRunActive(token) then break end
				if inst.Parent and NAmanage.StreamerIsTarget(inst) then
					NAmanage.StreamerScrubInstance(inst)
					NAmanage.WorkBudgetStep(work, 48, 0.002)
				end
			end
		until not state.refreshAgain or not NAmanage.StreamerIsRunActive(token)
		if NAmanage.StreamerIsRunActive(token) and NAmanage.StreamerChatChanged then pcall(NAmanage.StreamerChatChanged) end
		if state.refreshJob == job then state.refreshJob = nil end
	end)
end

NAmanage.StreamerTextRanges = function(text)
	const trie = NAmanage.StreamerGetState().trie
	const lower = string.lower(text)
	const ranges = {}
	const function word(byte)
		return byte and ((byte >= 48 and byte <= 57) or (byte >= 97 and byte <= 122) or byte == 95 or byte >= 128)
	end
	local i = 1
	while i <= #text do
		local last
		if not word(string.byte(lower, i - 1)) then
			local node = trie
			local j = i
			while j <= #text do
				node = node[string.byte(lower, j)]
				if not node then break end
				if node.done and not word(string.byte(lower, j + 1)) then last = j end
				j += 1
			end
		end
		if last then
			ranges[#ranges + 1] = { i, last }
			i = last + 1
		else
			i += 1
		end
	end
	return ranges
end

NAmanage.StreamerMaskText = function(text, rich)
	if text == nil then return nil end
	const source = tostring(text)
	const state = NAmanage.StreamerGetState()
	if #state.nameTokens == 0 or source == "" then return source end
	local rep = tostring(NAStuff.StreamerModeText or "User")
	const parts, plain = {}, {}
	local count, at = 0, 1
	const entities = { amp = "&", lt = "<", gt = ">", quot = '"', apos = "'" }
	const function add(raw, value)
		parts[#parts + 1] = { raw = raw, text = value, first = count + 1 }
		if value then count += #value; plain[#plain + 1] = value end
	end
	if rich then
		while at <= #source do
			const start = source:find("[<&]", at)
			if not start then add(source:sub(at), source:sub(at)); break end
			if start > at then add(source:sub(at, start - 1), source:sub(at, start - 1)) end
			local last, value
			if source:sub(start, start) == "<" then
				local quote
				for i = start + 1, #source do
					const ch = source:sub(i, i)
					if quote then
						if ch == quote then quote = nil end
					elseif ch == '"' or ch == "'" then quote = ch
					elseif ch == ">" then last = i; break end
				end
				if last then
					const tag = source:sub(start, last)
					if tag:match("^<%s*br%s*/?%s*>$") then value = "\n" end
					add(tag, value)
				end
			else
				const key = source:match("^&([%w#]+);", start)
				value = key and entities[key]
				if key and not value and key:sub(1, 1) == "#" then
					local n = key:sub(2, 2):lower() == "x" and tonumber(key:sub(3), 16) or tonumber(key:sub(2))
					if n and n >= 0 and n <= 0x10ffff then
						const ok, char = pcall(utf8.char, n)
						if ok then value = char end
					end
				end
				if value then last = start + #key + 1; add(source:sub(start, last), value) end
			end
			if not last then add(source:sub(start, start), source:sub(start, start)); last = start end
			at = last + 1
		end
		rep = rep:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
	else
		add(source, source)
	end
	const ranges = NAmanage.StreamerTextRanges(table.concat(plain))
	if #ranges == 0 then return source end
	const out = {}
	local ri = 1
	for _, part in parts do
		if not part.text then
			out[#out + 1] = part.raw
		else
			local pos = part.first
			const last = pos + #part.text - 1
			while pos <= last do
				local range = ranges[ri]
				if range and pos > range[2] then ri += 1
				elseif range and pos >= range[1] then
					if pos == range[1] then out[#out + 1] = rep end
					pos = math.min(last + 1, range[2] + 1)
				else
					const endAt = range and math.min(last, range[1] - 1) or last
					if part.raw ~= part.text then out[#out + 1] = part.raw
					else out[#out + 1] = part.text:sub(pos - part.first + 1, endAt - part.first + 1) end
					pos = endAt + 1
				end
			end
		end
	end
	return table.concat(out)
end

NAmanage.StreamerShouldMaskImage = function(image)
	const value = string.lower(tostring(image or ""))
	if value:sub(1, 11) == "rbxthumb://" then
		const kind = value:match("[?&/]?type=([^&]+)")
		return kind == "avatar" or kind == "avatarheadshot" or kind == "avatarbust"
	end
	return value:find("/users/", 1, true) ~= nil and (value:find("avatar", 1, true) ~= nil or value:find("thumbnail", 1, true) ~= nil)
		or value:find("headshot", 1, true) ~= nil
end

NAmanage.StreamerIsContainer = function(inst)
	return typeof(inst) == "Instance" and (inst:IsA("BillboardGui") or inst:IsA("SurfaceGui"))
end

NAmanage.StreamerIsTarget = function(inst)
	if typeof(inst) ~= "Instance" or NAmanage.StreamerGetState().overlays[inst] then return false end
	const kind = inst.ClassName
	if kind == "ImageLabel" or kind == "ImageButton" then return true end
	if kind ~= "TextLabel" and kind ~= "TextButton" and kind ~= "TextBox" then return false end
	const font = NAlib.isProperty(inst, "FontFace")
	const family = font and NAlib.isProperty(font, "Family")
	return not (type(family) == "string" and family:find("BuilderIcons", 1, true))
end

NAmanage.StreamerIsRelevant = function(inst)
	return NAmanage.StreamerIsTarget(inst) or NAmanage.StreamerIsContainer(inst)
end

NAmanage.StreamerDisconnectConn = function(conn)
	if conn then pcall(function() conn:Disconnect() end) end
end

NAmanage.StreamerInScope = function(inst)
	if not inst.Parent then return false end
	const state = NAmanage.StreamerGetState()
	for _, root in state.roots or {} do
		if root ~= Services.Workspace and (inst == root or inst:IsDescendantOf(root)) then return true end
	end
	return Services.Workspace and inst:IsDescendantOf(Services.Workspace)
		and (inst:FindFirstAncestorOfClass("BillboardGui") ~= nil or inst:FindFirstAncestorOfClass("SurfaceGui") ~= nil)
end

NAmanage.StreamerWatchTarget = function(inst)
	const rec = NAmanage.StreamerGetRecord(inst)
	if rec.links.text then return end
	if inst:IsA("TextBox") then
		rec.links.text = inst.Changed:Connect(function(prop)
			if not rec.busy and NAmanage.StreamerIsRunActive() and NAmanage.StreamerBoxProps[prop] then NAmanage.StreamerScrubInstance(inst) end
		end)
	else
		const prop = (inst:IsA("ImageLabel") or inst:IsA("ImageButton")) and "Image" or "Text"
		rec.links.text = inst:GetPropertyChangedSignal(prop):Connect(function()
			if not rec.busy then NAmanage.StreamerScrubInstance(inst) end
		end)
		if prop == "Text" then
			rec.links.rich = inst:GetPropertyChangedSignal("RichText"):Connect(function()
				if not rec.busy then NAmanage.StreamerScrubInstance(inst) end
			end)
		end
	end
	rec.links.anc = inst.AncestryChanged:Connect(function()
		if not NAmanage.StreamerInScope(inst) then NAmanage.StreamerRestoreInstance(inst) end
	end)
end

NAmanage.StreamerScanContainer = function(root, token, opts)
	if typeof(root) ~= "Instance" or not NAmanage.StreamerIsRunActive(token) then return end
	opts = opts or {}
	const work = {}
	const query = root == Services.Workspace and "BillboardGui >> GuiObject, SurfaceGui >> GuiObject" or "TextLabel, TextButton, TextBox, ImageLabel, ImageButton"
	if opts.includeRoot and NAmanage.StreamerIsTarget(root) then NAmanage.StreamerScrubInstance(root) end
	for _, inst in NAmanage.QueryDescendants(root, query) do
		if not NAmanage.StreamerIsRunActive(token) then break end
		if inst.Parent and NAmanage.StreamerIsTarget(inst) then NAmanage.StreamerScrubInstance(inst) end
		NAmanage.WorkBudgetStep(work, tonumber(opts.yieldEvery) or 64, 0.002)
	end
end

-- PART 2 --
NAmanage.StreamerScanContainerAsync = function(root, opts)
	if typeof(root) ~= "Instance" then return end
	opts = opts or {}
	const state = NAmanage.StreamerGetState()
	const token = opts.cancelToken or state.token
	if not NAmanage.StreamerIsRunActive(token) then return end
	const rec = NAmanage.StreamerGetRecord(root)
	if rec.scanToken == token then return end
	rec.scanToken = token
	Spawn(function()
		if NAmanage.StreamerIsRunActive(token) then NAmanage.StreamerScanContainer(root, token, opts) end
		if rec.scanToken == token then rec.scanToken = nil end
	end)
end

NAmanage.StreamerWatchContainer = function(container)
	NAmanage.StreamerScanContainerAsync(container)
end

NAmanage.StreamerApplyProp = function(inst, prop, value)
	if not NAmanage.StreamerIsRunActive() then return false end
	const current = NAlib.isProperty(inst, prop)
	if current == nil then return false end
	const rec = NAmanage.StreamerGetRecord(inst)
	const orig, applied = prop .. "Original", prop .. "Applied"
	if rec[applied] == nil or current ~= rec[applied] then rec[orig] = current end
	rec[applied] = value
	if current == value or NAlib.setProperty(inst, prop, value) then
		rec.props[prop] = value
		return true
	end
	rec[orig], rec[applied], rec.props[prop] = nil, nil, nil
	return false
end

NAmanage.StreamerReleaseProp = function(inst, rec, prop)
	const orig, applied = prop .. "Original", prop .. "Applied"
	const current = NAlib.isProperty(inst, prop)
	if rec[orig] ~= nil and current ~= nil and current == rec[applied] and current ~= rec[orig] then
		if not NAlib.setProperty(inst, prop, rec[orig]) then return false end
	end
	rec[orig], rec[applied], rec.props[prop] = nil, nil, nil
	return true
end

NAmanage.StreamerApplyCharacterVisual = function(inst)
	if not NAmanage.StreamerIsRunActive() or typeof(inst) ~= "Instance" then return end
	const gray = NAStuff.StreamerModeGray
	const rec = NAmanage.StreamerGetRecord(inst)
	if rec.busy then return end
	rec.busy = true
	if inst:IsA("BasePart") then
		if inst:FindFirstAncestorOfClass("Accessory") then
			NAmanage.StreamerApplyProp(inst, "LocalTransparencyModifier", 1)
		else
			NAmanage.StreamerReleaseProp(inst, rec, "LocalTransparencyModifier")
			NAmanage.StreamerApplyProp(inst, "Color", gray)
			NAmanage.StreamerApplyProp(inst, "Material", Enum.Material.SmoothPlastic)
			NAmanage.StreamerApplyProp(inst, "Reflectance", 0)
			if inst:IsA("MeshPart") then NAmanage.StreamerApplyProp(inst, "TextureID", "") end
		end
	elseif inst:IsA("Decal") or inst:IsA("Texture") then
		NAmanage.StreamerApplyProp(inst, "Transparency", 1)
	elseif inst:IsA("CharacterMesh") then
		NAmanage.StreamerApplyProp(inst, "BaseTextureId", 0)
		NAmanage.StreamerApplyProp(inst, "OverlayTextureId", 0)
	elseif inst:IsA("DataModelMesh") then
		NAmanage.StreamerApplyProp(inst, "TextureId", "")
		NAmanage.StreamerApplyProp(inst, "VertexColor", Vector3.new(gray.R, gray.G, gray.B))
	elseif inst:IsA("Shirt") then
		NAmanage.StreamerApplyProp(inst, "ShirtTemplate", "")
	elseif inst:IsA("Pants") then
		NAmanage.StreamerApplyProp(inst, "PantsTemplate", "")
	elseif inst:IsA("ShirtGraphic") then
		NAmanage.StreamerApplyProp(inst, "Graphic", "")
	elseif inst:IsA("BodyColors") then
		for _, prop in { "HeadColor3", "LeftArmColor3", "RightArmColor3", "LeftLegColor3", "RightLegColor3", "TorsoColor3" } do
			NAmanage.StreamerApplyProp(inst, prop, gray)
		end
	end
	rec.busy = false
	if NAmanage.StreamerIsRunActive() and NAmanage.StreamerGetState().cache[inst] == rec and next(rec.props) and not rec.links.visual then
		rec.links.visual = inst.Changed:Connect(function(prop)
			if not rec.busy and rec.props[prop] ~= nil then NAmanage.StreamerApplyCharacterVisual(inst) end
		end)
	end
end

NAmanage.StreamerApplyHumanoid = function(hum)
	if not NAmanage.StreamerIsRunActive() or not hum:IsA("Humanoid") then return end
	const rec = NAmanage.StreamerGetRecord(hum)
	if rec.busy then return end
	rec.busy = true
	NAmanage.StreamerApplyProp(hum, "DisplayDistanceType", Enum.HumanoidDisplayDistanceType.None)
	NAmanage.StreamerApplyProp(hum, "NameDisplayDistance", 0)
	NAmanage.StreamerApplyProp(hum, "DisplayName", tostring(NAStuff.StreamerModeText or "User"))
	rec.busy = false
	if NAmanage.StreamerIsRunActive() and NAmanage.StreamerGetState().cache[hum] == rec and not rec.links.visual then
		rec.links.visual = hum.Changed:Connect(function(prop)
			if not rec.busy and rec.props[prop] ~= nil then NAmanage.StreamerApplyHumanoid(hum) end
		end)
	end
end

NAmanage.StreamerHandleCharacterDesc = function(inst, token, char)
	if not NAmanage.StreamerIsRunActive(token) or not inst.Parent then return end
	if inst:IsA("Humanoid") then NAmanage.StreamerApplyHumanoid(inst)
	else NAmanage.StreamerApplyCharacterVisual(inst) end
	const state = NAmanage.StreamerGetState()
	const rec = state.cache[inst]
	if rec and char and (next(rec.props) or next(rec.links)) then
		if rec.char and rec.char ~= char then
			const old = state.cache[rec.char]
			if old and old.nodes then old.nodes[inst] = nil end
		end
		rec.char = char
		NAmanage.StreamerGetRecord(char).nodes[inst] = true
	end
	if rec and not next(rec.props) and not next(rec.links) then state.cache[inst] = nil end
end

NAmanage.StreamerHandleCharacter = function(char, token)
	if typeof(char) ~= "Instance" or not char:IsA("Model") then return end
	token = token or NAmanage.StreamerGetState().token
	if not NAmanage.StreamerIsRunActive(token) then return end
	const rec = NAmanage.StreamerGetRecord(char)
	if rec.charToken == token then return end
	for _, key in { "charAdd", "charRem", "charAnc" } do NAmanage.StreamerDisconnectConn(rec.links[key]) end
	rec.charToken = token
	rec.nodes = rec.nodes or NAmanage.ensureWeakTable(nil, "k")
	rec.links.charAdd = char.DescendantAdded:Connect(function(inst)
		NAmanage.StreamerHandleCharacterDesc(inst, token, char)
	end)
	rec.links.charRem = char.DescendantRemoving:Connect(function(inst)
		Defer(function()
			const live = NAmanage.StreamerGetState().cache[inst]
			if live and live.char == char and not inst:IsDescendantOf(char) then NAmanage.StreamerRestoreInstance(inst) end
		end)
	end)
	rec.links.charAnc = char.AncestryChanged:Connect(function(_, parent)
		if not parent then NAmanage.StreamerRestoreInstance(char) end
	end)
	const hum = char:FindFirstChildOfClass("Humanoid")
	if hum then NAmanage.StreamerHandleCharacterDesc(hum, token, char) end
	Spawn(function()
		const work = {}
		for _, inst in NAmanage.QueryDescendants(char, "BasePart, Humanoid, Decal, Texture, DataModelMesh, CharacterMesh, Shirt, Pants, ShirtGraphic, BodyColors") do
			if not NAmanage.StreamerIsRunActive(token) or rec.charToken ~= token then break end
			if inst:IsDescendantOf(char) then NAmanage.StreamerHandleCharacterDesc(inst, token, char) end
			NAmanage.WorkBudgetStep(work, 32, 0.002)
		end
	end)
end

NAmanage.StreamerApplyTextProp = function(inst, prop)
	const current = NAlib.isProperty(inst, prop)
	if type(current) ~= "string" then return end
	const rec = NAmanage.StreamerGetRecord(inst)
	const orig, applied = prop .. "Original", prop .. "Applied"
	if rec[applied] == nil or current ~= rec[applied] then rec[orig] = current; rec.rev = nil end
	const state = NAmanage.StreamerGetState()
	const rich = inst.RichText == true
	const rep = NAStuff.StreamerModeText
	if rec.rev ~= state.rev or rec.rich ~= rich or rec.rep ~= rep then
		rec.masked = NAmanage.StreamerMaskText(rec[orig], rich)
		rec.rev, rec.rich, rec.rep = state.rev, rich, rep
	end
	if rec.masked ~= rec[orig] then NAmanage.StreamerApplyProp(inst, "AutoLocalize", false)
	else NAmanage.StreamerReleaseProp(inst, rec, "AutoLocalize") end
	rec[applied] = rec.masked
	rec.props[prop] = rec.masked
	if current ~= rec.masked then NAlib.setProperty(inst, prop, rec.masked) end
end

NAmanage.StreamerBoxProps = {
	Text = true, PlaceholderText = true, PlaceholderColor3 = true, RichText = true,
	TextTransparency = true, TextStrokeTransparency = true, FontFace = true, TextSize = true,
	TextColor3 = true, TextStrokeColor3 = true, TextWrapped = true, TextScaled = true,
	TextXAlignment = true, TextYAlignment = true, LineHeight = true, TextTruncate = true,
	TextDirection = true, MaxVisibleGraphemes = true, ZIndex = true, ShowNativeInput = true,
}

NAmanage.StreamerApplyTextBox = function(inst)
	const rec = NAmanage.StreamerGetRecord(inst)
	const state = NAmanage.StreamerGetState()
	const source = inst.Text ~= "" and inst.Text or inst.PlaceholderText
	const rich = inst.RichText == true and inst.Text ~= ""
	if rec.input ~= source or rec.rev ~= state.rev or rec.rich ~= rich or rec.rep ~= NAStuff.StreamerModeText then
		rec.input = source
		rec.masked = NAmanage.StreamerMaskText(source, rich)
		rec.rev, rec.rich, rec.rep = state.rev, rich, NAStuff.StreamerModeText
	end
	if rec.masked == source then
		if rec.overlay then
			state.overlays[rec.overlay] = nil
			rec.overlay:Destroy()
			rec.overlay = nil
		end
		for _, prop in { "TextTransparency", "TextStrokeTransparency", "ShowNativeInput" } do
			NAmanage.StreamerReleaseProp(inst, rec, prop)
		end
		return
	end
	local label = rec.overlay
	if not label then
		label = InstanceNew("TextLabel")
		state.overlays[label] = true
		rec.overlay = label
		label.Name = "NAStreamerMask"
		label.BackgroundTransparency = 1
		label.BorderSizePixel = 0
		label.Size = UDim2.new(1, 0, 1, 0)
		label.Position = UDim2.new(0, 0, 0, 0)
		label.AnchorPoint = Vector2.new()
		label.ClipsDescendants = true
		label.AutoLocalize = false
		label.Active = false
		label.Selectable = false
		for _, child in inst:GetChildren() do
			if child:IsA("UIPadding") or child:IsA("UITextSizeConstraint") then child:Clone().Parent = label end
		end
		label.Parent = inst
	end
	for _, prop in { "FontFace", "TextSize", "TextColor3", "TextStrokeColor3", "TextWrapped", "TextScaled", "TextXAlignment", "TextYAlignment", "LineHeight", "TextTruncate", "TextDirection", "MaxVisibleGraphemes" } do
		const value = NAlib.isProperty(inst, prop)
		if value ~= nil then NAlib.setProperty(label, prop, value) end
	end
	NAmanage.StreamerApplyProp(inst, "TextTransparency", 1)
	NAmanage.StreamerApplyProp(inst, "TextStrokeTransparency", 1)
	NAmanage.StreamerApplyProp(inst, "ShowNativeInput", false)
	NAlib.setProperty(label, "TextTransparency", rec.TextTransparencyOriginal)
	NAlib.setProperty(label, "TextStrokeTransparency", rec.TextStrokeTransparencyOriginal)
	if inst.Text == "" then NAlib.setProperty(label, "TextColor3", inst.PlaceholderColor3) end
	NAlib.setProperty(label, "ZIndex", inst.ZIndex + 1)
	NAlib.setProperty(label, "RichText", rich)
	NAlib.setProperty(label, "Text", rec.masked)
end

NAmanage.StreamerApplyImageProp = function(inst)
	const current = NAlib.isProperty(inst, "Image")
	if type(current) ~= "string" then return end
	const rec = NAmanage.StreamerGetRecord(inst)
	if rec.ImageApplied == nil or current ~= rec.ImageApplied then rec.ImageOriginal = current end
	const value = NAmanage.StreamerShouldMaskImage(rec.ImageOriginal) and tostring(NAStuff.StreamerModeImage or "") or rec.ImageOriginal
	rec.ImageApplied = value
	rec.props.Image = value
	if current ~= value then NAlib.setProperty(inst, "Image", value) end
end

NAmanage.StreamerScrubInstance = function(inst)
	if not NAmanage.StreamerIsRunActive() or not NAmanage.StreamerIsTarget(inst) or not NAmanage.StreamerInScope(inst) then return end
	const rec = NAmanage.StreamerGetRecord(inst)
	if rec.busy then return end
	NAmanage.StreamerWatchTarget(inst)
	rec.busy = true
	if inst:IsA("TextBox") then NAmanage.StreamerApplyTextBox(inst)
	elseif inst:IsA("ImageLabel") or inst:IsA("ImageButton") then NAmanage.StreamerApplyImageProp(inst)
	else NAmanage.StreamerApplyTextProp(inst, "Text") end
	rec.busy = false
end

NAmanage.StreamerRestoreInstance = function(inst)
	const state = NAmanage.StreamerGetState()
	const rec = state.cache[inst]
	if not rec then return true end
	rec.busy = true
	rec.links = rec.links or {}
	for _, conn in rec.links do NAmanage.StreamerDisconnectConn(conn) end
	table.clear(rec.links)
	for _, conn in rec.signalConns or {} do NAmanage.StreamerDisconnectConn(conn) end
	for _, key in { "ancConn", "charDescConn", "charAncConn", "containerDescConn", "containerAncConn" } do NAmanage.StreamerDisconnectConn(rec[key]); rec[key] = nil end
	rec.scanToken, rec.charToken, rec.charScanToken = nil, nil, nil
	if rec.overlay then
		state.overlays[rec.overlay] = nil
		rec.overlay:Destroy()
		rec.overlay = nil
	end
	if rec.nodes then
		for child in rec.nodes do NAmanage.StreamerRestoreInstance(child) end
		table.clear(rec.nodes)
	end
	if rec.char then
		const owner = state.cache[rec.char]
		if owner and owner.nodes then owner.nodes[inst] = nil end
		rec.char = nil
	end
	local failed = false
	const props = {}
	for key in rec do
		if type(key) == "string" and key:sub(-8) == "Original" then props[#props + 1] = key:sub(1, -9) end
	end
	for _, prop in props do
		if not NAmanage.StreamerReleaseProp(inst, rec, prop) then failed = true end
	end
	rec.busy = false
	if not failed then state.cache[inst] = nil end
	return not failed
end

NAmanage.StreamerGetRoots = function(opts)
	const roots = {}
	const function add(root)
		if typeof(root) ~= "Instance" then return end
		for _, other in roots do if root == other or root:IsDescendantOf(other) then return end end
		for i = #roots, 1, -1 do if roots[i]:IsDescendantOf(root) then table.remove(roots, i) end end
		roots[#roots + 1] = root
	end
	add(Services.CoreGui)
	const hub = NAmanage._pgHubGet and NAmanage._pgHubGet()
	add(hub and hub.root)
	add(NAlib.distinctHuiGrabber and NAlib.distinctHuiGrabber(Services.CoreGui))
	add(NAmanage.getUI and NAmanage.getUI())
	if opts and opts.includeWorkspace then add(Services.Workspace) end
	return roots
end

NAmanage.StreamerScrubAll = function(token, opts)
	const state = NAmanage.StreamerGetState()
	if state.scanJob == token then return end
	state.scanJob = token
	Spawn(function()
		for _, root in state.roots or {} do
			if not NAmanage.StreamerIsRunActive(token) then break end
			NAmanage.StreamerScanContainer(root, token, opts)
		end
		if state.scanJob == token then state.scanJob = nil end
	end)
end

NAmanage.StreamerSortRestorePending = function(pending) return pending end
NAmanage.StreamerGetPriorityRoots = function() return NAmanage.StreamerGetRoots() end
NAmanage.StreamerRestorePriority = function(opts)
	const roots = opts and opts.roots or NAmanage.StreamerGetPriorityRoots()
	local count = 0
	for inst in NAmanage.StreamerGetState().cache do
		for _, root in roots do
			if inst == root or inst:IsDescendantOf(root) then NAmanage.StreamerRestoreInstance(inst); count += 1; break end
		end
	end
	return count
end

NAmanage.StreamerRestoreAll = function(opts)
	opts = opts or {}
	const state = NAmanage.StreamerGetState()
	NAmanage.CancelTokenCancel(state.restoreToken)
	const token = NAmanage.NewCancelToken()
	state.restoreToken = token
	const pending = {}
	for inst in state.cache do pending[#pending + 1] = inst end
	const function restore()
		const work = {}
		local count = 0
		for _, inst in pending do
			if token.cancelled or state.restoreToken ~= token then break end
			if NAmanage.StreamerRestoreInstance(inst) then count += 1 end
			if opts.async ~= false then NAmanage.WorkBudgetStep(work, tonumber(opts.maxPerStep) or 32, tonumber(opts.timeBudget) or 0.002, opts.delayTime) end
		end
		if state.restoreToken == token then state.restoreToken = nil end
		const left = NAmanage.StreamerCacheCount(state.cache)
		if left > 0 and not token.cancelled and (tonumber(opts.retries) or 2) > 0 then
			const nextOpts = table.clone(opts)
			nextOpts.retries = (tonumber(opts.retries) or 2) - 1
			Delay(0.15, function()
				if not NAStuff.StreamerModeEnabled and state.token == nil and not state.restoreToken then NAmanage.StreamerRestoreAll(nextOpts) end
			end)
		elseif type(opts.onComplete) == "function" then pcall(opts.onComplete, count, token.cancelled) end
		return count
	end
	if opts.async == false then return restore() end
	if #pending > 0 then Spawn(restore) else state.restoreToken = nil end
	return #pending
end

NAmanage.StreamerWatchPlayer = function(plr)
	const state = NAmanage.StreamerGetState()
	const token = state.token
	const rec = NAmanage.StreamerGetRecord(plr)
	if rec.playerToken == token then return end
	for _, conn in rec.links do NAmanage.StreamerDisconnectConn(conn) end
	table.clear(rec.links)
	rec.playerToken = token
	const function changed()
		if not NAmanage.StreamerIsRunActive(token) then return end
		NAmanage.StreamerAddName(plr.Name)
		NAmanage.StreamerAddName(plr.DisplayName)
		NAmanage.StreamerScheduleNameRefresh(true)
	end
	rec.links.name = plr:GetPropertyChangedSignal("Name"):Connect(changed)
	rec.links.display = plr:GetPropertyChangedSignal("DisplayName"):Connect(changed)
	rec.links.char = plr.CharacterAdded:Connect(function(char) NAmanage.StreamerHandleCharacter(char, token) end)
	rec.links.anc = plr.AncestryChanged:Connect(function(_, parent)
		if not parent then NAmanage.StreamerRestoreInstance(plr) end
	end)
	if plr == Services.Players.LocalPlayer then
		rec.links.gui = plr.ChildAdded:Connect(function(child)
			if child:IsA("PlayerGui") and NAmanage.StreamerIsRunActive(token) then
				state.roots = NAmanage.StreamerGetRoots({ includeWorkspace = true })
				NAmanage.StreamerScanContainerAsync(child, { cancelToken = token })
			end
		end)
	end
	if plr.Character then NAmanage.StreamerHandleCharacter(plr.Character, token) end
end

NAmanage.StreamerHandleAdded = function(inst)
	if not NAmanage.StreamerIsRunActive() then return end
	if NAmanage.StreamerIsTarget(inst) then NAmanage.StreamerScrubInstance(inst)
	elseif NAmanage.StreamerIsContainer(inst) then NAmanage.StreamerScanContainerAsync(inst) end
end

NAmanage.setStreamerMode = function(enable, opts)
	opts = opts or {}
	const state = NAmanage.StreamerGetState()
	const on = enable == true
	if opts.save ~= false then pcall(NAmanage.NASettingsSet, "streamerMode", on) end
	if opts.force ~= true and NAStuff.StreamerModeEnabled == on and (on and state.applied or not on and not next(state.cache) and state.playerListOriginal == nil) then
		if on then NAmanage.StreamerScheduleNameRefresh(true) end
		return on
	end
	NAmanage.CancelTokenCancel(state.token)
	NAmanage.CancelTokenCancel(state.restoreToken)
	state.token, state.restoreToken, state.nameJob, state.refreshJob = nil, nil, nil, nil
	state.refresh, state.refreshAgain = false, false
	NAStuff.StreamerModeEnabled = on
	for _, key in { "streamermode_coregui", "streamermode_playergui", "streamermode_hui", "streamermode_workspace", "streamermode_player_chars", "streamermode_players", "streamermode_player_names" } do NAlib.disconnect(key) end
	if not on then
		state.applied = false
		NAmanage.StreamerSetPlayerListHidden(false)
		NAmanage.StreamerRestoreAll({ async = opts.restoreAsync ~= false, maxPerStep = opts.maxPerStep, timeBudget = opts.timeBudget })
		if NAmanage.StreamerChatChanged then pcall(NAmanage.StreamerChatChanged) end
		if not opts.silent and DoNotif then DoNotif("Streamer Mode disabled", 2) end
		return false
	end
	const token = NAmanage.NewCancelToken()
	state.token = token
	state.roots = NAmanage.StreamerGetRoots({ includeWorkspace = true })
	NAmanage.StreamerRefreshNameTokens()
	NAmanage.StreamerSetPlayerListHidden(true)
	Delay(0.25, function()
		if NAmanage.StreamerIsRunActive(token) then NAmanage.StreamerSetPlayerListHidden(true) end
	end)
	for _, plr in __lt.cm("Players", "GetPlayers") do NAmanage.StreamerWatchPlayer(plr) end
	const spec = {
		added = NAmanage.StreamerHandleAdded,
		filterAdded = NAmanage.StreamerIsRelevant,
		classNames = { "TextLabel", "TextButton", "TextBox", "ImageLabel", "ImageButton", "BillboardGui", "SurfaceGui" },
	}
	NAlib.connect("streamermode_coregui", NAmanage.cgSub(spec))
	NAlib.connect("streamermode_playergui", NAmanage.pgSub(spec))
	for _, root in state.roots do
		if root ~= Services.CoreGui and root ~= Services.Workspace and not root:IsA("PlayerGui") then
			NAlib.connect("streamermode_hui", NAmanage.descSub(root, spec))
		end
	end
	NAlib.connect("streamermode_workspace", NAmanage.wsSub(spec))
	NAlib.connect("streamermode_players", NAmanage.playersSub({
		added = function(plr)
			if not NAmanage.StreamerIsRunActive(token) then return end
			NAmanage.StreamerAddName(plr.Name)
			NAmanage.StreamerAddName(plr.DisplayName)
			NAmanage.StreamerWatchPlayer(plr)
			NAmanage.StreamerScheduleNameRefresh(true)
		end,
		removing = function(plr)
			NAmanage.StreamerRestoreInstance(plr)
			if plr.Character and not plr.Character.Parent then NAmanage.StreamerRestoreInstance(plr.Character) end
		end,
	}))
	NAmanage.StreamerScrubAll(token, { yieldEvery = 64 })
	if NAmanage.StreamerChatChanged then pcall(NAmanage.StreamerChatChanged) end
	state.applied = true
	if not opts.silent and DoNotif then DoNotif("Streamer Mode enabled", 2) end
	return true
end

NAStuff.CmdBar2 = {
	defaultWidth = 340;
	defaultHeight = 78;
	minWidth = 200;
	maxWidth = 500;
	minHeight = 70;
	maxHeight = 160;
	topHeight = 26;
	bodyOffsetY = 34;
	bodyBottomPadding = 8;
	bodyMinHeight = 24;
}

function NAmanage.CmdBar2ClampValue(value, minValue, maxValue, fallback)
	local numberValue = tonumber(value)
	if not numberValue then
		return fallback
	end
	numberValue = math.floor(numberValue + 0.5)
	if numberValue < minValue then
		return minValue
	elseif numberValue > maxValue then
		return maxValue
	end
	return numberValue
end

function NAmanage.CmdBar2ComputeBodyHeight(totalHeight)
	const cfg = NAStuff.CmdBar2 or {}
	const available = totalHeight - (cfg.bodyOffsetY or 0) - (cfg.bodyBottomPadding or 0)
	if available < (cfg.bodyMinHeight or 0) then
		return cfg.bodyMinHeight or 0
	end
	return available
end

