NAlib.connect("NA_startup_performance", Services.RunService.Heartbeat:Connect(function(dt)
	const perf = NAStuff.StartupPerformance
	if type(perf) ~= "table" or perf.finished == true then
		return
	end
	dt = tonumber(dt) or 0
	perf.lastFrameDt = dt
	perf.frames = (tonumber(perf.frames) or 0) + 1
	if dt > 0 and (not perf.minFrame or dt < perf.minFrame) then
		perf.minFrame = dt
	end
	if dt > (tonumber(perf.maxFrame) or 0) then
		perf.maxFrame = dt
	end
	if dt >= 0.08 then
		const spikes = perf.spikes
		if type(spikes) == "table" and #spikes < 24 then
			spikes[#spikes + 1] = {
				dt = dt;
				at = os.clock() - (tonumber(perf.started) or os.clock());
			}
		end
	end
end))

NAmanage.StartupWorkStep = function()
	const perf = NAStuff and NAStuff.StartupPerformance
	const build = NAgui and NAgui.SettingsBuildState
	const active = type(perf) == "table" and perf.finished ~= true
	if not active and NAStuff.SettingsBuildRunning ~= true and not (type(build) == "table" and build.building == true)
		and (NAStuff._loadingFinalizedOnce == true or (NAAssetsLoading and NAAssetsLoading._finalized == true)) then
		return false
	end
	local state = NAStuff._startupWorkBudget
	const now = os.clock()
	if type(state) ~= "table" then
		state = { count = 0; last = now; }
		NAStuff._startupWorkBudget = state
	end
	state.count += 1
	const mobile = IsOnMobile == true or (NAmanage.IsLowEndUI and NAmanage.IsLowEndUI() == true)
	const dt = active and tonumber(perf.lastFrameDt) or nil
	local budget = mobile and 0.004 or 0.006
	local batch = mobile and 96 or 160
	if dt and dt > (1 / 30) then
		budget = 0.002
		batch = mobile and 48 or 80
	elseif dt and dt > 0 and dt < (1 / 180) then
		budget = 0.002
	end
	if type(build) == "table" and build.userInteracted == true then budget = math.min(budget, 0.003) end
	if state.count < batch and now - state.last < budget then return false end
	if coroutine and type(coroutine.isyieldable) == "function" and not coroutine.isyieldable() then return false end
	const start = os.clock()
	Wait()
	state.last = os.clock()
	state.count = 0
	if active then
		perf.workYields = (tonumber(perf.workYields) or 0) + 1
		perf.workWaitElapsed = (tonumber(perf.workWaitElapsed) or 0) + state.last - start
	end
	return true
end

NAmanage.StartupInstanceBudgetStep = function()
	if NAmanage.StartupWorkStep() then
		const perf = NAStuff and NAStuff.StartupPerformance
		if type(perf) == "table" and perf.finished ~= true then
			perf.instanceYields = (tonumber(perf.instanceYields) or 0) + 1
		end
	end
end

