	ui.statusLabel = label(content, "Starting...", 12, { Position = UDim2.fromOffset(0, 54), Size = UDim2.new(1, -58, 0, 38), TextWrapped = true, TextTruncate = Enum.TextTruncate.AtEnd, TextYAlignment = Enum.TextYAlignment.Top, TextColor3 = Color3.fromRGB(162, 162, 162) })
