	ui.toastPercent = label(ui.toast, "0%", 11, { Position = UDim2.new(1, -177, 0, 9), Size = UDim2.fromOffset(35, 22), TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 21 })
