		fpsBoostOptions = {
			default = function()
				return {
					lowQuality = true;
					disableShadows = true;
					disableGrass = true;
					simpleWater = true;
					stripParticles = true;
					stripDecals = true;
					stripTextures = true;
					stripLights = true;
					stripPostFx = true;
					stripAtmosphere = true;
					stripSurfaceAppearance = true;
					stripHighlights = true;
					stripExplosions = true;
					simplifyMaterials = true;
					zeroReflectance = true;
					optimizeMeshes = true;
					disable3dUi = false;
					ignorePlayers = false;
					ignoreSelf = true;
					liveUpdates = true;
					keepEffectsOff = false;
					particleRate = 0;
				}
			end;
			coerce = function(value)
				const defaults = {
					lowQuality = true;
					disableShadows = true;
					disableGrass = true;
					simpleWater = true;
					stripParticles = true;
					stripDecals = true;
					stripTextures = true;
					stripLights = true;
					stripPostFx = true;
					stripAtmosphere = true;
					stripSurfaceAppearance = true;
					stripHighlights = true;
					stripExplosions = true;
					simplifyMaterials = true;
					zeroReflectance = true;
					optimizeMeshes = true;
					disable3dUi = false;
					ignorePlayers = false;
					ignoreSelf = true;
					liveUpdates = true;
					keepEffectsOff = false;
					particleRate = 0;
				}
				value = type(value) == "table" and value or {}
				const out = {}
				for key, fallback in defaults do
					if type(fallback) == "boolean" then
						out[key] = NAmanage.NASettingsSchemaState.coerceBoolean(value[key], fallback)
					end
				end
				local rate = tonumber(value.particleRate) or 0
				if rate ~= rate then rate = 0 end
				out.particleRate = math.clamp(math.floor(rate), 0, 1000)
				return out
			end;
		};
		hitboxOptions = {
			default = function()
				return {
					size = 10;
					transparency = 0.9;
					color = { R = 0; G = 0; B = 0 };
					material = "Neon";
					noCollide = true;
					massless = true;
				}
			end;
			coerce = function(value)
				const function coerceNumber(v, min, max, fallback)
					local n = tonumber(v)
					if not n then return fallback end
					if n < min then n = min end
					if n > max then n = max end
					return n
				end

				const function coerceColor(v)
					if typeof(v) == "Color3" then
						return {
							R = NAmanage.NASettingsSchemaState.clampChannel(v.R) or 0;
							G = NAmanage.NASettingsSchemaState.clampChannel(v.G) or 0;
							B = NAmanage.NASettingsSchemaState.clampChannel(v.B) or 0;
						}
					end
					if type(v) == "table" then
						const r = NAmanage.NASettingsSchemaState.clampChannel(v.R or v.r or v[1])
						const g = NAmanage.NASettingsSchemaState.clampChannel(v.G or v.g or v[2])
						const b = NAmanage.NASettingsSchemaState.clampChannel(v.B or v.b or v[3])
						if r and g and b then
							return { R = r; G = g; B = b }
						end
					end
					if type(v) == "string" then
						local ok, decoded = NACaller(function()
							return Services.HttpService:JSONDecode(v)
						end)
						if ok and type(decoded) == "table" then
							return coerceColor(decoded)
						end
					end
					return { R = 0; G = 0; B = 0 }
				end

				const defaults = {
					size = 10;
					transparency = 0.9;
					color = { R = 0; G = 0; B = 0 };
					material = "Neon";
					noCollide = true;
					massless = true;
				}

				if type(value) ~= "table" then
					return defaults
				end

				const out = {}
				out.size = coerceNumber(value.size, 0.1, 200, defaults.size)
				out.transparency = coerceNumber(value.transparency, 0, 1, defaults.transparency)
				out.color = coerceColor(value.color)

				local mat = "Neon"
				if type(value.material) == "string" then
					mat = value.material
				elseif value.material ~= nil then
					mat = tostring(value.material)
				end
				if type(mat) == "string" then
					const trimmed = mat:match("^%s*(.-)%s*$") or mat
					if Enum.Material[trimmed] then
						mat = trimmed
					else
						const lower = trimmed:lower()
						for _, item in Enum.Material:GetEnumItems() do
							if item.Name:lower() == lower then
								mat = item.Name
								break
							end
						end
					end
				else
					mat = defaults.material
				end
				out.material = mat
				out.noCollide = NAmanage.NASettingsSchemaState.coerceBoolean(value.noCollide, defaults.noCollide)
				out.massless = NAmanage.NASettingsSchemaState.coerceBoolean(value.massless, defaults.massless)
				return out
			end;
		};
