NAmanage.resolveCommandName=function(name)
	name = (name or ""):lower()
	const entry = cmds.Commands[name] or cmds.Aliases[name]
	if not entry then return nil end
	for cmdName, data in cmds.Commands do
		if data == entry then
			return cmdName
		end
	end
	return name
end

