PlayerArgs["closest"] = PlayerArgs["nearest"]
PlayerArgs["furthest"] = PlayerArgs["farthest"]
PlayerArgs["sat"] = PlayerArgs["seated"]
PlayerArgs["standing"] = PlayerArgs["stood"]
