NAmanage.DrawingCreateSquare = function(color, fillTransparency, options)
	if NAmanage.DrawingObjectSupported and not NAmanage.DrawingObjectSupported("Square") then
		return nil
	end
	const drawingLib = NAgui.getDrawingLibrary()
	if not drawingLib then
		return nil
	end
	local ok, square = pcall(function()
		return drawingLib.new("Square")
	end)
	if not ok or not square then
		if type(NAmanage._drawingObjectSupport) == "table" then
			NAmanage._drawingObjectSupport.Square = false
		end
		return nil
	end
	const alpha = NAgui.toDrawingTransparency(fillTransparency or 0.7)
	const thickness = math.max(1, tonumber(options and options.thickness) or 1)
	const filled = options and options.filled == true
	pcall(function()
		square.Visible = false
		square.Filled = filled
		square.Thickness = thickness
		square.Color = color or Color3.new(1, 1, 1)
		square.Transparency = alpha
	end)
	return square
end

NAmanage.DrawingUpdateSquare = function(square, inst, color, fillTransparency, options)
	if not square then return false end
	local minX, minY, width, height = NAgui.getInstanceViewportBounds(inst)
	if not minX then
		pcall(function()
			square.Visible = false
		end)
		return true
	end
	const alpha = NAgui.toDrawingTransparency(fillTransparency or 0.7)
	const thickness = math.max(1, tonumber(options and options.thickness) or 1)
	const filled = options and options.filled == true
	const ok = pcall(function()
		square.Color = color or Color3.new(1, 1, 1)
		square.Transparency = alpha
		square.Filled = filled
		square.Thickness = thickness
		square.Position = Vector2.new(minX, minY)
		square.Size = Vector2.new(width, height)
		square.Visible = true
	end)
	if not ok and type(NAmanage._drawingObjectSupport) == "table" then
		NAmanage._drawingObjectSupport.Square = false
	end
	return ok
end

NAmanage.DrawingCreateText = function(text, color, textSize, options)
	if NAmanage.DrawingObjectSupported and not NAmanage.DrawingObjectSupported("Text") then
		return nil
	end
	const drawingLib = NAgui.getDrawingLibrary()
	if not drawingLib then
		return nil
	end
	local ok, txt = pcall(function()
		return drawingLib.new("Text")
	end)
	if not ok or not txt then
		if type(NAmanage._drawingObjectSupport) == "table" then
			NAmanage._drawingObjectSupport.Text = false
		end
		return nil
	end
	local outlineEnabled
	if options and options.outlineEnabled ~= nil then
		outlineEnabled = options.outlineEnabled == true
	else
		outlineEnabled = NAStuff.ESP_DrawingTextOutline ~= false
	end
	local centered = options and options.centered
	if centered == nil then
		centered = NAStuff.ESP_DrawingTextCentered ~= false
	end
	const alpha = NAgui.sanitizeDrawingAlpha(options and options.textTransparency or NAStuff.ESP_DrawingTextTransparency or 0)
	const fontValue = NAgui.getDrawingTextFontValue(options and options.font or NAStuff.ESP_DrawingTextFont)
	pcall(function()
		txt.Visible = false
		txt.Center = centered ~= false
		txt.Outline = outlineEnabled
		txt.Color = color or Color3.new(1, 1, 1)
		txt.Size = NAgui.sanitizeLabelSize(textSize or 12)
		txt.Text = tostring(text or "")
		txt.Transparency = alpha
		txt.OutlineColor = Color3.new(0.05, 0.05, 0.05)
	end)
	pcall(function()
		txt.Font = fontValue
	end)
	return txt
end

NAmanage.DrawingUpdateText = function(txt, worldPos, text, color, textSize, options)
	if not txt then return false end
	const cam = Services.Workspace and Services.Workspace.CurrentCamera
	if not cam or not worldPos then
		pcall(function()
			txt.Visible = false
		end)
		return true
	end
	local viewportPoint, onScreen = cam:WorldToViewportPoint(worldPos)
	if viewportPoint.Z <= 0 or not onScreen then
		pcall(function()
			txt.Visible = false
		end)
		return true
	end
	local outlineEnabled
	if options and options.outlineEnabled ~= nil then
		outlineEnabled = options.outlineEnabled == true
	else
		outlineEnabled = NAStuff.ESP_DrawingTextOutline ~= false
	end
	local centered = options and options.centered
	if centered == nil then
		centered = NAStuff.ESP_DrawingTextCentered ~= false
	end
	const alpha = NAgui.sanitizeDrawingAlpha(options and options.textTransparency or NAStuff.ESP_DrawingTextTransparency or 0)
	const fontValue = NAgui.getDrawingTextFontValue(options and options.font or NAStuff.ESP_DrawingTextFont)
	const ok = pcall(function()
		txt.Text = tostring(text or "")
		txt.Color = color or Color3.new(1, 1, 1)
		txt.Size = NAgui.sanitizeLabelSize(textSize or 12)
		txt.Outline = outlineEnabled
		txt.Center = centered ~= false
		txt.Transparency = alpha
		txt.OutlineColor = Color3.new(0.05, 0.05, 0.05)
		txt.Position = Vector2.new(viewportPoint.X, viewportPoint.Y)
		txt.Visible = true
	end)
	pcall(function()
		txt.Font = fontValue
	end)
	if not ok and type(NAmanage._drawingObjectSupport) == "table" then
		NAmanage._drawingObjectSupport.Text = false
	end
	return ok
end

NAmanage.DrawingCreateLine = function(color, alpha, thickness)
	if NAmanage.DrawingLineSupported and not NAmanage.DrawingLineSupported() then
		return nil
	end
	const drawingLib = NAgui.getDrawingLibrary()
	if not drawingLib then
		return nil
	end
	local ok, line = pcall(function()
		return drawingLib.new("Line")
	end)
	if not ok or not line then
		if type(NAmanage._drawingObjectSupport) == "table" then
			NAmanage._drawingObjectSupport.Line = false
		end
		return nil
	end
	pcall(function()
		line.Visible = false
		line.Color = color or Color3.new(1, 1, 1)
		line.Transparency = math.clamp(tonumber(alpha) or 1, 0, 1)
		line.Thickness = math.max(1, tonumber(thickness) or 1)
		line.From = Vector2.new(0, 0)
		line.To = Vector2.new(0, 0)
	end)
	return line
end

NAmanage.DrawingUpdateLine = function(line, fromPos, toPos, color, alpha, thickness)
	if not line then return false end
	if typeof(fromPos) ~= "Vector2" or typeof(toPos) ~= "Vector2" then
		pcall(function()
			line.Visible = false
		end)
		return true
	end
	const ok = pcall(function()
		line.From = fromPos
		line.To = toPos
		line.Color = color or Color3.new(1, 1, 1)
		line.Transparency = math.clamp(tonumber(alpha) or 1, 0, 1)
		line.Thickness = math.max(1, tonumber(thickness) or 1)
		line.Visible = true
	end)
	if not ok and type(NAmanage._drawingObjectSupport) == "table" then
		NAmanage._drawingObjectSupport.Line = false
	end
	return ok
end

NAmanage.DrawingCreateTriangle = function(color, alpha)
	if NAmanage.DrawingTriangleSupported and not NAmanage.DrawingTriangleSupported() then
		return nil
	end
	const drawingLib = NAgui.getDrawingLibrary()
	if not drawingLib then
		return nil
	end
	local ok, tri = pcall(function()
		return drawingLib.new("Triangle")
	end)
	if not ok or not tri then
		if type(NAmanage._drawingObjectSupport) == "table" then
			NAmanage._drawingObjectSupport.Triangle = false
		end
		return nil
	end
	pcall(function()
		tri.Visible = false
		tri.Filled = true
		tri.Thickness = 1
		tri.Color = color or Color3.new(1, 1, 1)
		tri.Transparency = math.clamp(tonumber(alpha) or 1, 0, 1)
	end)
	return tri
end

NAmanage.DrawingUpdateTriangle = function(tri, centerX, centerY, dirX, dirY, size, color, alpha)
	if not tri then
		return
	end
	local dx = tonumber(dirX) or 0
	local dy = tonumber(dirY) or -1
	const mag = math.sqrt((dx * dx) + (dy * dy))
	if mag <= 1e-4 then
		dx, dy = 0, -1
	else
		dx, dy = dx / mag, dy / mag
	end
	const arrowSize = math.clamp(tonumber(size) or 26, 8, 256)
	const tip = arrowSize * 0.5
	const tail = arrowSize * 0.36
	const halfWidth = arrowSize * 0.32
	const px = -dy
	const py = dx
	const ax = centerX + (dx * tip)
	const ay = centerY + (dy * tip)
	const baseX = centerX - (dx * tail)
	const baseY = centerY - (dy * tail)
	const bx = baseX + (px * halfWidth)
	const by = baseY + (py * halfWidth)
	const cx = baseX - (px * halfWidth)
	const cy = baseY - (py * halfWidth)
	const ok = pcall(function()
		tri.Color = color or Color3.new(1, 1, 1)
		tri.Transparency = math.clamp(tonumber(alpha) or 1, 0, 1)
		tri.PointA = Vector2.new(ax, ay)
		tri.PointB = Vector2.new(bx, by)
		tri.PointC = Vector2.new(cx, cy)
		tri.Visible = true
	end)
	if not ok and type(NAmanage._drawingObjectSupport) == "table" then
		NAmanage._drawingObjectSupport.Triangle = false
	end
	return ok
end

NAgui.updateLabelBounds=function(label)
	if not label then return end
	const billboard = label.Parent
	if not billboard or not billboard:IsA("BillboardGui") then return end
	local text = label.Text
	if text == "" then
		text = label.Name or " "
	end
	const targetSize = NAgui.sanitizeLabelSize(NAStuff.ESP_LabelTextSize)
	local success, bounds = pcall(Services.TextService.GetTextSize, Services.TextService, text, targetSize, label.Font, Vector2.new(1e4, 1e4))
	local width = 150
	local height = math.max(targetSize + 12, 30)
	if success and bounds then
		width = math.clamp(math.floor(bounds.X + 16), 80, 600)
		height = math.clamp(math.floor(bounds.Y + 12), 24, 200)
	end
	const size = billboard.Size
	if size.X.Offset ~= width or size.Y.Offset ~= height then
		billboard.Size = UDim2.new(0, width, 0, height)
	end
end

NAgui.applyLabelStyle=function(label)
	if not label then return end
	label.AutomaticSize = Enum.AutomaticSize.None
	label.TextScaled = NAStuff.ESP_LabelTextScaled
	label.TextWrapped = false
	label.ClipsDescendants = false
	label.TextStrokeTransparency = math.clamp(tonumber(NAStuff.ESP_LabelStrokeTransparency) or 0.5, 0, 1)
	label.TextSize = NAgui.sanitizeLabelSize(NAStuff.ESP_LabelTextSize)
	NAgui.updateLabelBounds(label)
end

NAgui.updateLabelForInstance=function(inst)
	if not inst or not inst.Parent then return end
	for _, child in inst:GetChildren() do
		if child:IsA("BillboardGui") and Sub(Lower(child.Name),-6) == "_label" then
			const lbl = child:FindFirstChildWhichIsA("TextLabel")
			if lbl then
				NAgui.applyLabelStyle(lbl)
			end
		end
	end
end

NAmanage.ESP_ApplyLabelStyles = function()
	const scaled = (NAStuff.ESP_LabelTextScaled == true)
	const size = NAgui.sanitizeLabelSize(NAStuff.ESP_LabelTextSize)
	const seen = {}
	if NAStuff.partESPEntries then
		for _, entry in NAStuff.partESPEntries do
			if typeof(entry) == "table" and not seen[entry] then
				seen[entry] = true
				if entry.label then
					entry.label.TextScaled = scaled
					if not scaled then
						entry.label.TextSize = size
					end
				end
				if entry.drawingLabel then
					pcall(function()
						entry.drawingLabel.Size = size
						entry.drawingLabel.Outline = NAStuff.ESP_DrawingPartTextOutline ~= false
						entry.drawingLabel.Center = NAStuff.ESP_DrawingPartTextCentered ~= false
						entry.drawingLabel.Transparency = NAgui.sanitizeDrawingAlpha(NAStuff.ESP_DrawingPartTextTransparency or 0)
						entry.drawingLabel.Font = NAgui.getDrawingTextFontValue(NAStuff.ESP_DrawingTextFont)
						entry.drawingLabel.OutlineColor = Color3.new(0.05, 0.05, 0.05)
					end)
				end
			end
		end
	end
	if NAStuff.partESPVisualMap then
		for _, entry in NAStuff.partESPVisualMap do
			if typeof(entry) == "table" and not seen[entry] then
				seen[entry] = true
				if entry.label then
					entry.label.TextScaled = scaled
					if not scaled then
						entry.label.TextSize = size
					end
				end
				if entry.drawingLabel then
					pcall(function()
						entry.drawingLabel.Size = size
						entry.drawingLabel.Outline = NAStuff.ESP_DrawingPartTextOutline ~= false
						entry.drawingLabel.Center = NAStuff.ESP_DrawingPartTextCentered ~= false
						entry.drawingLabel.Transparency = NAgui.sanitizeDrawingAlpha(NAStuff.ESP_DrawingPartTextTransparency or 0)
						entry.drawingLabel.Font = NAgui.getDrawingTextFontValue(NAStuff.ESP_DrawingTextFont)
						entry.drawingLabel.OutlineColor = Color3.new(0.05, 0.05, 0.05)
					end)
				end
			end
		end
	end
	if type(espCONS) == "table" then
		for _, data in espCONS do
			if type(data) == "table" then
				if data.textLabel then
					data.textLabel.TextScaled = scaled
					if not scaled then
						data.textLabel.TextSize = size
					end
				end
				if data.drawingLabel then
					pcall(function()
						data.drawingLabel.Size = size
						data.drawingLabel.Outline = NAStuff.ESP_DrawingTextOutline ~= false
						data.drawingLabel.Center = NAStuff.ESP_DrawingTextCentered ~= false
						data.drawingLabel.Transparency = NAgui.sanitizeDrawingAlpha(NAStuff.ESP_DrawingTextTransparency or 0)
						data.drawingLabel.Font = NAgui.getDrawingTextFontValue(NAStuff.ESP_DrawingTextFont)
						data.drawingLabel.OutlineColor = Color3.new(0.05, 0.05, 0.05)
					end)
				end
			end
		end
	end
end

NAgui.highlightNeedsGlass = function(base)
	if not base or not base:IsA("BasePart") then
		return false
	end
	const transparency = tonumber(base.Transparency) or 0
	const localTransparency = tonumber(base.LocalTransparencyModifier) or 0
	return transparency > 0.01 or localTransparency > 0.01
end

NAStuff.ESP_HighlightMaterialPartStates = NAmanage.ensureWeakTable(NAStuff.ESP_HighlightMaterialPartStates, "k")
NAStuff.ESP_HighlightMaterialTargetStates = NAmanage.ensureWeakTable(NAStuff.ESP_HighlightMaterialTargetStates, "k")

NAgui.highlightMaterialApplyPart = function(base, state)
	if not (base and base:IsA("BasePart") and type(state) == "table") then
		return
	end
	const active = (tonumber(state.refs) or 0) > 0
	const needsGlass = active and NAgui.highlightNeedsGlass(base)
	if needsGlass then
		if not state.forced then
			state.desiredMaterial = base.Material
			state.forced = true
		elseif not state.writingMaterial and base.Material ~= Enum.Material.Glass then
			state.desiredMaterial = base.Material
		end
		if base.Material ~= Enum.Material.Glass then
			state.writingMaterial = true
			NAlib.setProperty(base, "Material", Enum.Material.Glass)
			state.writingMaterial = false
		end
	elseif state.forced then
		const restoreMaterial = state.desiredMaterial
		state.forced = false
		if restoreMaterial ~= nil and base.Material ~= restoreMaterial then
			state.writingMaterial = true
			NAlib.setProperty(base, "Material", restoreMaterial)
			state.writingMaterial = false
		end
		state.desiredMaterial = nil
	end
end

NAgui.highlightMaterialAcquirePart = function(base)
	if not (base and base:IsA("BasePart")) then
		return
	end
	local states = NAmanage.ensureWeakTable(NAStuff.ESP_HighlightMaterialPartStates, "k")
	NAStuff.ESP_HighlightMaterialPartStates = states
	local state = states[base]
	if type(state) == "table" then
		state.refs = (tonumber(state.refs) or 0) + 1
		NAgui.highlightMaterialApplyPart(base, state)
		return
	end
	state = {
		refs = 1,
		forced = false,
		writingMaterial = false,
	}
	states[base] = state
	state.materialConn = base:GetPropertyChangedSignal("Material"):Connect(function()
		if state.writingMaterial or (tonumber(state.refs) or 0) <= 0 then
			return
		end
		if state.forced and base.Material ~= Enum.Material.Glass then
			state.desiredMaterial = base.Material
			NAgui.highlightMaterialApplyPart(base, state)
		end
	end)
	state.transparencyConn = base:GetPropertyChangedSignal("Transparency"):Connect(function()
		if (tonumber(state.refs) or 0) > 0 then
			NAgui.highlightMaterialApplyPart(base, state)
		end
	end)
	state.localTransparencyConn = base:GetPropertyChangedSignal("LocalTransparencyModifier"):Connect(function()
		if (tonumber(state.refs) or 0) > 0 then
			NAgui.highlightMaterialApplyPart(base, state)
		end
	end)
	NAgui.highlightMaterialApplyPart(base, state)
end

NAgui.highlightMaterialReleasePart = function(base)
	if not (base and base:IsA("BasePart")) then
		return
	end
	const states = NAStuff.ESP_HighlightMaterialPartStates
	const state = type(states) == "table" and states[base] or nil
	if type(state) ~= "table" then
		return
	end
	state.refs = math.max(0, (tonumber(state.refs) or 1) - 1)
	if state.refs > 0 then
		NAgui.highlightMaterialApplyPart(base, state)
		return
	end
	NAgui.highlightMaterialApplyPart(base, state)
	for _, connection in { state.materialConn, state.transparencyConn, state.localTransparencyConn } do
		if connection then
			pcall(function()
				connection:Disconnect()
			end)
		end
	end
	state.materialConn = nil
	state.transparencyConn = nil
	state.localTransparencyConn = nil
	states[base] = nil
end

NAgui.highlightMaterialAcquireTarget = function(target, owner)
	if not (target and typeof(target) == "Instance" and (target:IsA("BasePart") or target:IsA("Model"))) then
		return
	end
	local targetStates = NAmanage.ensureWeakTable(NAStuff.ESP_HighlightMaterialTargetStates, "k")
	NAStuff.ESP_HighlightMaterialTargetStates = targetStates
	local state = targetStates[target]
	if type(state) ~= "table" then
		state = {
			owners = {},
			ownerCount = 0,
			parts = NAmanage.ensureWeakTable(nil, "k"),
		}
		targetStates[target] = state
	end
	const ownerKey = owner or target
	if state.owners[ownerKey] then
		return
	end
	state.owners[ownerKey] = true
	state.ownerCount = (tonumber(state.ownerCount) or 0) + 1
	if state.ownerCount > 1 then
		return
	end
	const function acquirePart(base)
		if base and base:IsA("BasePart") and not state.parts[base] then
			state.parts[base] = true
			NAgui.highlightMaterialAcquirePart(base)
		end
	end
	const function releasePart(base)
		if base and state.parts[base] then
			state.parts[base] = nil
			NAgui.highlightMaterialReleasePart(base)
		end
	end
	if target:IsA("BasePart") then
		acquirePart(target)
	else
		for _, desc in NAmanage.QueryDescendants(target, "BasePart") do
			acquirePart(desc)
		end
		state.descAddedConn = target.DescendantAdded:Connect(function(desc)
			if desc:IsA("BasePart") then
				acquirePart(desc)
			end
		end)
		state.descRemovingConn = target.DescendantRemoving:Connect(function(desc)
			if desc:IsA("BasePart") then
				releasePart(desc)
			end
		end)
	end
end

NAgui.highlightMaterialReleaseTarget = function(target, owner)
	if not (target and typeof(target) == "Instance") then
		return
	end
	const targetStates = NAStuff.ESP_HighlightMaterialTargetStates
	const state = type(targetStates) == "table" and targetStates[target] or nil
	if type(state) ~= "table" then
		return
	end
	const ownerKey = owner or target
	if not state.owners[ownerKey] then
		return
	end
	state.owners[ownerKey] = nil
	state.ownerCount = math.max(0, (tonumber(state.ownerCount) or 1) - 1)
	if state.ownerCount > 0 then
		return
	end
	for _, connection in { state.descAddedConn, state.descRemovingConn } do
		if connection then
			pcall(function()
				connection:Disconnect()
			end)
		end
	end
	state.descAddedConn = nil
	state.descRemovingConn = nil
	const releaseList = {}
	for base in state.parts do
		releaseList[#releaseList + 1] = base
	end
	for i = 1, #releaseList do
		state.parts[releaseList[i]] = nil
		NAgui.highlightMaterialReleasePart(releaseList[i])
	end
	targetStates[target] = nil
end

NAgui.adjustHighlightMaterialFor = function(target, enable, owner)
	if enable then
		NAgui.highlightMaterialAcquireTarget(target, owner)
	else
		NAgui.highlightMaterialReleaseTarget(target, owner)
	end
end

NAmanage.ESP_AdjustHighlightMaterial = function(target, enable, owner)
	NAgui.adjustHighlightMaterialFor(target, enable, owner)
end

NAStuff.partESPEntries = NAStuff.partESPEntries or {}
NAStuff.partESPVisualMap = NAmanage.ensureWeakTable(NAStuff.partESPVisualMap, "k")
NAStuff.partESPPartMap = NAmanage.ensureWeakTable(NAStuff.partESPPartMap, "k")
NAStuff.partESPQueueMap = NAmanage.ensureWeakTable(NAStuff.partESPQueueMap, "k")
NAStuff.partESPQueue = NAStuff.partESPQueue or {}
NAStuff.partESPQueueHead = tonumber(NAStuff.partESPQueueHead) or 1
NAStuff.partESPQueueTail = tonumber(NAStuff.partESPQueueTail) or 0
NAStuff.partESPActiveCount = tonumber(NAStuff.partESPActiveCount) or 0
NAStuff.partESPSweeps = NAStuff.partESPSweeps or {}
NAStuff.espScanTokens = NAStuff.espScanTokens or {}
NAStuff.espSweepCursor = NAStuff.espSweepCursor or {}
NAStuff.espNameApplicators = NAStuff.espNameApplicators or {}
NAStuff.espNameWatchers = NAmanage.ensureWeakTable(NAStuff.espNameWatchers, "k")
NAStuff.espNameWatchQueue = NAStuff.espNameWatchQueue or {}
NAStuff.espNameWatchQueueMap = NAmanage.ensureWeakTable(NAStuff.espNameWatchQueueMap, "k")
NAStuff.espNameWatchHead = tonumber(NAStuff.espNameWatchHead) or 1
NAStuff.espNameWatchTail = tonumber(NAStuff.espNameWatchTail) or 0

NAmanage.PartESP_QueueClear = function()
	NAStuff.partESPQueue = {}
	NAStuff.partESPQueueMap = NAmanage.ensureWeakTable(nil, "k")
	NAStuff.partESPQueueHead = 1
	NAStuff.partESPQueueTail = 0
	NAlib.disconnect("esp_part_queue")
end

NAmanage.PartESP_QueueRun = function()
	if NAlib.isConnected("esp_part_queue") then
		return
	end
	NAlib.connect("esp_part_queue", Services.RunService.Heartbeat:Connect(function()
		const queue = NAStuff.partESPQueue
		const qMap = NAStuff.partESPQueueMap
		local head = tonumber(NAStuff.partESPQueueHead) or 1
		const tail = tonumber(NAStuff.partESPQueueTail) or 0
		if head > tail then
			NAmanage.PartESP_QueueClear()
			return
		end

		local maxPerStep = tonumber(NAStuff.ESP_MaxPerStep) or 24
		if NAgui.espUsesDrawing("part") then
			maxPerStep = math.max(maxPerStep, tonumber(NAStuff.ESP_DrawingPartQueuePerStep) or 64)
		end
		maxPerStep = math.clamp(math.floor(maxPerStep), 1, 512)
		local processed = 0
		while processed < maxPerStep and head <= tail do
			const item = queue[head]
			queue[head] = nil
			head += 1
			processed += 1
			if item then
				const part = item.part
				if qMap[part] == item then
					qMap[part] = nil
				end
				if part and part.Parent and (part:IsA("BasePart") or part:IsA("Model")) then
					local canCreate = true
					if type(item.guard) == "function" then
						local ok, result = pcall(item.guard, part, item)
						canCreate = ok and result == true
					end
					if canCreate then
						NAmanage.CreateBox(part, item.color, item.transparency, item.customName)
					end
				end
			end
		end

		NAStuff.partESPQueueHead = head
		NAStuff.partESPQueueTail = tail
		if head > tail then
			NAmanage.PartESP_QueueClear()
		end
	end))
end

NAmanage.PartESP_QueueCreate = function(part, color, transparency, guard, customName)
	if not part or not part.Parent then
		return
	end
	if not (part:IsA("BasePart") or part:IsA("Model")) then
		return
	end
	if type(NAmanage.PartESP_CanCreateFor) == "function" and not NAmanage.PartESP_CanCreateFor(part) then
		NAStuff.partESPSkippedLimit = (tonumber(NAStuff.partESPSkippedLimit) or 0) + 1
		return
	end
	const qMap = NAStuff.partESPQueueMap
	const existing = qMap[part]
	if existing then
		existing.color = color
		existing.transparency = transparency
		existing.guard = guard
		existing.customName = customName
		return
	end
	const queue = NAStuff.partESPQueue
	const tail = (tonumber(NAStuff.partESPQueueTail) or 0) + 1
	const item = {
		part = part,
		color = color,
		transparency = transparency,
		guard = guard,
		customName = customName,
	}
	queue[tail] = item
	qMap[part] = item
	NAStuff.partESPQueueTail = tail
	NAmanage.PartESP_QueueRun()
end

NAmanage.PartESP_QueueRemove = function(part)
	if not part then
		return false
	end
	const qMap = NAStuff.partESPQueueMap
	if type(qMap) ~= "table" then
		return false
	end
	const item = qMap[part]
	if not item then
		return false
	end
	qMap[part] = nil
	item.part = nil
	item.guard = nil
	return true
end

NAmanage.PartESP_MaxActive = function()
	local cap = math.clamp(math.floor(tonumber(NAStuff.ESP_PartMaxActive) or 450), 50, 5000)
	local mode = nil
	pcall(function()
		mode = NAgui.getESPRenderMode("part")
	end)
	if mode == "Highlight" then
		cap = math.min(cap, 255)
	end
	return cap
end

NAmanage.PartESP_CanCreateFor = function(part)
	if not part then
		return false
	end
	const partMap = NAStuff.partESPPartMap
	if type(partMap) == "table" and partMap[part] ~= nil then
		return true
	end
	const qMap = NAStuff.partESPQueueMap
	if type(qMap) == "table" and qMap[part] ~= nil then
		return true
	end
	return (tonumber(NAStuff.partESPActiveCount) or 0) < NAmanage.PartESP_MaxActive()
end

NAmanage.PartESP_StartSweep = function(key, predicate, budget, intervalOverride)
	if type(key) ~= "string" or key == "" or type(predicate) ~= "function" then
		return
	end
	local sweeps = NAStuff.partESPSweeps
	if type(sweeps) ~= "table" then
		sweeps = {}
		NAStuff.partESPSweeps = sweeps
	end
	local state = sweeps[key]
	if type(state) ~= "table" then
		state = {}
		sweeps[key] = state
	end
	state.predicate = predicate
	state.budget = math.clamp(math.floor(tonumber(budget) or tonumber(NAStuff.ESP_RescanPerStep) or 90), 8, 400)
	state.intervalOverride = tonumber(intervalOverride)
	state.interval = math.clamp(state.intervalOverride or tonumber(NAStuff.ESP_PartSweepInterval) or 4, 0.75, 60)

	const function resolveInterval()
		return math.clamp(tonumber(state.intervalOverride) or tonumber(NAStuff.ESP_PartSweepInterval) or tonumber(state.interval) or 4, 0.75, 60)
	end

	const function runSweep()
		if state.running then
			return
		end
		state.running = true
		const token = NAmanage.NewCancelToken()
		state.token = token
		SpawnCall(function()
			NAmanage.ForEachWorkspaceYield(function(obj)
				if token.cancelled or not NAlib.isConnected(key) then
					NAmanage.CancelTokenCancel(token)
					return
				end
				const fn = state.predicate
				if type(fn) == "function" then
					pcall(fn, obj)
				end
			end, {
				yieldEvery = state.budget,
				delayTime = tonumber(NAStuff.ESP_ScanDelay) or 0,
				cancelToken = token,
			})
			if state.token == token then
				state.running = false
				state.nextRun = tick() + resolveInterval()
			end
		end)
	end

	if not NAlib.isConnected(key) then
		state.nextRun = 0
		NAlib.connect(key, Services.RunService.Heartbeat:Connect(function()
			const active = NAStuff.partESPSweeps and NAStuff.partESPSweeps[key]
			if active ~= state then
				NAlib.disconnect(key)
				return
			end
			const now = tick()
			if not state.running and now >= (tonumber(state.nextRun) or 0) then
				state.interval = resolveInterval()
				state.nextRun = now + state.interval
				runSweep()
			end
		end))
	else
		state.nextRun = 0
	end
	runSweep()
end

NAmanage.PartESP_StopSweep = function(key)
	if type(key) ~= "string" or key == "" then
		return
	end
	const sweeps = NAStuff.partESPSweeps
	const state = type(sweeps) == "table" and sweeps[key] or nil
	if state and state.token then
		NAmanage.CancelTokenCancel(state.token)
	end
	if type(sweeps) == "table" then
		sweeps[key] = nil
	end
	NAlib.disconnect(key)
	if NAStuff.espSweepCursor then
		NAStuff.espSweepCursor[key] = nil
	end
end

NAmanage.ESP_ClearOcclusionCache = function()
	NAStuff.ESP_OcclusionCache = setmetatable({}, { __mode = "k" })
	NAStuff.ESP_OcclusionFrame = nil
	NAStuff.ESP_OcclusionUsed = 0
	NAStuff.ESP_OcclusionRaycastParams = nil
	NAStuff.partESPLastUpdate = 0
	if type(espCONS) == "table" then
		for _, data in espCONS do
			if data then
				data.next = 0
			end
		end
	end
end

NAmanage.ESP_GetOccludedColor = function(color)
	if typeof(color) ~= "Color3" then
		color = Color3.new(1, 1, 1)
	end
	local blockedColor = NAStuff.ESP_OcclusionColor
	if typeof(blockedColor) ~= "Color3" then
		blockedColor = Color3.fromRGB(130, 130, 130)
	end
	const amount = math.clamp(tonumber(NAStuff.ESP_OcclusionDimAmount) or 0.55, 0, 1)
	return color:Lerp(blockedColor, amount)
end

NAmanage.ESP_GetOccludedTransparency = function(transparency)
	const base = NAgui.sanitizeTransparency(transparency)
	const amount = math.clamp(tonumber(NAStuff.ESP_OcclusionDimAmount) or 0.55, 0, 1)
	return math.clamp(base + ((1 - base) * amount), 0, 1)
end

NAmanage.ESP_CanSpendOcclusionRay = function(now)
	now = tonumber(now) or tick()
	const frame = math.floor(now * 30)
	if NAStuff.ESP_OcclusionFrame ~= frame then
		NAStuff.ESP_OcclusionFrame = frame
		NAStuff.ESP_OcclusionUsed = 0
	end
	const maxPerStep = math.clamp(math.floor(tonumber(NAStuff.ESP_OcclusionMaxPerStep) or 12), 1, 128)
	const used = tonumber(NAStuff.ESP_OcclusionUsed) or 0
	if used >= maxPerStep then
		return false
	end
	NAStuff.ESP_OcclusionUsed = used + 1
	return true
end

NAmanage.ESP_ShouldIgnoreOcclusionHit = function(inst)
	if not (inst and typeof(inst) == "Instance") then
		return false
	end
	if inst:IsA("BasePart") then
		if NAStuff.ESP_OcclusionIgnoreNonCollidable == true then
			local ok, canCollide = pcall(function()
				return inst.CanCollide
			end)
			if ok and canCollide == false then
				return true
			end
		end
		if NAStuff.ESP_OcclusionIgnoreTransparent == true then
			const threshold = math.clamp(tonumber(NAStuff.ESP_OcclusionTransparentThreshold) or 0.85, 0, 1)
			local transparency = 0
			pcall(function()
				transparency = math.max(tonumber(inst.Transparency) or 0, tonumber(inst.LocalTransparencyModifier) or 0)
			end)
			if transparency >= threshold then
				return true
			end
		end
	end
	return false
end

NAmanage.ESP_GetOcclusionFilterList = function(inst, localChar, opts)
	const filter = {}
	if localChar then
		filter[#filter + 1] = localChar
	end
	if typeof(inst) == "Instance" then
		if opts and opts.partESP == true and NAStuff.ESP_OcclusionIgnoreSameModel == true then
			const parent = inst.Parent
			if parent and parent:IsA("Model") then
				filter[#filter + 1] = parent
			else
				filter[#filter + 1] = inst
			end
		else
			filter[#filter + 1] = inst
		end
	end
	return filter
end

NAmanage.ESP_RaycastOccluded = function(inst, targetPos, localChar, opts)
	const cam = Services.Workspace and Services.Workspace.CurrentCamera
	if not (cam and Services.Workspace and Services.Workspace.Raycast and targetPos) then
		return false
	end
	const origin = cam.CFrame.Position
	const direction = targetPos - origin
	const distance = direction.Magnitude
	if distance <= 0.5 then
		return false
	end
	const maxDistance = tonumber(NAStuff.ESP_OcclusionMaxDistance) or 1500
	if maxDistance > 0 and distance > maxDistance then
		return false
	end
	local params = NAStuff.ESP_OcclusionRaycastParams
	if not params then
		params = RaycastParams.new()
		const okFilter = pcall(function()
			params.FilterType = Enum.RaycastFilterType.Exclude
		end)
		if not okFilter then
			pcall(function()
				params.FilterType = Enum.RaycastFilterType.Blacklist
			end)
		end
		params.IgnoreWater = true
		NAStuff.ESP_OcclusionRaycastParams = params
	end
	params.IgnoreWater = true
	const filter = NAmanage.ESP_GetOcclusionFilterList(inst, localChar, opts)
	const probeLimit = math.clamp(math.floor(tonumber(NAStuff.ESP_OcclusionHitProbeLimit) or 4), 1, 20)
	for _ = 1, probeLimit do
		params.FilterDescendantsInstances = filter
		const result = Services.Workspace:Raycast(origin, direction, params)
		if not result then
			return false
		end
		const hit = result.Instance
		if hit and NAmanage.ESP_ShouldIgnoreOcclusionHit(hit) then
			filter[#filter + 1] = hit
		else
			return result.Distance < (distance - 0.5)
		end
	end
	return false
end

NAmanage.ESP_GetOcclusionState = function(key, inst, targetPos, localChar, now, force, opts)
	if NAStuff.ESP_OcclusionEnabled ~= true then
		return false
	end
	if not targetPos then
		return false
	end
	local cache = NAStuff.ESP_OcclusionCache
	if type(cache) ~= "table" then
		cache = setmetatable({}, { __mode = "k" })
		NAStuff.ESP_OcclusionCache = cache
	end
	key = key or inst
	if key == nil then
		return false
	end
	now = tonumber(now) or tick()
	local entry = cache[key]
	const interval = math.clamp(tonumber(NAStuff.ESP_OcclusionUpdateInterval) or 0.25, 0.05, 1)
	if entry and not force and now < (entry.next or 0) then
		return entry.blocked == true
	end
	if not force and not NAmanage.ESP_CanSpendOcclusionRay(now) then
		return entry and entry.blocked == true or false
	end
	entry = entry or {}
	entry.blocked = NAmanage.ESP_RaycastOccluded(inst, targetPos, localChar, opts) == true
	entry.next = now + interval
	cache[key] = entry
	return entry.blocked == true
end

-- PART 7 --
NAmanage.PartESP_UpdateEntry = function(entry, force, rootPart)
	if not entry or entry.removed then return end
	const part = entry.part
	if not part or not part.Parent then
		NAmanage.PartESP_UnregisterEntry(entry)
		return
	end
	const billboard = entry.billboard
	local label = entry.label
	const drawingLabel = entry.drawingLabel
	const drawingSquare = entry.drawingSquare
	const drawingCornerLines = entry.drawingCornerLines
	local drawingCornerOutlineLines = entry.drawingCornerOutlineLines
	const visual = entry.visual
	const hasBillboard = billboard and billboard.Parent
	const hasDrawingLabel = drawingLabel ~= nil
	const hasDrawingSquare = drawingSquare ~= nil
	const hasDrawingCorners = type(drawingCornerLines) == "table" and #drawingCornerLines > 0
		or type(drawingCornerOutlineLines) == "table" and #drawingCornerOutlineLines > 0
	const hasVisual = visual and visual.Parent
	if not (hasBillboard or hasDrawingLabel or hasDrawingSquare or hasDrawingCorners or hasVisual) then
		NAmanage.PartESP_UnregisterEntry(entry)
		return
	end
	if billboard and ((not label) or label.Parent ~= billboard) then
		label = billboard:FindFirstChildWhichIsA("TextLabel")
		entry.label = label
	end
	if billboard and billboard.Parent then
		NAmanage.ESP_StoreVisual(billboard)
	end
	const baseLight = entry.lightColor or entry.baseColor or Color3.new(1, 1, 1)
	const baseDark = entry.darkColor or baseLight
	local visualLight = baseLight
	local visualDark = baseDark
	local labelColor = baseLight
	local transparency = NAgui.sanitizeTransparency(NAStuff.ESP_PartTransparency or entry.transparency)
	local occluded = false
	if NAStuff.ESP_OcclusionEnabled == true and NAStuff.ESP_OcclusionIncludeParts == true then
		const pos = NAgui.getInstanceWorldPosition(part)
		if pos then
			const plr = Services.Players.LocalPlayer
			const char = plr and plr.Character
			occluded = NAmanage.ESP_GetOcclusionState(part, part, pos, char, tick(), false, {
				partESP = true
			})
		end
	end
	if occluded then
		if NAStuff.ESP_OcclusionDimBoxes == true then
			visualLight = NAmanage.ESP_GetOccludedColor(visualLight)
			visualDark = NAmanage.ESP_GetOccludedColor(visualDark)
			transparency = NAmanage.ESP_GetOccludedTransparency(transparency)
		end
		if NAStuff.ESP_OcclusionDimLabels == true then
			labelColor = NAmanage.ESP_GetOccludedColor(labelColor)
		end
	end
	const baseName = entry.customName or part.Name or "Part"
	local display = baseName
	const showPartText = (NAStuff.ESP_ShowPartText ~= false) and not (occluded and NAStuff.ESP_OcclusionHidePartLabels == true)
	const showDistance = (NAStuff.ESP_ShowPartDistance == true)
	local root = rootPart
	if showDistance and not root then
		const plr = Services.Players.LocalPlayer
		const char = plr and plr.Character
		root = char and getRoot(char)
	end
	if showDistance and root then
		const pos = NAgui.getInstanceWorldPosition(part)
		if pos then
			const dist = math.floor((root.Position - pos).Magnitude + 0.5)
			display = Format("%s | %d studs", baseName, dist)
		end
	end
	if billboard and billboard.Parent then
		pcall(function()
			billboard.Enabled = showPartText
		end)
	end
	if label then
		if showPartText then
			if label.Text ~= display then
				label.Text = display
			end
			if not label.Visible then
				label.Visible = true
			end
			NAgui.applyLabelStyle(label)
			if label.TextColor3 ~= labelColor then
				label.TextColor3 = labelColor
			end
		elseif label.Visible then
			label.Visible = false
		end
	end
	if drawingLabel then
		if showPartText then
			const textPos = NAgui.getInstanceLabelWorldPosition(part, 0.2)
			if not NAmanage.DrawingUpdateText(drawingLabel, textPos, display, labelColor, NAStuff.ESP_LabelTextSize, {
				outlineEnabled = NAStuff.ESP_DrawingPartTextOutline ~= false;
				centered = NAStuff.ESP_DrawingPartTextCentered ~= false;
				font = NAStuff.ESP_DrawingTextFont;
				textTransparency = NAStuff.ESP_DrawingPartTextTransparency;
			}) then
				NAmanage.ESP_RequestVisualRebuild()
				return
			end
		else
			pcall(function()
				drawingLabel.Visible = false
			end)
		end
	end
	const partDrawingStyle = NAgui.sanitizeESPDrawingBoxStyle(NAStuff.ESP_DrawingPartBoxStyle)
	if drawingSquare then
		if partDrawingStyle == "Corners" then
			pcall(function()
				drawingSquare.Visible = false
			end)
		elseif not NAmanage.DrawingUpdateSquare(drawingSquare, part, visualLight, transparency, {
			filled = NAStuff.ESP_DrawingPartFilledBoxes == true;
			thickness = NAStuff.ESP_DrawingPartBoxThickness;
		}) then
			NAmanage.ESP_RequestVisualRebuild()
			return
		end
	end
	if partDrawingStyle == "Corners" and type(drawingCornerLines) == "table" then
		local minX, minY, width, height = NAgui.getInstanceViewportBounds(part)
		if minX then
			const alpha = NAgui.toDrawingTransparency(transparency)
			const mainThickness = math.max(1, tonumber(NAStuff.ESP_DrawingPartBoxThickness) or 1)
			const outlineEnabled = NAStuff.ESP_DrawingPartBoxOutline ~= false
			const outlineThickness = math.max(1, tonumber(NAStuff.ESP_DrawingPartBoxOutlineThickness) or (mainThickness + 2))
			const scale = math.clamp(tonumber(NAStuff.ESP_DrawingPartCornerScale) or 0.25, 0.05, 0.5)
			const segX = math.max(4, width * scale)
			const segY = math.max(4, height * scale)
			const points = {
				{ Vector2.new(minX, minY), Vector2.new(minX + segX, minY) },
				{ Vector2.new(minX + width, minY), Vector2.new(minX + width - segX, minY) },
				{ Vector2.new(minX, minY + height), Vector2.new(minX + segX, minY + height) },
				{ Vector2.new(minX + width, minY + height), Vector2.new(minX + width - segX, minY + height) },
				{ Vector2.new(minX, minY), Vector2.new(minX, minY + segY) },
				{ Vector2.new(minX + width, minY), Vector2.new(minX + width, minY + segY) },
				{ Vector2.new(minX, minY + height), Vector2.new(minX, minY + height - segY) },
				{ Vector2.new(minX + width, minY + height), Vector2.new(minX + width, minY + height - segY) },
			}
			if outlineEnabled and type(drawingCornerOutlineLines) ~= "table" then
				drawingCornerOutlineLines = {}
			end
			for i = 1, 8 do
				const seg = points[i]
				if outlineEnabled then
					if not drawingCornerOutlineLines[i] then
						drawingCornerOutlineLines[i] = NAmanage.DrawingCreateLine(Color3.new(0.1, 0.1, 0.1), math.min(1, alpha + 0.15), outlineThickness)
					end
					if not NAmanage.DrawingUpdateLine(drawingCornerOutlineLines[i], seg[1], seg[2], Color3.new(0.1, 0.1, 0.1), math.min(1, alpha + 0.15), outlineThickness) then
						NAmanage.ESP_RequestVisualRebuild()
						return
					end
				elseif type(drawingCornerOutlineLines) == "table" and drawingCornerOutlineLines[i] then
					pcall(function() drawingCornerOutlineLines[i].Visible = false end)
				end
				if not NAmanage.DrawingUpdateLine(drawingCornerLines[i], seg[1], seg[2], visualLight, alpha, mainThickness) then
					NAmanage.ESP_RequestVisualRebuild()
					return
				end
			end
		else
			for i = 1, #(drawingCornerLines or {}) do
				pcall(function()
					drawingCornerLines[i].Visible = false
				end)
			end
			for i = 1, #(drawingCornerOutlineLines or {}) do
				pcall(function()
					drawingCornerOutlineLines[i].Visible = false
				end)
			end
		end
	end
	if visual and visual.Parent then
		NAmanage.ESP_StoreVisual(visual)
		if visual:IsA("Highlight") then
			if visual.Enabled ~= true then
				visual.Enabled = true
			end
			if visual.FillTransparency ~= transparency then
				visual.FillTransparency = transparency
			end
			const outlineTr = NAgui.sanitizeTransparency(NAStuff.ESP_OutlineTransparency or 0)
			if visual.FillColor ~= visualLight then
				visual.FillColor = visualLight
			end
			if visual.OutlineColor ~= visualDark then
				visual.OutlineColor = visualDark
			end
			if visual.OutlineTransparency ~= outlineTr then
				visual.OutlineTransparency = outlineTr
			end
		elseif visual:IsA("BoxHandleAdornment") then
			if visual.Visible ~= true then
				visual.Visible = true
			end
			if visual.Color3 ~= visualLight then
				visual.Color3 = visualLight
			end
			if visual.Transparency ~= transparency then
				visual.Transparency = transparency
			end
			if part:IsA("BasePart") then
				const desired = part.Size + Vector3.new(0.1,0.1,0.1)
				if visual.Size ~= desired then
					visual.Size = desired
				end
			end
		end
	end
end

NAmanage.PartESP_TryUpdate = function(entry, force, rootPart)
	if not entry or entry.removed then return true end
	const ok, err = pcall(NAmanage.PartESP_UpdateEntry, entry, force, rootPart)
	if ok then
		entry.updateError = nil
	else
		entry.updateError = tostring(err)
	end
	return ok
end

NAmanage.PartESP_UpdateTexts = function(force)
	const entries = NAStuff.partESPEntries
	if not entries then return end
	const now = tick()
	if not force and now < (NAStuff.partESPLastUpdate or 0) then return end
	NAStuff.partESPLastUpdate = now + 0.05
	if next(entries) == nil then
		NAStuff.partESPUpdateCursor = nil
		NAmanage.PartESP_StopHeartbeat()
		return
	end
	local rootPart
	if NAStuff.ESP_ShowPartDistance == true then
		const plr = Services.Players.LocalPlayer
		const char = plr and plr.Character
		rootPart = char and getRoot(char)
	end
	if force then
		for _, entry in table.clone(entries) do
			NAmanage.PartESP_TryUpdate(entry, true, rootPart)
		end
	else
		const perStep = math.clamp(math.max(math.floor(tonumber(NAStuff.ESP_PartUpdatePerStep) or 48), math.ceil((tonumber(NAStuff.partESPActiveCount) or 0) / 12)), 1, 256)
		local key = NAStuff.partESPUpdateCursor
		if key == nil or entries[key] == nil then key = next(entries) end
		const firstKey = key
		const pass = (tonumber(NAStuff.partESPUpdatePass) or 0) + 1
		NAStuff.partESPUpdatePass = pass
		for _ = 1, perStep do
			if key == nil then break end
			const entry = entries[key]
			if entry and entry.updatePass == pass then break end
			if entry then entry.updatePass = pass end
			NAStuff.partESPUpdateCursor = next(entries, key) or next(entries)
			NAmanage.PartESP_TryUpdate(entry, false, rootPart)
			key = NAStuff.partESPUpdateCursor
			if key == firstKey then break end
			if key ~= nil and entries[key] == nil then key = next(entries) end
		end
	end
	if next(entries) == nil then
		NAStuff.partESPUpdateCursor = nil
		NAmanage.PartESP_StopHeartbeat()
	end
end

NAmanage.PartESP_StartHeartbeat = function()
	const useDrawingSignal = NAgui.espUsesDrawing("part")
	const desiredSignal = useDrawingSignal and "RenderStepped" or "Heartbeat"
	if NAlib.isConnected("esp_part_update") then
		if NAStuff.partESPUpdateSignal == desiredSignal then
			return
		end
		NAlib.disconnect("esp_part_update")
	end
	NAStuff.partESPUpdateSignal = desiredSignal
	NAStuff.partESPLastUpdate = 0
	const signal = useDrawingSignal and Services.RunService.RenderStepped or Services.RunService.Heartbeat
	NAlib.connect("esp_part_update", signal:Connect(function()
		NAmanage.PartESP_UpdateTexts(false)
	end))
end

NAmanage.PartESP_StopHeartbeat = function()
	const entries = NAStuff.partESPEntries
	if entries and next(entries) then return end
	NAlib.disconnect("esp_part_update")
	NAStuff.partESPUpdateSignal = nil
end

NAmanage.PartESP_RegisterEntry = function(entry)
	if not entry then return end
	entry.entryKey = entry.entryKey or entry.billboard or entry.visual or entry.drawingSquare or entry.drawingLabel or entry.part
	if not entry.entryKey then return end
	NAStuff.partESPEntries[entry.entryKey] = entry
	if not entry._partESPCounted then
		entry._partESPCounted = true
		NAStuff.partESPActiveCount = (tonumber(NAStuff.partESPActiveCount) or 0) + 1
	end
	if entry.visual and typeof(entry.visual) == "Instance" then
		NAStuff.partESPVisualMap[entry.visual] = entry
	end
	if entry.part and typeof(entry.part) == "Instance" then
		local partMap = NAStuff.partESPPartMap
		if type(partMap) ~= "table" then
			partMap = NAmanage.ensureWeakTable(nil, "k")
			NAStuff.partESPPartMap = partMap
		else
			partMap = NAmanage.ensureWeakTable(partMap, "k")
			NAStuff.partESPPartMap = partMap
		end
		local bucket = partMap[entry.part]
		if type(bucket) ~= "table" then
			bucket = {}
			partMap[entry.part] = bucket
		end
		bucket[entry.entryKey] = entry
	end
	if entry.billboardCleanup then
		entry.billboardCleanup:Disconnect()
	end
	if entry.visualCleanup then
		entry.visualCleanup:Disconnect()
	end
	if entry.partCleanup then
		entry.partCleanup:Disconnect()
		entry.partCleanup = nil
	end
	if entry.partDestroyingCleanup then
		entry.partDestroyingCleanup:Disconnect()
		entry.partDestroyingCleanup = nil
	end
	if entry.billboard then
		entry.billboardCleanup = entry.billboard.AncestryChanged:Connect(function(_, parent)
			if not parent then
				NAmanage.PartESP_UnregisterEntry(entry)
			end
		end)
	end
	if entry.visual then
		entry.visualCleanup = entry.visual.AncestryChanged:Connect(function(_, parent)
			if not parent then
				NAmanage.PartESP_UnregisterEntry(entry)
			end
		end)
	end
	if entry.part and typeof(entry.part) == "Instance" then
		entry.partCleanup = entry.part.AncestryChanged:Connect(function(_, parent)
			if not parent then
				NAmanage.PartESP_UnregisterEntry(entry)
			end
		end)
		pcall(function()
			entry.partDestroyingCleanup = entry.part.Destroying:Connect(function()
				NAmanage.PartESP_UnregisterEntry(entry)
			end)
		end)
	end
	NAmanage.PartESP_StartHeartbeat()
	NAmanage.PartESP_TryUpdate(entry, true)
end

NAmanage.PartESP_UnregisterEntry = function(entry)
	if not entry or entry.removed then return end
	entry.removed = true
	NAmanage.ESP_LocatorRemoveArrow(entry)
	if entry.highlightMaterialTarget then
		const materialTarget = entry.highlightMaterialTarget
		entry.highlightMaterialTarget = nil
		NAmanage.ESP_AdjustHighlightMaterial(materialTarget, false, entry)
	end
	if entry.billboardCleanup then
		entry.billboardCleanup:Disconnect()
		entry.billboardCleanup = nil
	end
	if entry.visualCleanup then
		entry.visualCleanup:Disconnect()
		entry.visualCleanup = nil
	end
	if entry.partCleanup then
		entry.partCleanup:Disconnect()
		entry.partCleanup = nil
	end
	if entry.partDestroyingCleanup then
		entry.partDestroyingCleanup:Disconnect()
		entry.partDestroyingCleanup = nil
	end
	if entry.updateKey then
		NAlib.disconnect(entry.updateKey)
		entry.updateKey = nil
	end
	if entry.entryKey and NAStuff.partESPEntries then
		const entries = NAStuff.partESPEntries
		if NAStuff.partESPUpdateCursor == entry.entryKey then
			local nextKey = entries[entry.entryKey] and next(entries, entry.entryKey) or nil
			nextKey = nextKey or next(entries)
			NAStuff.partESPUpdateCursor = nextKey ~= entry.entryKey and nextKey or nil
		end
		entries[entry.entryKey] = nil
	end
	if entry._partESPCounted then
		entry._partESPCounted = nil
		NAStuff.partESPActiveCount = math.max(0, (tonumber(NAStuff.partESPActiveCount) or 1) - 1)
	end
	if entry.visual and typeof(entry.visual) == "Instance" and NAStuff.partESPVisualMap then
		NAStuff.partESPVisualMap[entry.visual] = nil
	end
	if entry.part and typeof(entry.part) == "Instance" and type(NAStuff.partESPPartMap) == "table" then
		const bucket = NAStuff.partESPPartMap[entry.part]
		if type(bucket) == "table" and entry.entryKey then
			bucket[entry.entryKey] = nil
			if not next(bucket) then
				NAStuff.partESPPartMap[entry.part] = nil
			end
		end
	end
	if entry.drawingSquare then
		NAmanage.DrawingRemoveObject(entry.drawingSquare)
		entry.drawingSquare = nil
	end
	if type(entry.drawingCornerLines) == "table" then
		for i = 1, #entry.drawingCornerLines do
			NAmanage.DrawingRemoveObject(entry.drawingCornerLines[i])
		end
		entry.drawingCornerLines = nil
	end
	if type(entry.drawingCornerOutlineLines) == "table" then
		for i = 1, #entry.drawingCornerOutlineLines do
			NAmanage.DrawingRemoveObject(entry.drawingCornerOutlineLines[i])
		end
		entry.drawingCornerOutlineLines = nil
	end
	if entry.drawingLabel then
		NAmanage.DrawingRemoveObject(entry.drawingLabel)
		entry.drawingLabel = nil
	end
	if entry.visual and typeof(entry.visual) == "Instance" then
		pcall(function()
			entry.visual:Destroy()
		end)
	end
	entry.visual = nil
	if entry.billboard then
		pcall(function()
			entry.billboard:Destroy()
		end)
	end
	entry.billboard = nil
	entry.label = nil
	NAmanage.PartESP_StopHeartbeat()
end

NAmanage.PartESP_RebuildVisuals = function()
	const entries = NAStuff.partESPEntries
	if not entries or not next(entries) then
		return
	end
	const grouped = {}
	for _, entry in entries do
		if entry and not entry.removed and entry.part and entry.part.Parent then
			local bucket = grouped[entry.part]
			if not bucket then
				bucket = {}
				grouped[entry.part] = bucket
			end
			bucket[#bucket+1] = {
				color = entry.baseColor or Color3.new(1,1,1),
				transparency = NAgui.sanitizeTransparency(NAStuff.ESP_PartTransparency or entry.transparency or 0.45),
			}
		end
	end
	for part, bucket in grouped do
		NAmanage.RemoveEspFromPart(part)
		for _, info in bucket do
			NAmanage.CreateBox(part, info.color, info.transparency)
		end
	end
	NAmanage.PartESP_UpdateTexts(true)
end

NAmanage.ESP_RebuildVisuals = function()
	for model, data in espCONS do
		if data then
			const wasEnabled = data.boxEnabled
			NAmanage.ESP_RemoveBoxes(model)
			if wasEnabled then
				NAmanage.ESP_AddBoxes(model)
			end
		end
	end
	NAmanage.PartESP_RebuildVisuals()
	NAmanage.PartESP_StartHeartbeat()
	if NAStuff.ESP_LocatorEnabled then
		NAmanage.ESP_LocatorEnable(true)
		NAmanage.ESP_LocatorApplyFlags()
	end
	if NAStuff.ESP_PlayerLocatorEnabled then
		NAmanage.ESP_PlayerLocatorEnable(true)
		NAmanage.ESP_PlayerLocatorApplyFlags()
	end
	NAmanage.ESP_ApplyLabelStyles()
end

function round(num,numDecimalPlaces)
	const mult=10^(numDecimalPlaces or 0)
	return math.floor(num*mult+0.5) / mult
end

function getPlaceInfo(forceRefresh)
	const cachedInfo = NAStuff and NAStuff._placeInfoCache
	if not forceRefresh and type(cachedInfo) == "table" then
		return cachedInfo
	end

	local success, result = pcall(function()
		return __lt.cm("MarketplaceService", "GetProductInfo", PlaceId)
	end)

	if not success or type(result) ~= "table" then
		return cachedInfo
	end

	if NAStuff then
		NAStuff._placeInfoCache = result
		NAStuff._placeInfoCacheAt = os.clock()
	end

	return result
end

function placeName()
	const info = getPlaceInfo()
	const name = info and NAlib.isProperty(info, "Name")
	return name or "unknown"
end

function placeIconAssetId()
	const info = getPlaceInfo()
	const icon = info and NAlib.isProperty(info, "IconImageAssetId")
	if typeof(icon) == "number" then
		return icon
	end
	if typeof(icon) == "string" then
		const digits = icon:match("(%d+)")
		if digits then
			const numeric = tonumber(digits)
			if numeric then
				return numeric
			end
		end
		const asNumber = tonumber(icon)
		if asNumber then
			return asNumber
		end
	end
	return nil
end

Defer(function()
	if NAmanage and NAmanage.btEnabled and NAmanage.btEnabled() then
		pcall(getPlaceInfo)
	end
end)

function SaveUIStroke(color)
	if typeof(color) ~= "Color3" then
		return
	end

	if NAStuff and NAStuff.AprilFoolsData then
		NAStuff.AprilFoolsData.originalColor = color
	end

	NAmanage.NASettingsSet("uiStroke", {
		R = color.R;
		G = color.G;
		B = color.B;
	})
end

function placeCreator()
	const info = getPlaceInfo()
	const creator = info and NAlib.isProperty(info, "Creator")
	const creatorName = creator and NAlib.isProperty(creator, "Name")
	return creatorName or "unknown"
end

NAmanage.ESP_Key = function(model)
	return tostring(model)
end

NAmanage.ESP_GetSecureHost = function()
	const host = (NAlib.huiGrabber and NAlib.huiGrabber())
		or Services.CoreGui
		or (Services.Players and Services.Players.LocalPlayer and Services.Players.LocalPlayer:FindFirstChildOfClass("PlayerGui"))
		or Services.Workspace.CurrentCamera
	if typeof(host) == "Instance" then
		return host
	end
	return nil
end

NAmanage.ESP_GetSecureAttrKey = function()
	local key = NAStuff.ESP_SecureAttrKey
	if type(key) == "string" and key ~= "" then
		return key
	end
	key = NAmanage.GenerateOpaqueSessionKey()
	NAStuff.ESP_SecureAttrKey = key
	return key
end

NAmanage.ESP_HardenVisual = function(inst)
	if typeof(inst) ~= "Instance" then
		return
	end
	pcall(function()
		inst.Archivable = false
	end)
	const secureAttrKey = NAmanage.ESP_GetSecureAttrKey()
	if NAmanage.GetAttr(inst, secureAttrKey) ~= true then
		NAmanage.SetAttr(inst, secureAttrKey, true)
		pcall(function()
			inst.Name = (NAgui.rStringgg and NAgui.rStringgg()) or "\0"
		end)
	end
	const hiddenSetter = (opt and opt.hiddenprop) or hiddenprop or sethiddenproperty or set_hidden_property or set_hidden_prop
	if hiddenSetter then
		pcall(function()
			hiddenSetter(inst, "RobloxLocked", true)
		end)
	end
end

NAmanage.ESP_EnsureSecureContainer = function()
	const host = NAmanage.ESP_GetSecureHost()
	if not host then
		return nil
	end
	local container = NAStuff.ESP_SecureContainer
	if container and not container.Parent then
		NAStuff.ESP_SecureContainer = nil
		container = nil
	end
	if not container then
		container = InstanceNew("Folder")
		NAStuff.ESP_SecureContainer = container
	end
	NAmanage.ESP_HardenVisual(container)
	if container.Parent ~= host then
		pcall(function()
			container.Parent = host
		end)
	end
	return container
end

NAmanage.ESP_StoreVisual = function(inst)
	if typeof(inst) ~= "Instance" then
		return nil
	end
	const container = NAmanage.ESP_EnsureSecureContainer()
	if not container then
		return nil
	end
	NAmanage.ESP_HardenVisual(inst)
	if inst.Parent ~= container then
		pcall(function()
			inst.Parent = container
		end)
	end
	return container
end

NAmanage.ESP_CollectTrackedBillboards = function(model, uid)
	const list = {}
	const seen = {}
	const function scan(root)
		if not (root and root.Parent) then
			return
		end
		for _, d in NAmanage.QueryDescendants(root, "BillboardGui") do
			if not seen[d] and NAmanage.GetAttr(d, "NA_ESP_UID") == uid then
				seen[d] = true
				list[#list + 1] = d
			end
		end
	end
	scan(model)
	scan(NAStuff.ESP_SecureContainer)
	return list
end

NAmanage.Helper_GetSecureHost = function()
	return Services.Workspace
end

NAmanage.Helper_EnsureSecureContainer = function()
