end

NAmanage.readAliasFile = function()
	if not (FileSupport and isfile(NAfiles.NAALIASPATH)) then
		return {}
	end

	local okRead, raw = pcall(readfile, NAfiles.NAALIASPATH)
	if not okRead or type(raw) ~= "string" then
		return {}
	end

	local okDecode, decoded = pcall(function()
		return Services.HttpService:JSONDecode(raw)
	end)
	if okDecode and type(decoded) == "table" then
		return decoded
	end

	const trimmed = raw:match("^%s*(.-)%s*$") or ""
	if trimmed ~= "" then
		const backupPath = NAfiles.NAALIASPATH .. ".corrupt_" .. tostring(os.time()) .. ".json"
		pcall(writefile, backupPath, raw)
		NAmanage.loaderWarn('Aliases', ('failed to decode storage; backed up to %s, resetting'):format(backupPath))
	end
	pcall(writefile, NAfiles.NAALIASPATH, Services.HttpService:JSONEncode({}))
	return {}
end

NAmanage.loadAliases = function()
	const aliasMap = NAmanage.readAliasFile()
	for alias, original in aliasMap do
		if type(alias) == "string" and type(original) == "string" then
			const aliasLower = alias:lower()
			const originalLower = original:lower()
			const command = cmds.Commands[originalLower]
			if command then
				cmds.Aliases[aliasLower] = command
				cmds.NASAVEDALIASES[aliasLower] = originalLower
			end
		end
	end
end

NAmanage.decodeUserButtons=function(raw)
	if type(raw) ~= "string" or raw == "" then
		return nil
	end
	local ok, decoded = pcall(function()
		return Services.HttpService:JSONDecode(raw)
	end)
	if ok and type(decoded) == "table" then
		return decoded
	end
	return nil
end

NAmanage.ubNorm=function(dt)
	const norm = {}
	local chg = false
	if type(dt) ~= "table" then
		return norm, false
	end
	for id, entry in dt do
		if type(id) == "number" then
			norm[id] = entry
		else
			chg = true
		end
	end
	for id, entry in dt do
		if type(id) == "string" then
			const n = tonumber(id)
			if n and norm[n] == nil then
				norm[n] = entry
				chg = true
			end
		end
	end
	return norm, chg
end

NAmanage.UserButtonsSave = function(reason, data)
	local pay = data or NAUserButtons or {}
	local norm, chg = NAmanage.ubNorm(pay)
	if chg then
		pay = norm
		if data == nil or data == NAUserButtons then
			NAUserButtons = norm
		end
	end

	if not FileSupport then
		return true
	end

	const path = NAfiles.NAUSERBUTTONSPATH
	const backupPath = path..".bak"
	local okEncode, encoded = pcall(Services.HttpService.JSONEncode, Services.HttpService, pay)
	if not okEncode then
		NAmanage.loaderWarn('UserButtons', 'failed to encode data'..(reason and (' ('..reason..')') or '')..': '..tostring(encoded))
		return false
	end

	local okRead, existing = pcall(readfile, path)
	if okRead and type(existing) == "string" and existing ~= "" then
		pcall(writefile, backupPath, existing)
	end

	local okWrite, errWrite = pcall(writefile, path, encoded)
	if not okWrite then
		if okRead and type(existing) == "string" then
			pcall(writefile, path, existing)
		end
		NAmanage.loaderWarn('UserButtons', 'failed to save data'..(reason and (' ('..reason..')') or '')..': '..tostring(errWrite))
		return false
	end

	return true
end

NAmanage.loadButtonIDS = function()
	if not FileSupport then
		NAUserButtons = NAUserButtons or {}
		return true
	end

	const path = NAfiles.NAUSERBUTTONSPATH

	if not (isfile and isfile(path)) then
		local okCreate, createErr = pcall(function()
			writefile(path, Services.HttpService:JSONEncode({}))
		end)
		if not okCreate then
			NAmanage.loaderWarn('UserButtons', 'failed to create storage: '..tostring(createErr))
			return false
		end
	end

	local okRead, raw = pcall(readfile, path)
	if not okRead or type(raw) ~= "string" then
		NAmanage.loaderWarn('UserButtons', 'failed to read storage: '..tostring(raw))
		return false
	end

	const decoded = NAmanage.decodeUserButtons(raw)
	if not decoded then
		local backup = nil
		local okBackup, rawBackup = pcall(readfile, path..".bak")
		if okBackup then
			backup = NAmanage.decodeUserButtons(rawBackup)
		end

		if backup then
			NAmanage.loaderWarn('UserButtons', 'storage corrupted; recovered from backup')
			NAUserButtons = backup
			NAmanage.UserButtonsSave("restore backup")
			return true
		end

		NAmanage.loaderWarn('UserButtons', 'invalid storage data; resetting')
		NAUserButtons = {}
		NAmanage.UserButtonsSave("reset invalid data")
		return false
	end

	local norm, normChg = NAmanage.ubNorm(decoded)
	NAUserButtons = norm
	local chg = normChg

	for _, data in NAUserButtons do
		if type(data) == "table" and type(data.Keybind) == "string" and data.Keybind ~= "" then
			const keyName = NAmanage.CKBNorm(data.Keybind) or data.Keybind

			if CommandKeybinds[keyName] == nil then
				const parts = {}
				if type(data.Cmd1) == "string" and data.Cmd1 ~= "" then
					Insert(parts, data.Cmd1)
				end
				if type(data.Args) == "table" then
					for _, v in data.Args do
						Insert(parts, tostring(v))
					end
				end
				if #parts > 0 then
					CommandKeybinds[keyName] = parts
				end
			end

			data.Keybind = nil
			chg = true
		end
	end

	if chg and FileSupport then
		NAmanage.UserButtonsSave("normalize ids")
	end
	NAmanage.SaveCommandKeybinds()
	NAmanage.ApplyCommandKeybinds()
	return true
end

function NAUserButtonNextId()
	local maxId = 0
	for id in NAUserButtons do
		if type(id) == "number" and id > maxId then
			maxId = id
		end
	end
	return maxId + 1
end

function NAUserButtonCloneAsChild(data, fallbackLabel)
	if type(data) ~= "table" then
		return nil
	end
	const label = (type(data.Label) == "string" and data.Label ~= "" and data.Label) or fallbackLabel or "Button"
	const child = {
		Label = label,
		Cmd1 = data.Cmd1,
		Cmd2 = data.Cmd2,
		Args = (type(data.Args) == "table") and originalIO.deepCopyTable(data.Args) or nil,
		ArgsSaved = data.ArgsSaved,
		RunMode = data.RunMode,
		BgColor = data.BgColor,
		TextColor = data.TextColor,
		Width = data.Width,
		Height = data.Height,
		CornerRadius = data.CornerRadius,
		Hidden = data.Hidden,
		Interactable = data.Interactable,
		Locked = data.Locked,
		Pos = data.Pos and originalIO.deepCopyTable(data.Pos),
	}
	return child
end

function NAUserButtonCollectChildren(store, entry, fallbackLabel)
	if type(entry) ~= "table" then
		return
	end
	if entry.Type == "group" and type(entry.Children) == "table" then
		for _, child in entry.Children do
			const clone = NAUserButtonCloneAsChild(child, fallbackLabel)
			if clone then
				Insert(store, clone)
			end
		end
	else
		const clone = NAUserButtonCloneAsChild(entry, fallbackLabel)
		if clone then
			Insert(store, clone)
		end
	end
end

function NAUserButtonRectOverlap(posA, sizeA, posB, sizeB, padding)
	padding = padding or 0
	if not (posA and sizeA and posB and sizeB) then return false end
	return not (
		posA.X + sizeA.X < posB.X - padding
			or posB.X + sizeB.X < posA.X - padding
			or posA.Y + sizeA.Y < posB.Y - padding
			or posB.Y + sizeB.Y < posA.Y - padding
	)
end

NAmanage.UserButtons_CombineButtons = function(targetId, sourceId, opts)
	opts = opts or {}
	if type(targetId) ~= "number" or type(sourceId) ~= "number" then
		return false, "Invalid button ids."
	end
	if targetId == sourceId then
		return false, "Pick two different buttons to combine."
	end

	const target = NAUserButtons[targetId]
	const source = NAUserButtons[sourceId]
	if type(target) ~= "table" or type(source) ~= "table" then
		return false, "One of the buttons is missing."
	end
	if target.Locked or source.Locked then
		return false, "Locked buttons cannot be combined."
	end

	const children = {}
	const targetLabel = (type(target.Label) == "string" and target.Label ~= "" and target.Label) or ("Button "..targetId)
	const sourceLabel = (type(source.Label) == "string" and source.Label ~= "" and source.Label) or ("Button "..sourceId)

	NAUserButtonCollectChildren(children, target, targetLabel)
	NAUserButtonCollectChildren(children, source, sourceLabel)

	target.Type = "group"
	target.Children = children
	target.GroupMode = (opts.mode == "side") and "side" or "dropdown"
	target.Cmd1, target.Cmd2, target.Args, target.RunMode = nil, nil, nil, nil

	NAUserButtons[sourceId] = nil
	originalIO.clearUserButtonState(sourceId)
	originalIO.clearUserButtonState(targetId)

	NAmanage.UserButtonsSave("combine buttons")

	return true, ("Grouped %d buttons"):format(#children)
end

NAmanage.UserButtons_CheckCombine = function(sourceId, sourceBtn)
	if type(sourceId) ~= "number" then
		return
	end
	if not (sourceBtn and sourceBtn.AbsolutePosition) then
		return
	end
	const sourceData = NAUserButtons[sourceId]
	if type(sourceData) ~= "table" or sourceData.Locked then
		return
	end

	const srcPos = sourceBtn.AbsolutePosition
	const srcSize = sourceBtn.AbsoluteSize
	local candidateId

	for id, btn in UserButtonGuiMap do
		if id ~= sourceId and btn and btn.Parent and btn.Visible then
			if NAUserButtonRectOverlap(srcPos, srcSize, btn.AbsolutePosition, btn.AbsoluteSize, 6) then
				candidateId = id
				break
			end
		end
	end

	if not candidateId then
		return
	end

	const targetData = NAUserButtons[candidateId]
	if type(targetData) ~= "table" or targetData.Locked then
		return
	end

	const srcLabel = (type(sourceData.Label) == "string" and sourceData.Label ~= "" and sourceData.Label) or ("Button "..sourceId)
	const targetLabel = (type(targetData.Label) == "string" and targetData.Label ~= "" and targetData.Label) or ("Button "..candidateId)

	Window({
		Title = "Combine User Buttons",
		Description = ("Merge [%d] %s into [%d] %s?"):format(sourceId, srcLabel, candidateId, targetLabel),
		Buttons = {
			{
				Text = "Dropdown Toggle",
				Callback = function()
					local ok, msg = NAmanage.UserButtons_CombineButtons(candidateId, sourceId, { mode = "dropdown" })
					if ok then
						DoNotif("Created dropdown group", 2)
						NAmanage.RenderUserButtons()
					else
						DoNotif(msg or "Failed to combine buttons", 3)
					end
				end
			},
			{
				Text = "Side Toggle",
				Callback = function()
					local ok, msg = NAmanage.UserButtons_CombineButtons(candidateId, sourceId, { mode = "side" })
					if ok then
						DoNotif("Created side group", 2)
						NAmanage.RenderUserButtons()
					else
						DoNotif(msg or "Failed to combine buttons", 3)
					end
				end
			},
			{
				Text = "Cancel",
				Callback = function() end
			},
		}
	})
end

NAmanage.UserButtons_Ungroup = function(groupId)
	if type(groupId) ~= "number" then
		return false, "Invalid group id"
	end
	const group = NAUserButtons[groupId]
	if type(group) ~= "table" or group.Type ~= "group" then
		return false, "Selected item is not a group"
	end

	const children = (type(group.Children) == "table") and group.Children or {}
	if #children == 0 then
		NAUserButtons[groupId] = nil
		originalIO.clearUserButtonState(groupId)
		NAmanage.UserButtonsSave("ungroup empty")
		return true, "Removed empty group"
	end

	const basePos = group.Pos
	local offset = 0
	const offsetStep = 70
	for _, child in children do
		const newId = NAUserButtonNextId()
		const clone = NAUserButtonCloneAsChild(child, child.Label)
		if basePos and type(basePos) == "table" then
			clone.Pos = {
				basePos[1] or 0,
				(basePos[2] or 0) + offset,
				basePos[3] or 0,
				basePos[4] or 0,
			}
			offset = offset + offsetStep
		else
			clone.Pos = nil
		end
		NAUserButtons[newId] = clone
	end

	NAUserButtons[groupId] = nil
	originalIO.clearUserButtonState(groupId)

	NAmanage.UserButtonsSave("ungroup")
	return true, ("Ungrouped %d buttons"):format(#children)
end

NAmanage.AutoExecSave = function(data, context)
	if not FileSupport then return true end

	const out = { commands = {} }
	const src = (type(data) == "table" and type(data.commands) == "table") and data.commands or {}

	for i = 1, #src do
		const it = src[i]
		local c, a

		if type(it) == "table" then
			c = it.c or it.cmd or it.command or it[1]
			a = it.a or it.args or it.arguments or it[2] or ""
		elseif type(it) == "string" then
			c = NAmanage.resolveCommandName(it:lower()) or it:lower()
			a = (type(data) == "table" and data.args and (data.args[it] or data.args[c])) or ""
		end

		if type(c) == "string" then
			if type(a) ~= "string" then
				a = tostring(a or "")
			end
			out.commands[#out.commands + 1] = { c = c:lower(), a = a }
		end
	end

	local ok, err = pcall(function()
		writefile(NAfiles.NAAUTOEXECPATH, Services.HttpService:JSONEncode(out))
	end)

	if not ok then
		if context == "loader" then
			NAmanage.loaderWarn("AutoExec", "failed to update storage: " .. tostring(err))
		else
			warn("[NA] AutoExec save failed: " .. tostring(err))
		end
	end

	return ok
end

NAmanage.loadAutoExec = function()
	const cur = NAEXECDATA or { commands = {}, args = {} }
	const path = NAfiles.NAAUTOEXECPATH

	if not FileSupport then
		NAEXECDATA = cur
		return true
	end

	if not (isfile and isfile(path)) then
		local okc, erc = pcall(function()
			writefile(path, Services.HttpService:JSONEncode({ commands = {}, args = {} }))
		end)
		if not okc then
			NAmanage.loaderWarn("AutoExec", "failed to create storage: " .. tostring(erc))
			return false
		end
	end

	local okr, raw = pcall(readfile, path)
	if not okr or type(raw) ~= "string" then
		NAmanage.loaderWarn("AutoExec", "failed to read storage: " .. tostring(raw))
		return false
	end

	local okd, dec = pcall(function()
		return Services.HttpService:JSONDecode(raw)
	end)

	if not okd or type(dec) ~= "table" then
		const tr = (type(raw) == "string") and raw:match("^%s*(.-)%s*$") or ""
		if tr == "" then
			dec = { commands = {}, args = {} }
		else
			const bkp = path .. ".corrupt_" .. tostring(os.time()) .. ".json"
			pcall(writefile, bkp, raw)
			NAmanage.loaderWarn("AutoExec", ("failed to decode storage; backed up to %s, resetting"):format(bkp))
			local okrs, er2 = pcall(function()
				writefile(path, Services.HttpService:JSONEncode({ commands = {}, args = {} }))
			end)
			if not okrs then
				NAmanage.loaderWarn("AutoExec", "failed to reset storage: " .. tostring(er2))
				return false
			end
			dec = { commands = {}, args = {} }
		end
	end

	local src = dec.commands
	local largs = dec.args

	if type(src) ~= "table" then
		if dec[1] ~= nil then
			src = dec
		else
			src = {}
		end
	end
	if type(largs) ~= "table" then
		largs = {}
	end

	const blk = (NAStuff and type(NAStuff.AutoExecBlockedCommands) == "table") and NAStuff.AutoExecBlockedCommands or {}

	local canRes = type(NAmanage.resolveCommandName) == "function"
		and type(cmds) == "table"
		and type(cmds.Commands) == "table"
		and type(cmds.Aliases) == "table"

	const out = {}
	const seen = {}
	local mod = false

	for i = 1, #src do
		const it = src[i]
		local rn, ra

		if type(it) == "string" then
			rn = it
			ra = largs[it] or ""
			mod = true
		elseif type(it) == "table" then
			rn = it.c or it.cmd or it.command or it[1]
			ra = it.a or it.args or it.arguments or it[2] or ""
		end

		if type(rn) == "string" then
			const low = rn:lower()
			local base = nil

			if canRes then
				local ok, res = pcall(NAmanage.resolveCommandName, low)
				if ok then
					base = res
				else
					canRes = false
				end
			end

			const cn = base or low

			if base and blk[base] then
				mod = true
			else
				if type(ra) ~= "string" then
					ra = tostring(ra or "")
					mod = true
				end

				const k = cn .. "\n" .. ra
				if not seen[k] then
					seen[k] = true
					out[#out + 1] = { c = cn, a = ra }
				else
					mod = true
				end
			end
		else
			mod = true
		end
	end

	const nd = { commands = out, args = {} }

	if mod then
		NAmanage.AutoExecSave(nd, "loader")
	end

	NAEXECDATA = nd
	return true
end

NAmanage.PluginNormalizePath = NAmanage.PluginNormalizePath or function(path)
	return Lower(tostring(path or ""):gsub("\\", "/"):gsub("/+", "/"))
end

NAmanage.PluginBaseName = NAmanage.PluginBaseName or function(path)
	return (tostring(path or ""):match("[^\\/]+$") or tostring(path or ""))
end

NAmanage.PluginIsIgnoredFile = NAmanage.PluginIsIgnoredFile or function(path)
	const base = NAmanage.PluginBaseName(path)
	return type(base) == "string" and base:lower() == "iy_fe.iy"
end

NAmanage.PluginDisabledMap = NAmanage.PluginDisabledMap or function()
	local stored = NAmanage.NASettingsGet and NAmanage.NASettingsGet("pluginDisabled") or {}
	if type(stored) ~= "table" then
		stored = {}
	end
	return stored
end

NAmanage.PluginSaveDisabledMap = NAmanage.PluginSaveDisabledMap or function(map)
	map = type(map) == "table" and map or {}
	if NAmanage.NASettingsSet then
		return NAmanage.NASettingsSet("pluginDisabled", map)
	end
	return map
end

NAmanage.PluginIsDisabled = NAmanage.PluginIsDisabled or function(path)
	const map = NAmanage.PluginDisabledMap()
	const key = NAmanage.PluginNormalizePath(path)
	const base = NAmanage.PluginBaseName(path)
	return map[key] == true or (base ~= "" and map[Lower(base)] == true)
end

NAmanage.PluginSetEnabled = NAmanage.PluginSetEnabled or function(path, enabled)
	const map = {}
	for k, v in NAmanage.PluginDisabledMap() do
		if v == true then
			map[k] = true
		end
	end
	const key = NAmanage.PluginNormalizePath(path)
	if key == "" then
		return false
	end
	if enabled then
		map[key] = nil
		const base = Lower(NAmanage.PluginBaseName(path))
		if base ~= "" then
			map[base] = nil
		end
	else
		map[key] = true
	end
	NAmanage.PluginSaveDisabledMap(map)
	return true
end

NAmanage.PluginListFiles = NAmanage.PluginListFiles or function(includeWorkspace)
	const entries = {}
	const function addDir(dir, kind, extPat)
		if type(dir) ~= "string" or dir == "" or not (isfolder and isfolder(dir)) then
			return
		end
		local ok, items = pcall(listfiles, dir)
		if not ok or type(items) ~= "table" then
			return
		end
		for _, path in items do
			if type(path) == "string" and Lower(path):match(extPat) and not NAmanage.PluginIsIgnoredFile(path) then
				const key = NAmanage.PluginNormalizePath(path)
				const meta = NAmanage._pluginFileMeta and NAmanage._pluginFileMeta[key] or nil
				Insert(entries, {
					path = path,
					key = key,
					name = NAmanage.PluginBaseName(path),
					kind = kind,
					enabled = not NAmanage.PluginIsDisabled(path),
					loaded = meta and meta.loaded == true or false,
					commands = meta and type(meta.commands) == "table" and meta.commands or {},
				})
			end
		end
	end
	addDir(NAfiles and NAfiles.NAPLUGINFILEPATH, ".na", "%.na$")
	addDir(NAfiles and NAfiles.NAIYPLUGINFILEPATH, ".iy", "%.iy$")
	table.sort(entries, function(a, b)
		if a.enabled ~= b.enabled then
			return a.enabled == true
		end
		if a.kind ~= b.kind then
			return tostring(a.kind) < tostring(b.kind)
		end
		return tostring(a.name):lower() < tostring(b.name):lower()
	end)
	return entries
end

NAmanage.PluginJoinPath = NAmanage.PluginJoinPath or function(dir, name)
	dir = tostring(dir or "")
	name = tostring(name or "")
	return (#dir > 0) and (dir.."/"..name) or name
end

NAmanage.PluginUniquePath = NAmanage.PluginUniquePath or function(dir, fileName)
	const name = tostring(fileName or "")
	local base, ext = name:match("^(.*)(%.[^%.]+)$")
	base, ext = base or name, ext or ""
	local path = NAmanage.PluginJoinPath(dir, name)
	if not (isfile and isfile(path)) then
		return path
	end
	local i = 1
	repeat
		path = NAmanage.PluginJoinPath(dir, Format("%s (%d)%s", base, i, ext))
		i += 1
	until not (isfile and isfile(path))
	return path
end

NAmanage.PluginWorkspaceRoot = NAmanage.PluginWorkspaceRoot or function()
	if not listfiles then return "" end
	for _, candidate in {"", ".", "/"} do
		local ok, items = pcall(listfiles, candidate)
		if ok and type(items) == "table" then
			return candidate
		end
	end
	return ""
end

NAmanage.PluginIsInstalledPath = NAmanage.PluginIsInstalledPath or function(path)
	const p = NAmanage.PluginNormalizePath(path)
	for _, dir in {NAfiles and NAfiles.NAPLUGINFILEPATH, NAfiles and NAfiles.NAIYPLUGINFILEPATH} do
		if type(dir) == "string" and dir ~= "" then
			const norm = NAmanage.PluginNormalizePath(dir):gsub("/+$", "")
			const tail = norm:match("([^/]+/[^/]+)$") or norm
			if p == norm or p:sub(1, #norm + 1) == (norm.."/") or p:find("/"..tail.."/", 1, true) then
				return true
			end
		end
	end
	return false
end

NAmanage.PluginListAvailable = NAmanage.PluginListAvailable or function()
	const entries = {}
	if not (listfiles and isfolder) then
		return entries
	end
	const function add(path)
		if type(path) ~= "string" or NAmanage.PluginIsIgnoredFile(path) or NAmanage.PluginIsInstalledPath(path) then
			return
		end
		const lowerPath = Lower(path)
		const kind = lowerPath:match("%.iy$") and ".iy" or (lowerPath:match("%.na$") and ".na" or nil)
		if not kind then return end
		Insert(entries, {
			path = path,
			key = NAmanage.PluginNormalizePath(path),
			name = NAmanage.PluginBaseName(path),
			kind = kind,
		})
	end
	const function scan(dir)
		local ok, items = pcall(listfiles, dir)
		if not ok or type(items) ~= "table" then return end
		for _, path in items do
			local okDir, isDir = pcall(isfolder, path)
			if okDir and isDir then
				if not NAmanage.PluginIsInstalledPath(path) then
					scan(path)
				end
			else
				add(path)
			end
		end
	end
	scan(NAmanage.PluginWorkspaceRoot())
	table.sort(entries, function(a, b)
		if a.kind ~= b.kind then
			return tostring(a.kind) < tostring(b.kind)
		end
		return tostring(a.name):lower() < tostring(b.name):lower()
	end)
	return entries
end

NAmanage.PluginAvailableCacheGet = NAmanage.PluginAvailableCacheGet or function(maxAge)
	const cache = NAStuff and NAStuff.PluginAvailableCache
	if type(cache) ~= "table" or type(cache.entries) ~= "table" then
		return nil
	end
	maxAge = tonumber(maxAge) or 30
	if maxAge > 0 and (tick() - (tonumber(cache.time) or 0)) > maxAge then
		return nil
	end
	return cache.entries
end

NAmanage.PluginScanAvailableAsync = NAmanage.PluginScanAvailableAsync or function(force, callback)
	if type(callback) == "function" then
		NAStuff.PluginAvailableCallbacks = NAStuff.PluginAvailableCallbacks or {}
		Insert(NAStuff.PluginAvailableCallbacks, callback)
	end
	if not force then
		const cached = NAmanage.PluginAvailableCacheGet and NAmanage.PluginAvailableCacheGet(30)
		if cached then
			const callbacks = NAStuff.PluginAvailableCallbacks or {}
			NAStuff.PluginAvailableCallbacks = {}
			for _, cb in callbacks do
				pcall(cb, cached)
			end
			return cached
		end
	end
	if NAStuff.PluginAvailableScanRunning then
		return nil
	end
	NAStuff.PluginAvailableScanRunning = true
	SpawnCall(function()
		const entries = {}
		const seen = {}
		const function add(path)
			if type(path) ~= "string" or seen[path] or NAmanage.PluginIsIgnoredFile(path) or NAmanage.PluginIsInstalledPath(path) then
				return
			end
			const lowerPath = Lower(path)
			const kind = lowerPath:match("%.iy$") and ".iy" or (lowerPath:match("%.na$") and ".na" or nil)
			if not kind then return end
			seen[path] = true
			Insert(entries, {
				path = path,
				key = NAmanage.PluginNormalizePath(path),
				name = NAmanage.PluginBaseName(path),
				kind = kind,
			})
		end
		const queue = {}
		if listfiles and isfolder then
			queue[1] = NAmanage.PluginWorkspaceRoot()
		end
		local head = 1
		local lastYield = os.clock()
		while head <= #queue do
			const dir = queue[head]
			head += 1
			local ok, items = pcall(listfiles, dir)
			if ok and type(items) == "table" then
				for _, path in items do
					local okDir, isDir = pcall(isfolder, path)
					if okDir and isDir then
						if not NAmanage.PluginIsInstalledPath(path) then
							Insert(queue, path)
						end
					else
						add(path)
					end
				end
			end
			if os.clock() - lastYield > 0.008 then
				Wait()
				lastYield = os.clock()
			end
		end
		table.sort(entries, function(a, b)
			if a.kind ~= b.kind then
				return tostring(a.kind) < tostring(b.kind)
			end
			return tostring(a.name):lower() < tostring(b.name):lower()
		end)
		NAStuff.PluginAvailableCache = {
			entries = entries,
			time = tick(),
		}
		NAStuff.PluginAvailableScanRunning = false
		const callbacks = NAStuff.PluginAvailableCallbacks or {}
		NAStuff.PluginAvailableCallbacks = {}
		for _, cb in callbacks do
			pcall(cb, entries)
		end
	end)
	return nil
end

NAmanage.PluginInstallFromWorkspace = NAmanage.PluginInstallFromWorkspace or function(path)
	if not FileSupport or type(path) ~= "string" or path == "" then
		return false, "file operations unavailable"
	end
	if NAmanage.PluginIsInstalledPath(path) then
		return false, "already installed"
	end
	const lowerPath = Lower(path)
	const dstDir = lowerPath:match("%.iy$") and (NAfiles and NAfiles.NAIYPLUGINFILEPATH) or (NAfiles and NAfiles.NAPLUGINFILEPATH)
	if type(dstDir) ~= "string" or dstDir == "" then
		return false, "plugin folder unavailable"
	end
	if not (isfolder and isfolder(dstDir)) and makefolder then
		pcall(makefolder, dstDir)
	end
	const fileName = NAmanage.PluginBaseName(path)
	if fileName == "" then
		return false, "invalid plugin path"
	end
	local okRead, data = pcall(readfile, path)
	if not okRead or data == nil then
		return false, "failed to read plugin"
	end
	const dst = NAmanage.PluginUniquePath(dstDir, fileName)
	const okWrite = pcall(writefile, dst, data)
	if not okWrite then
		return false, "failed to write plugin"
	end
	if delfile then
		const okDelete = pcall(delfile, path)
		if not okDelete then
			return false, "installed, but failed to delete original"
		end
	end
	NAmanage.PluginSetEnabled(dst, true)
	return true, dst
end

NAmanage.PluginNormalizeUrl = NAmanage.PluginNormalizeUrl or function(url)
	if typeof(url) ~= "string" then
		return nil
	end
	local t = url:match("^%s*(.-)%s*$") or ""
	if t == "" then
		return nil
	end
	t = t:gsub(" ", "%%20")
	const q = t:find("%?")
	const base = q and t:sub(1, q - 1) or t
	local owner, repo, kind, rest = base:match("^https?://github.com/([^/]+)/([^/]+)/([^/]+)/(.+)$")
	if owner and repo and kind and rest then
		local s = rest
		if s:sub(1, 11) == "refs/heads/" then
			s = s:sub(12)
		elseif s:sub(1, 10) == "refs/tags/" then
			s = s:sub(11)
		end
		local branch, path = s:match("^([^/]+)/(.+)$")
		if branch and path and (kind == "blob" or kind == "raw") then
			branch = branch:gsub("%%2[Ff]", "/")
			path = path:gsub("%%2[Ff]", "/")
			return Format("https://raw.githubusercontent.com/%s/%s/%s/%s", owner, repo, branch, path)
		end
	end
	if base:match("^https?://") then
		return t
	end
	return nil
end

NAmanage.PluginFileNameFromUrl = NAmanage.PluginFileNameFromUrl or function(url)
	if type(url) ~= "string" then return nil end
	const base = (url:match("^([^%?#]+)") or url):gsub("/+$", "")
	local name = base:match("/([^/]+)$") or ""
	name = name:gsub("%%20", " ")
	name = name:match("^%s*(.-)%s*$") or ""
	name = name:gsub("[^%w%._%-]", "_"):gsub("_+", "_"):gsub("^_+", ""):gsub("_+$", "")
	if name == "" then return nil end
	return name
end

NAmanage.PluginInstallFromUrl = NAmanage.PluginInstallFromUrl or function(url)
	if not FileSupport then
		return false, "file operations unavailable"
	end
	const norm = NAmanage.PluginNormalizeUrl(url)
	if not norm then
		return false, "enter a valid plugin URL"
	end
	const fileName = NAmanage.PluginFileNameFromUrl(norm)
	if not fileName then
		return false, "unable to determine plugin filename"
	end
	const lowerName = Lower(fileName)
	const kind = lowerName:match("%.iy$") and ".iy" or (lowerName:match("%.na$") and ".na" or nil)
	if not kind then
		return false, "plugin URL must end with .na or .iy"
	end
	local okFetch, data = pcall(function()
		return NAmanage.HttpGetOrError(norm)
	end)
	if not (okFetch and type(data) == "string" and data ~= "") then
		return false, "unable to download plugin"
	end
	const dstDir = kind == ".iy" and (NAfiles and NAfiles.NAIYPLUGINFILEPATH) or (NAfiles and NAfiles.NAPLUGINFILEPATH)
	if type(dstDir) ~= "string" or dstDir == "" then
		return false, "plugin folder unavailable"
	end
	if not (isfolder and isfolder(dstDir)) and makefolder then
		pcall(makefolder, dstDir)
	end
	const dst = NAmanage.PluginUniquePath(dstDir, fileName)
	local okWrite, errWrite = pcall(writefile, dst, data)
	if not okWrite then
		return false, errWrite or "unable to save plugin"
	end
	NAmanage.PluginSetEnabled(dst, true)
	return true, dst
end

NAmanage.PluginMoveToWorkspace = NAmanage.PluginMoveToWorkspace or function(path)
	if not FileSupport or type(path) ~= "string" or path == "" then
		return false, "file operations unavailable"
	end
	const name = NAmanage.PluginBaseName(path)
	if name == "" then
		return false, "invalid plugin path"
	end
	local okRead, data = pcall(readfile, path)
	if not okRead or data == nil then
		return false, "failed to read plugin"
	end
	const dst = NAmanage.PluginUniquePath("", name)
	const okWrite = pcall(writefile, dst, data)
	if not okWrite then
		return false, "failed to write workspace copy"
	end
	if delfile then
		const okDelete = pcall(delfile, path)
		if not okDelete then
			return false, "copied, but failed to delete original"
		end
	end
	NAmanage.PluginSetEnabled(path, true)
	return true, dst
end

NAmanage.PluginUserButtonRequestRender = NAmanage.PluginUserButtonRequestRender or function()
	if NAStuff and NAStuff.PluginUserButtonRenderPaused then
		NAStuff.PluginUserButtonsDirty = true
		return true
	end
	if NAmanage and type(NAmanage.RenderUserButtons) == "function" then
		return pcall(NAmanage.RenderUserButtons)
	end
	return false
end

NAmanage.PluginUserButtonClear = NAmanage.PluginUserButtonClear or function(pluginKey)
	if type(pluginKey) ~= "string" or pluginKey == "" then
		return false
	end
	NAPluginUserButtons = NAPluginUserButtons or {}
	const hadButtons = NAPluginUserButtons[pluginKey] ~= nil
	NAPluginUserButtons[pluginKey] = nil
	NAmanage._pluginUserButtonSpecs = NAPluginUserButtons
	if hadButtons then
		NAStuff.PluginUserButtonsDirty = true
	end
	return hadButtons
end

NAmanage.PluginUserButtonNormalize = NAmanage.PluginUserButtonNormalize or function(spec, label, command, command2)
	const data = {}
	if type(spec) == "table" then
		for k, v in spec do
			data[k] = v
		end
	else
		data.Label = label or spec
		data.Cmd1 = command
		data.Cmd2 = command2
	end

	local cmd1 = data.Cmd1 or data.Command or data.command or data.Cmd or data.cmd or data.Run or data.run or data[2]
	local cmd2 = data.Cmd2 or data.Command2 or data.command2 or data.OffCommand or data.offCommand or data.DisableCommand or data.disableCommand or data.ToggleOff or data.toggleOff or data[3]
	const buttonLabel = data.Label or data.label or data.Text or data.text or data.Name or data.name or data.Title or data.title or data[1] or cmd1

	if type(cmd1) == "table" then
		cmd1 = cmd1[1]
	end
	if type(cmd2) == "table" then
		cmd2 = cmd2[1]
	end
	if type(cmd1) ~= "string" or cmd1 == "" then
		return nil, "missing command"
	end

	local args = data.Args or data.args or data.Arguments or data.arguments
	if type(args) ~= "table" then
		args = nil
	end

	const out = {
		Id = data.Id or data.id or data.ButtonId or data.buttonId,
		Label = tostring(buttonLabel or cmd1),
		Cmd1 = tostring(cmd1),
		Cmd2 = (type(cmd2) == "string" and cmd2 ~= "") and tostring(cmd2) or nil,
		Args = args,
		ArgsSaved = data.ArgsSaved == true or data.argsSaved == true or args ~= nil,
		RunMode = (data.RunMode == "S" or data.SaveArgs == true or data.saveArgs == true) and "S" or "N",
		BgColor = data.BgColor or data.bgColor or data.BackgroundColor or data.backgroundColor,
		TextColor = data.TextColor or data.textColor,
		Width = data.Width or data.width,
		Height = data.Height or data.height,
		CornerRadius = data.CornerRadius or data.cornerRadius,
		Hidden = data.Hidden == true or data.hidden == true,
		Interactable = not (data.Interactable == false or data.interactable == false),
		Locked = data.Locked == true or data.locked == true,
		Pos = data.Pos or data.Position or data.position,
		MobileOnly = data.MobileOnly == true or data.mobileOnly == true,
		PCOnly = data.PCOnly == true or data.pcOnly == true or data.DesktopOnly == true or data.desktopOnly == true,
		PluginButton = true,
	}
	if out.Id ~= nil then
		out.Id = tostring(out.Id)
	end

	const mode = tostring(data.Mode or data.mode or data.Type or data.type or ""):lower()
	if mode == "toggle" and not out.Cmd2 then
		out.Cmd2 = data.Off or data.off or data.Disable or data.disable
	end

	return out
end

NAmanage.PluginUserButtonAdd = NAmanage.PluginUserButtonAdd or function(pluginKey, fileName, spec, command, command2)
	if NAStuff and NAStuff.PluginSettingsUIEnabled == false then
		return false, "plugin UI controls disabled"
	end
	if type(pluginKey) ~= "string" or pluginKey == "" then
		return false, "invalid plugin"
	end
	local button, err = NAmanage.PluginUserButtonNormalize(spec, spec, command, command2)
	if not button then
		return false, err or "invalid button"
	end
	if (button.MobileOnly == true or button.mobileOnly == true) and not IsOnMobile then
		return false, "mobile only"
	end
	if (button.PCOnly == true or button.pcOnly == true or button.DesktopOnly == true or button.desktopOnly == true) and not IsOnPC then
		return false, "pc only"
	end

	NAPluginUserButtons = NAPluginUserButtons or {}
	local bucket = NAPluginUserButtons[pluginKey]
	if not bucket then
		bucket = {
			name = tostring(fileName or "Plugin"),
			items = {},
		}
		NAPluginUserButtons[pluginKey] = bucket
	end
	bucket.items = bucket.items or {}
	local id = button.Id
	if type(id) ~= "string" or id == "" then
		id = (button.Label or "").."|"..(button.Cmd1 or "").."|"..(button.Cmd2 or "")
		button.Id = id
	end
	for i = #bucket.items, 1, -1 do
		const existing = bucket.items[i]
		if type(existing) == "table" and existing.Id == id then
			table.remove(bucket.items, i)
		end
	end
	Insert(bucket.items, button)
	NAmanage._pluginUserButtonSpecs = NAPluginUserButtons
	NAStuff.PluginUserButtonsDirty = true
	NAmanage.PluginUserButtonRequestRender()
	return true, button
end

NAmanage.PluginUserButtonRemove = NAmanage.PluginUserButtonRemove or function(pluginKey, query)
	if type(pluginKey) ~= "string" or pluginKey == "" then
		return false, "invalid plugin"
	end
	NAPluginUserButtons = NAPluginUserButtons or {}
	const bucket = NAPluginUserButtons[pluginKey]
	const items = type(bucket) == "table" and bucket.items or nil
	if type(items) ~= "table" then
		return false, "no buttons"
	end
	local raw = query
	if type(raw) == "table" then
		raw = raw.Id or raw.id or raw.ButtonId or raw.buttonId or raw.Label or raw.label or raw.Command or raw.command or raw.Cmd1 or raw.cmd1
	end
	const needle = raw ~= nil and tostring(raw):lower() or nil
	local removed = 0
	for i = #items, 1, -1 do
		const item = items[i]
		if needle == nil
			or tostring(item.Id or ""):lower() == needle
			or tostring(item.Label or ""):lower() == needle
			or tostring(item.Cmd1 or ""):lower() == needle then
			table.remove(items, i)
			removed += 1
		end
	end
	if removed > 0 then
		NAmanage._pluginUserButtonSpecs = NAPluginUserButtons
		NAStuff.PluginUserButtonsDirty = true
		NAmanage.PluginUserButtonRequestRender()
		return true, removed
	end
	return false, "button not found"
end

NAmanage.PluginUIClear = NAmanage.PluginUIClear or function(pluginKey)
	if type(pluginKey) ~= "string" or pluginKey == "" then
		return
	end
	NAmanage._pluginControlSpecs = NAmanage._pluginControlSpecs or {}
	NAmanage._pluginControlSpecs[pluginKey] = nil
	if NAmanage.PluginUserButtonClear then
		pcall(NAmanage.PluginUserButtonClear, pluginKey)
	end
end

NAmanage.PluginUIFor = NAmanage.PluginUIFor or function(pluginKey, fileName, mode)
	NAmanage._pluginControlSpecs = NAmanage._pluginControlSpecs or {}
	const key = type(pluginKey) == "string" and pluginKey or tostring(pluginKey or "")
	const label = tostring(fileName or "Plugin")
	const function push(kind, tabName, data)
		if NAStuff and NAStuff.PluginSettingsUIEnabled == false then
			return false
		end
		if key == "" then
			return false
		end
		local bucket = NAmanage._pluginControlSpecs[key]
		if not bucket then
			bucket = {
				name = label,
				kind = mode == "iy" and ".iy" or ".na",
				items = {},
			}
			NAmanage._pluginControlSpecs[key] = bucket
		end
		data = type(data) == "table" and data or {}
		data.kind = kind
		data.tabName = tostring(tabName or "Controls")
		Insert(bucket.items, data)
		return true
	end
	const function makeApi(tabName)
		const api = {}
		api.addSection = function(text)
			return push("section", tabName, { label = tostring(text or "") })
		end
		api.addButton = function(text, callback)
			return push("button", tabName, { label = tostring(text or "Button"), callback = callback })
		end
		api.addInput = function(text, placeholder, defaultText, callback)
			return push("input", tabName, {
				label = tostring(text or "Input"),
				placeholder = tostring(placeholder or ""),
				defaultText = tostring(defaultText or ""),
				callback = callback,
			})
		end
		api.addToggle = function(text, defaultValue, callback)
			return push("toggle", tabName, {
				label = tostring(text or "Toggle"),
				defaultValue = defaultValue == true,
				callback = callback,
			})
		end
		api.addUserButton = function(spec, command, command2)
			return NAmanage.PluginUserButtonAdd(key, label, spec, command, command2)
		end
		api.removeUserButton = function(query)
			return NAmanage.PluginUserButtonRemove(key, query)
		end
		api.clearUserButtons = function()
			return NAmanage.PluginUserButtonRemove(key)
		end
		api.addCommandButton = api.addUserButton
		api.addMobileButton = api.addUserButton
		api.addToggleButton = function(text, onCommand, offCommand, opts)
			opts = type(opts) == "table" and opts or {}
			opts.Label = opts.Label or text
			opts.Cmd1 = opts.Cmd1 or opts.Command or onCommand
			opts.Cmd2 = opts.Cmd2 or opts.Command2 or offCommand
			opts.Mode = opts.Mode or "toggle"
			return NAmanage.PluginUserButtonAdd(key, label, opts)
		end
		api.addTab = function(name)
			return makeApi(tostring(name or "Controls"))
		end
		return api
	end
	return makeApi("Controls")
end

-- PART 8 --
NAmanage.LoadPlugins = function(opts)
	opts = opts or {}
	const silent = opts.silent == true
	const forceNotify = opts.forceNotify == true
	if opts.startup == true and NAStuff and NAStuff.PluginAutoLoad == false then
		return true
	end
	if not CustomFunctionSupport then
		return true
	end

	const iyCallCtx = { args = nil, speaker = nil }

	const pluginDirNA = NAfiles.NAPLUGINFILEPATH
	const pluginDirIY = NAfiles.NAIYPLUGINFILEPATH
	const function ensureDir(dir, label)
		if not (isfolder and isfolder(dir)) then
			local ok, err = pcall(makefolder, dir)
			if not ok then
				NAmanage.loaderWarn(label, 'failed to ensure folder: '..tostring(err))
				return false
			end
		end
		return true
	end

	if not ensureDir(pluginDirNA, 'Plugins') then
		return false
	end
	if not ensureDir(pluginDirIY, 'PluginsIY') then
		return false
	end

	const function formatInfo(aliases, argsHint)
		const main = aliases[1]
		const extras = {}
		for i = 2, #aliases do
			Insert(extras, aliases[i])
		end
		local formatted = main
		if argsHint and argsHint ~= "" then
			formatted = formatted.." "..argsHint
		end
		if #extras > 0 then
			formatted = formatted.." ("..Concat(extras, ", ")..")"
		end
		return formatted
	end

	const function splitArgs(line)
		local out, buf, quote = {}, "", nil
		for i = 1, #line do
			const ch = Sub(line, i, i)
			if quote then
				if ch == quote then
					quote = nil
				else
					buf = buf..ch
				end
			else
				if ch == "'" or ch == '"' then
					quote = ch
				elseif ch == " " or ch == "\t" then
					if #buf > 0 then out[#out+1] = buf; buf = "" end
				else
					buf = buf..ch
				end
			end
		end
		if #buf > 0 then out[#out+1] = buf end
		return out
	end
	const remoteSrc = {}
	const function fetchRem(url, method)
		if type(url) ~= "string" or url == "" then
			return nil, "missing plugin url"
		end
		if remoteSrc[url] then return remoteSrc[url] end
		local hash = 5381
		for i = 1, #url do
			hash = (hash * 33 + string.byte(url, i)) % 4294967296
		end
		const key = Format("plugin_%08x", hash)
		const cached = NAAssetsLoading.readCachedScript(key, url)
		local ok, result, err = NAmanage.HttpGet(url, {
			noCache = if method == "HttpGetAsync" then nil else true,
			timeout = 10,
			maxAttempts = cached and 1 or nil,
		})
		if ok and type(result) == "string" and result ~= "" then
			local valid, chunk, why = pcall(loadstring, result, "@"..url)
			if valid and type(chunk) == "function" then
				remoteSrc[url] = result
				NAAssetsLoading.writeCachedScript(key, url, result)
				return result
			end
			err = why or chunk or "plugin source failed to compile"
		end
		if cached then
			remoteSrc[url] = cached
			return cached
		end
		err = tostring(err or "")
		if not err:find("%S") then err = "empty HTTP response" end
		return nil, Format("HTTP GET %s failed: %s", url, err)
	end

	const function stripPluginScanText(content)
		content = tostring(content or "")
		const out = {}
		local i = 1
		const len = #content
		while i <= len do
			const ch = Sub(content, i, i)
			const two = Sub(content, i, i + 1)
			if two == "--" then
				if Sub(content, i + 2, i + 3) == "[[" then
					const closeAt = Find(content, "]]", i + 4, true)
					i = closeAt and (closeAt + 2) or (len + 1)
				else
					const nl = Find(content, "\n", i + 2, true)
					i = nl and (nl + 1) or (len + 1)
				end
			out[#out + 1] = " "
		elseif two == "[[" then
				const closeAt = Find(content, "]]", i + 2, true)
				i = closeAt and (closeAt + 2) or (len + 1)
			out[#out + 1] = " "
		elseif ch == "'" or ch == '"' then
				const q = ch
			i += 1
				while i <= len do
					const c = Sub(content, i, i)
					if c == "\\" then
						i += 2
					elseif c == q then
						i += 1
						break
					else
						i += 1
					end
				end
			out[#out + 1] = " "
		else
			out[#out + 1] = ch
			i += 1
		end
		end
		return Concat(out)
	end

	const function hasNAPluginCommandAPI(content)
		if type(content) ~= "string" then
			return false
		end
		const scan = stripPluginScanText(content)
		const lowerTxt = Lower(scan)
		if lowerTxt:find("cmdpluginadd", 1, true) then
			return true
		end
		if lowerTxt:find("adduserbutton", 1, true)
			or lowerTxt:find("addcommandbutton", 1, true)
			or lowerTxt:find("addmobilebutton", 1, true)
			or lowerTxt:find("addtogglebutton", 1, true)
			or lowerTxt:find("removeuserbutton", 1, true)
			or lowerTxt:find("clearuserbuttons", 1, true)
			or lowerTxt:find("buttononrun", 1, true)
			or lowerTxt:find("userbuttononrun", 1, true)
			or lowerTxt:find(":%s*userbutton%s*%(")
			or lowerTxt:find(":%s*buttononrun%s*%(")
			or lowerTxt:find(":%s*togglebutton%s*%(") then
			return true
		end
		const hasBuilderRoot = lowerTxt:find("naplugin%s*%(")
			or lowerTxt:find("plugin%s*%.%s*new%s*%(")
			or lowerTxt:find("plugin%s*%.%s*create%s*%(")
			or lowerTxt:find("plugin%s*%(")
		const hasBuilderCmd = lowerTxt:find(":%s*cmd%s*%(")
			or lowerTxt:find(":%s*command%s*%(")
			or lowerTxt:find(":%s*addcommand%s*%(")
		if hasBuilderRoot and hasBuilderCmd then
			return true
		end
		if lowerTxt:find("command%s*%(") or lowerTxt:find("cmdplugin%s*%(") then
			return true
		end
		if lowerTxt:find("return%s*{") and lowerTxt:find("commands%s*=") then
			return true
		end
		return false
	end

	const function isNAPlugin(content)
		if type(content) ~= "string" then
			return false
		end
		if hasNAPluginCommandAPI(content) then
			return true
		end
		const seenRemote = {}
		local lastErr
		const loadPat = "loadstring%s*%(%s*game[:%.]([%w_]+)%s*%(%s*(['\"])(.-)%2"
		for method, _, url in content:gmatch(loadPat) do
			if url and url ~= "" and not seenRemote[url] then
				const methodLow = method and method:lower() or ""
				if methodLow == "httpget" or methodLow == "httpgetasync" then
					seenRemote[url] = true
					local remote, err = fetchRem(url, method)
					if remote and hasNAPluginCommandAPI(remote) then
						return true
					end
					lastErr = err or lastErr
				end
			end
		end
		return false, lastErr
	end

	const function isIYPlugin(content)
		if type(content) ~= "string" then
			return false
		end
		const lowerTxt = Lower(stripPluginScanText(content))
		if lowerTxt:find("pluginname", 1, true) and lowerTxt:find("commands", 1, true) then
			return true
		end
		if lowerTxt:find("plugindescription", 1, true) and lowerTxt:find("commands", 1, true) then
			return true
		end
		return false
	end

	const function appendIYCommands(out, iyPlugin)
		if type(out) ~= "table" or type(iyPlugin) ~= "table" then
			return
		end
		const commands = iyPlugin.Commands or iyPlugin.commands
		if type(commands) ~= "table" then
			return
		end

		const function pushCommand(nameKey, cmdDef)
			if type(cmdDef) ~= "table" then
				return
			end
			const listName = cmdDef.ListName or cmdDef.Name or nameKey
			if type(listName) ~= "string" or listName == "" then
				return
			end

			const iyFunc = cmdDef.Function or cmdDef.Callback
			if type(iyFunc) ~= "function" then
				return
			end

			const seen = {}
			const aliases = {}
			const function addAlias(a)
				if type(a) ~= "string" then
					return
				end
				local added = false
				for part in a:gmatch("[^/,|]+") do
					const trimmed = part:match("^%s*(.-)%s*$")
					if trimmed and trimmed ~= "" then
						const low = trimmed:lower()
						if not seen[low] then
							seen[low] = true
							Insert(aliases, trimmed)
						end
						added = true
					end
				end
				if not added and a ~= "" then
					const low = a:lower()
					if not seen[low] then
						seen[low] = true
						Insert(aliases, a)
					end
				end
			end

			addAlias(listName)
			addAlias(nameKey)
			const extra = cmdDef.Aliases
			if type(extra) == "table" then
				for _, a in extra do
					addAlias(a)
				end
			elseif type(extra) == "string" then
				addAlias(extra)
			end

			const argsHint = cmdDef.ArgsHint or cmdDef.Args or cmdDef.Arguments or ""
			const info = cmdDef.Description or cmdDef.Info or iyPlugin.PluginDescription or iyPlugin.Description or "No description"
			const requires = cmdDef.RequiresArguments or cmdDef.RequiresArgs or false
			local overrideAliases = cmdDef.OverrideAliases
			if overrideAliases == nil then overrideAliases = cmdDef.Override end
			if overrideAliases == nil then overrideAliases = cmdDef.ReplaceExisting end
			if overrideAliases == nil then overrideAliases = iyPlugin.OverrideAliases end
			if overrideAliases == nil then overrideAliases = iyPlugin.Override end
			const overrideText = tostring(overrideAliases or ""):lower()
			const overrideState = overrideAliases == true or overrideText == "true" or overrideText == "yes" or overrideText == "1"

			Insert(out, {
				Aliases = aliases,
				ArgsHint = (type(argsHint) == "string") and argsHint or "",
				Info = (type(info) == "string") and info or tostring(info),
				Function = function(...)
					const args = { ... }
					iyCallCtx.args = args
					iyCallCtx.speaker = LocalPlayer
					local ok, res = pcall(iyFunc, args, LocalPlayer)
					iyCallCtx.args = nil
					iyCallCtx.speaker = nil
					if not ok then
						error(res)
					end
					return res
				end,
				RequiresArguments = requires and true or false,
				OverrideAliases = overrideState,
			})
		end

		if #commands > 0 then
			for _, cmdDef in commands do
				pushCommand(cmdDef and (cmdDef.ListName or cmdDef.Name), cmdDef)
			end
			return
		end

		const keys = {}
		for k, v in commands do
			if type(v) == "table" then
				Insert(keys, k)
			end
		end
		table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
		for _, k in keys do
			pushCommand(k, commands[k])
		end
	end

	NAmanage._pluginCommandRecords = NAmanage._pluginCommandRecords or {}
	NAmanage._pluginCommandSources = NAmanage._pluginCommandSources or {}

	const function normKey(path)
		if not path then
			return ""
		end
		const normalized = path:gsub("\\","/")
		return Lower(normalized)
	end

	const function restoreDisplacedAliases(key, subset)
		const record = NAmanage._pluginCommandRecords[key]
		const displaced = subset or (record and record.displaced)
		if type(displaced) ~= "table" then
			return false
		end
		local changed = false
		const sourceMap = NAmanage._pluginCommandSources or {}
		for alias, saved in displaced do
			if type(saved) == "table" then
				const source = sourceMap[alias]
				const sourceKey = cmds.PluginSources and cmds.PluginSources[alias] or nil
				const occupiedByOtherPlugin = (type(source) == "table" and source.key and source.key ~= key)
					or (sourceKey ~= nil and sourceKey ~= key)
				if not occupiedByOtherPlugin then
					if cmds.Commands[alias] == nil and saved.command ~= nil then
						cmds.Commands[alias] = saved.command
						changed = true
					end
					if cmds.Aliases[alias] == nil and saved.alias ~= nil then
						cmds.Aliases[alias] = saved.alias
						changed = true
					end
				end
			end
			if subset and record and type(record.displaced) == "table" then
				record.displaced[alias] = nil
			end
		end
		if subset and record then
			const hasAliases = type(record.aliases) == "table" and next(record.aliases) ~= nil
			const hasDisplaced = type(record.displaced) == "table" and next(record.displaced) ~= nil
			if not hasAliases and not hasDisplaced then
				NAmanage._pluginCommandRecords[key] = nil
			end
		end
		return changed
	end

	const function UnplugCmd(key)
		if not key then
			return false
		end
		const record = NAmanage._pluginCommandRecords[key]
		const aliases = {}
		if record and type(record.aliases) == "table" then
			for alias, data in record.aliases do
				aliases[alias] = data
			end
		end
		if type(NAmanage._pluginCommandSources) == "table" then
			for alias, src in NAmanage._pluginCommandSources do
				if type(src) == "table" and src.key == key then
					aliases[alias] = src.data
				end
			end
		end
		if cmds.PluginSources then
			for alias, srcKey in cmds.PluginSources do
				if srcKey == key then
					aliases[alias] = aliases[alias] or cmds.Commands[alias] or cmds.Aliases[alias]
				end
			end
		end
		local hasAlias = false
		for _ in aliases do
			hasAlias = true
			break
		end
		if not record and not hasAlias then
			return false
		end
		local changed = false
		for alias, data in aliases do
			if data == nil or cmds.Commands[alias] == data then
				if cmds.Commands[alias] ~= nil then
					cmds.Commands[alias] = nil
					changed = true
				end
			end
			if data == nil or cmds.Aliases[alias] == data then
				if cmds.Aliases[alias] ~= nil then
					cmds.Aliases[alias] = nil
					changed = true
				end
			end
			if cmds.PluginSources and cmds.PluginSources[alias] ~= nil then
				cmds.PluginSources[alias] = nil
				changed = true
			end
			if type(NAmanage._pluginCommandSources) == "table" and NAmanage._pluginCommandSources[alias] ~= nil then
				NAmanage._pluginCommandSources[alias] = nil
				changed = true
			end
		end
		if restoreDisplacedAliases(key) then
			changed = true
		end
		NAmanage._pluginCommandRecords[key] = nil
		if type(NAmanage.invalidateCommandBuild) == "function" then
			pcall(NAmanage.invalidateCommandBuild)
		end
		return changed
	end

	const function AddCmdPlug(key, aliases, dataRef)
		if not key or not dataRef or type(aliases) ~= "table" then
			return
		end
		local record = NAmanage._pluginCommandRecords[key]
		if not record then
			record = { aliases = {}, displaced = {} }
			NAmanage._pluginCommandRecords[key] = record
		else
			record.aliases = record.aliases or {}
			record.displaced = record.displaced or {}
		end
		cmds.PluginSources = cmds.PluginSources or {}
		const sourceMap = NAmanage._pluginCommandSources
		for _, alias in aliases do
			if type(alias) == "string" and alias ~= "" then
				const lowerAlias = alias:lower()
				record.aliases[lowerAlias] = dataRef
				cmds.PluginSources[lowerAlias] = key
				if type(sourceMap) == "table" then
					sourceMap[lowerAlias] = { key = key, data = dataRef }
				end
			end
		end
	end

	const function formatAliasSwapNote(replacements)
		if not replacements then
			return nil
		end
		const parts = {}
		for from, to in replacements do
			parts[#parts + 1] = tostring(from).."→"..tostring(to)
		end
		if #parts == 0 then
			return nil
		end
		table.sort(parts)
		return "Conflicting aliases remapped: "..Concat(parts, ", ")
	end

	const function formatAliasOverrideNote(overrides)
		if type(overrides) ~= "table" then
			return nil
		end
		const parts = {}
		for _, displayName in overrides do
			parts[#parts + 1] = tostring(displayName)
		end
		if #parts == 0 then
			return nil
		end
		table.sort(parts)
		return "Overridden base aliases: "..Concat(parts, ", ")
	end

	const function makeUniqueAliases(key, aliases, allowCoreOverride)
		const out = {}
		const replaced = {}
		const overridden = {}
		const seenLocal = {}
		const sourceMap = NAmanage._pluginCommandSources or {}

		const function aliasConflict(lowerAlias, thisKey)
			const src = sourceMap[lowerAlias]
			const sourceKey = cmds.PluginSources and cmds.PluginSources[lowerAlias] or nil
			if (type(src) == "table" and src.key and src.key ~= thisKey)
				or (sourceKey ~= nil and sourceKey ~= thisKey) then
				return "plugin"
			end
			const commandData = cmds.Commands and cmds.Commands[lowerAlias] or nil
			const aliasData = cmds.Aliases and cmds.Aliases[lowerAlias] or nil
			if commandData ~= nil or aliasData ~= nil then
				if cmds.NASAVEDALIASES and cmds.NASAVEDALIASES[lowerAlias] ~= nil then
					return "saved"
				end
				if type(src) == "table" and src.key == thisKey then
					return nil
				end
				if sourceKey == thisKey then
					return nil
				end
				return "core"
			end
			return nil
		end

		const function reserveAlias(baseAlias)
			local counter = 1
			local attempt = "plugin:"..baseAlias
			local lower = attempt:lower()
			while aliasConflict(lower, key) ~= nil do
				counter += 1
				attempt = "plugin"..tostring(counter)..":"..baseAlias
				lower = attempt:lower()
			end
			return attempt, lower
		end

		for _, alias in aliases or {} do
			const name = tostring(alias or "")
			if name ~= "" then
				const lower = name:lower()
				if not seenLocal[lower] then
					seenLocal[lower] = true
					const conflict = aliasConflict(lower, key)
					if conflict == "core" and allowCoreOverride == true then
						overridden[lower] = name
						out[#out + 1] = name
					elseif conflict ~= nil then
						local newAlias, newLower = reserveAlias(name)
						replaced[name] = newAlias
						out[#out + 1] = newAlias
						seenLocal[newLower] = true
					else
						out[#out + 1] = name
					end
				end
			end
		end

		return out, replaced, overridden
	end

	const function displaceCoreAliases(key, aliases)
		if type(aliases) ~= "table" or next(aliases) == nil then
			return nil
		end
		local record = NAmanage._pluginCommandRecords[key]
		if not record then
			record = { aliases = {}, displaced = {} }
			NAmanage._pluginCommandRecords[key] = record
		else
			record.aliases = record.aliases or {}
			record.displaced = record.displaced or {}
		end
		const taken = {}
		const sourceMap = NAmanage._pluginCommandSources or {}
		for lowerAlias in aliases do
			const source = sourceMap[lowerAlias]
			const sourceKey = cmds.PluginSources and cmds.PluginSources[lowerAlias] or nil
			const savedAlias = cmds.NASAVEDALIASES and cmds.NASAVEDALIASES[lowerAlias] or nil
			if not (type(source) == "table" and source.key and source.key ~= key)
				and not (sourceKey ~= nil and sourceKey ~= key)
				and savedAlias == nil then
				const commandData = cmds.Commands[lowerAlias]
				const aliasData = cmds.Aliases[lowerAlias]
				if commandData ~= nil or aliasData ~= nil then
					const displaced = {
						command = commandData,
						alias = aliasData,
					}
					record.displaced[lowerAlias] = displaced
					taken[lowerAlias] = displaced
					cmds.Commands[lowerAlias] = nil
					cmds.Aliases[lowerAlias] = nil
				end
			end
		end
		return taken
	end

	const loadedSumm = {}
	const runMeta = {}
	const seenKeys = {}

	const function enumerate(dir, label, extPat)
		local okList, files = pcall(listfiles, dir)
		if not okList or type(files) ~= "table" then
			const errMsg = okList and "invalid directory listing" or tostring(files)
			NAmanage.loaderWarn(label, "failed to enumerate: "..errMsg)
			return nil
		end
		const out = {}
		for _, p in files do
			if type(p) == "string" and Lower(p):match(extPat) then
				Insert(out, p)
			end
		end
		return out
	end

	const filesNA = enumerate(pluginDirNA, "Plugins", "%.na$") or {}
	const filesIY = enumerate(pluginDirIY, "PluginsIY", "%.iy$") or {}

	NAmanage.PluginCleanupEnv = NAmanage.PluginCleanupEnv or function(key)
		const states = NAmanage and NAmanage._pluginEnvState
		const store = type(states) == "table" and states[key] or nil
		if type(store) ~= "table" then
			return
		end
		const seen = {}
		const function try(fn, owner)
			if type(fn) == "function" and not seen[fn] then
				seen[fn] = true
				pcall(fn, owner)
			end
		end
		const function scan(bucket)
			if type(bucket) ~= "table" then
				return
			end
			try(rawget(bucket, "cleanup"), bucket)
			try(rawget(bucket, "Cleanup"), bucket)
			try(rawget(bucket, "destroy"), bucket)
			try(rawget(bucket, "Destroy"), bucket)
			try(rawget(bucket, "unload"), bucket)
			try(rawget(bucket, "Unload"), bucket)
			for _, value in bucket do
				if type(value) == "table" then
					try(rawget(value, "cleanup"), value)
					try(rawget(value, "Cleanup"), value)
					try(rawget(value, "destroy"), value)
					try(rawget(value, "Destroy"), value)
					try(rawget(value, "unload"), value)
					try(rawget(value, "Unload"), value)
				end
			end
		end
		scan(store.globals)
		scan(store.shared)
	end

	const function loadPluginFile(file, mode)
		const baseName = file and (file:match("[^\\/]+$") or file) or ""
		if mode == "iy" and type(baseName) == "string" and baseName:lower() == "iy_fe.iy" then
			return
		end

		const pluginKey = normKey(file)
		seenKeys[pluginKey] = true
		UnplugCmd(pluginKey)
		if NAmanage.PluginCleanupEnv then
			pcall(NAmanage.PluginCleanupEnv, pluginKey)
		end

		const disabled = NAmanage.PluginIsDisabled and NAmanage.PluginIsDisabled(file)
		runMeta[pluginKey] = {
			path = file,
			name = baseName,
			kind = mode == "iy" and ".iy" or ".na",
			enabled = not disabled,
			loaded = false,
			commands = {},
		}
		if NAmanage.PluginUIClear then
			pcall(NAmanage.PluginUIClear, pluginKey)
		end
		if disabled then
			return
		end

		local success, content = NACaller({ context = "Plugin read: "..file }, readfile, file)
		if not (success and content) then
			DoWindow("[Plugin Read Error] Failed to read '"..file.."'")
			return
		end

		if mode == "na" then
			local valid, err = isNAPlugin(content)
			if not valid then
				if err then
					NAmanage.NACallerReportExternalError(err, err, nil, { context = "Plugin download: "..file })
				else
					DoWindow("skipped '"..file.."' (no plugin command API found)")
				end
				return
			end
		end

		local func, loadErr = loadstring(content, "@"..file)
		if not func then
			DoWindow("[Plugin Load Error] '"..file.."': "..tostring(loadErr))
			return
		end

		NAmanage._pluginEnvState = NAmanage._pluginEnvState or {}
		local pluginStore = NAmanage._pluginEnvState[pluginKey]
		if type(pluginStore) ~= "table" then
			pluginStore = {}
			NAmanage._pluginEnvState[pluginKey] = pluginStore
		end
		const colPlugins = {}
		const proxyEnv = {}
		const pluginShared = type(pluginStore.shared) == "table" and pluginStore.shared or {}
		const pluginGlobals = type(pluginStore.globals) == "table" and pluginStore.globals or {}
		pluginStore.shared = pluginShared
		pluginStore.globals = pluginGlobals
		pluginStore.env = proxyEnv
		const baseEnv = getfenv()
		local pluginApi = nil
		const pluginNil = {}
		const pluginEnvShims = {}
		const pluginPrivateEnv = {}
		const pluginBaseGlobals = {}
		const pluginBlockedGlobals = {
			_G = true;
			shared = true;
			getgenv = true;
			getfenv = true;
			setfenv = true;
			game = true;
			["workspace"] = true;
			SafeGetService = true;
			ServiceResolver = true;
			__NAServiceResolver = true;
			__NAUIProtector = true;
			__lt = true;
			NAmanage = true;
			NAStuff = true;
			NAindex = true;
			NAjobs = true;
			NAfiles = true;
			NAlib = true;
			cmds = true;
			cmd = true;
		}
		const function _plugMarkPrivate(env)
			if type(env) == "table" then
				pluginPrivateEnv[env] = true
			end
		end
		_plugMarkPrivate(baseEnv)
		_plugMarkPrivate(_na_env)
		_plugMarkPrivate(_na_shared)
		_plugMarkPrivate(_na_boot and _na_boot.runtimeEnv)
		_plugMarkPrivate(_na_boot and _na_boot.hostEnv)
		_plugMarkPrivate(_na_boot and _na_boot.privateRoot)
		const function _plugBase(name, value)
			if type(name) == "string" and value ~= nil then
				pluginBaseGlobals[name] = value
			end
		end
		for _, name in {
			"assert", "error", "ipairs", "next", "pairs", "pcall", "xpcall", "select", "tonumber", "tostring", "type", "typeof",
			"unpack", "rawequal", "rawget", "rawset", "setmetatable", "getmetatable", "print", "warn", "require",
			"wait", "spawn", "delay", "tick", "time", "elapsedTime", "gcinfo", "collectgarbage", "settings", "UserSettings", "version",
			"cloneref", "compareinstances", "hookfunction", "hookmetamethod", "getnamecallmethod", "setnamecallmethod", "newcclosure", "checkcaller", "getthreadidentity", "getidentity", "get_thread_identity", "setthreadidentity", "setidentity", "set_thread_identity",
			"iscclosure", "islclosure", "isexecutorclosure", "isourclosure", "restorefunction", "clonefunction", "getconnections", "firesignal", "replicatesignal",
			"firetouchinterest", "fireproximityprompt", "fireclickdetector", "getnilinstances", "getinstances", "gethui", "getcustomasset", "getgc", "filtergc",
			"setclipboard", "toclipboard", "queue_on_teleport", "queueonteleport", "identifyexecutor", "isfile", "isfolder", "readfile", "writefile", "appendfile", "listfiles", "makefolder", "delfile", "delfolder",
			"isrbxactive", "keypress", "keyrelease", "keytap", "mouse1click", "mouse1press", "mouse1release", "mouse2click", "mouse2press", "mouse2release", "mousemoveabs", "mousemoverel", "mousescroll",
		} do
			_plugBase(name, baseEnv and baseEnv[name])
		end
		for _, name in {
			"math", "string", "table", "task", "coroutine", "os", "utf8", "bit32", "debug", "Enum", "Instance", "Color3", "BrickColor",
			"Vector2", "Vector3", "Vector2int16", "Vector3int16", "CFrame", "UDim", "UDim2", "Rect", "Ray", "Region3", "Region3int16",
			"NumberRange", "NumberSequence", "NumberSequenceKeypoint", "ColorSequence", "ColorSequenceKeypoint", "TweenInfo", "PhysicalProperties",
			"RaycastParams", "OverlapParams", "Random", "DateTime", "Faces", "Axes", "Font", "PathWaypoint", "DockWidgetPluginGuiInfo", "buffer", "Drawing", "DrawingImmediate", "WebSocket", "crypt",
		} do
			_plugBase(name, baseEnv and baseEnv[name])
		end

		const function _plugResolveGlobal(...)
			for i = 1, select("#", ...) do
				const name = select(i, ...)
				local value = baseEnv and baseEnv[name] or nil
				if value == nil and _na_boot and type(_na_boot.hostEnv) == "table" then
					value = _na_boot.hostEnv[name]
				end
				if value ~= nil then
					return value
				end
			end
			return nil
		end

		const pluginSetHiddenProperty = _plugResolveGlobal(
			"sethiddenproperty", "set_hidden_property", "sethiddenprop", "set_hidden_prop"
		)
		if type(pluginSetHiddenProperty) == "function" then
			pluginBaseGlobals.sethiddenproperty = pluginSetHiddenProperty
			pluginBaseGlobals.set_hidden_property = pluginSetHiddenProperty
			pluginBaseGlobals.sethiddenprop = pluginSetHiddenProperty
			pluginBaseGlobals.set_hidden_prop = pluginSetHiddenProperty
			pluginBaseGlobals.sethidden = pluginSetHiddenProperty
		end

		const pluginGetHiddenProperty = _plugResolveGlobal(
			"gethiddenproperty", "get_hidden_property", "gethiddenprop", "get_hidden_prop"
		)
		if type(pluginGetHiddenProperty) == "function" then
			pluginBaseGlobals.gethiddenproperty = pluginGetHiddenProperty
			pluginBaseGlobals.get_hidden_property = pluginGetHiddenProperty
			pluginBaseGlobals.gethiddenprop = pluginGetHiddenProperty
			pluginBaseGlobals.get_hidden_prop = pluginGetHiddenProperty
			pluginBaseGlobals.gethidden = pluginGetHiddenProperty
		end

		for _, name in {"setscriptable", "isscriptable"} do
			const value = _plugResolveGlobal(name)
			if type(value) == "function" then
				pluginBaseGlobals[name] = value
			end
		end

		const function _plugCleanEnv(env)
			if type(env) ~= "table" or pluginPrivateEnv[env] then
				return proxyEnv
			end
			return env
		end
		pluginEnvShims._G = proxyEnv
		pluginEnvShims.shared = pluginShared
		pluginEnvShims.getgenv = function()
			return proxyEnv
		end
		pluginEnvShims.getfenv = function(target)
			if target == nil or type(target) == "number" then
				return proxyEnv
			end
			const hostGetfenv = baseEnv and baseEnv.getfenv or getfenv
			if type(hostGetfenv) == "function" then
				local ok, env = pcall(hostGetfenv, target)
				if ok then
					return _plugCleanEnv(env)
				end
			end
			return proxyEnv
		end
		pluginEnvShims.setfenv = function(fn, env)
			const hostSetfenv = baseEnv and baseEnv.setfenv or setfenv
			if type(hostSetfenv) == "function" and type(fn) == "function" then
				return hostSetfenv(fn, _plugCleanEnv(env))
			end
			return fn
		end

		const function _runCmd(...)
			const runner = cmd and (cmd.run or cmd.Run)
			if not runner then return nil, "cmd.run not available" end
			const n = select("#", ...)
			local argv
			if n == 1 then
				const a = ...
				if type(a) == "table" then
					argv = a
				elseif type(a) == "string" then
					argv = splitArgs(a)
				else
					return nil, "invalid input to runCommand"
				end
			else
				argv = {}
				for i = 1, n do
					const v = select(i, ...)
					argv[#argv+1] = type(v) == "string" and v or tostring(v)
				end
			end
			local ok1, res1 = NACaller(runner, argv)
			if ok1 then return res1 end
			local ok2, res2 = NACaller(runner, Concat(argv, " "))
			if ok2 then return res2 end
			return nil, res2
		end

		const function _pluginRequest(opts)
			const rq = resolvedRequest or opt.NAREQUEST
			if type(rq) ~= "function" then
				return { StatusCode = 0, Body = "HTTP unavailable" }
			end
			if type(opts) == "table" then
				if type(opts.HttpRequestType) == "boolean" then
					opts = table.clone and table.clone(opts) or { }
					if not table.clone then
						for k, v in opts do opts[k] = v end
					end
					opts.HttpRequestType = nil
				end
			end
			local ok, res = pcall(rq, opts)
			if ok then
				return res
			end
			return { StatusCode = 0, Body = tostring(res) }
		end

		const pluginServiceNames = setmetatable({
			Workspace = true;
			Players = true;
			CoreGui = true;
			ReplicatedFirst = true;
			ReplicatedStorage = true;
			Lighting = true;
			StarterGui = true;
			StarterPack = true;
			StarterPlayer = true;
			ServerScriptService = true;
			ServerStorage = true;
			Teams = true;
			Debris = true;
			Stats = true;
			Chat = true;
			Selection = true;
			NetworkClient = true;
			NetworkServer = true;
			DebugSettings = true;
			ScriptContext = true;
			KeyframeSequenceProvider = true;
			VirtualInputManager = true;
			VirtualUser = true;
		}, {
			__index = function(_, name)
				return type(name) == "string" and (name:match("Service$") ~= nil or name:match("Provider$") ~= nil)
			end
		})
		const pluginServiceAliases = {
			["workspace"] = "Workspace";
			COREGUI = "CoreGui";
			CoreGui = "CoreGui";
			UIS = "UserInputService";
		}
		const rawGame = game
		const pluginServiceCache = {}
		const function _plugServiceName(name)
			if type(name) ~= "string" then
				return nil
			end
			name = pluginServiceAliases[name] or name
			if not name:match("^[%a_][%w_]*$") then
				return nil
			end
			return name
		end
		const function _plugGetRawService(name)
			name = _plugServiceName(name)
			if not name then
				return nil
			end
			if type(__lt) == "table" and type(__lt.gs) == "function" then
				local ok, svc = pcall(__lt.gs, name)
				if ok and typeof(svc) == "Instance" then
					return svc
				end
			end
			return nil
		end
		const function _plugGetService(name)
			name = _plugServiceName(name)
			if not name then
				return nil
			end
			if pluginServiceCache[name] ~= nil then
				return pluginServiceCache[name]
			end
			local svc
			if type(__lt) == "table" then
				if type(cloneref) == "function" and type(__lt.cs) == "function" then
					local ok, resolved = pcall(__lt.cs, name, cloneref)
					if ok and typeof(resolved) == "Instance" then
						svc = resolved
					end
				end
				if not svc and type(__lt.gs) == "function" then
					local ok, resolved = pcall(__lt.gs, name)
					if ok and typeof(resolved) == "Instance" then
						svc = resolved
					end
				end
			end
			if not svc then
				const rawSvc = _plugGetRawService(name)
				if rawSvc then
					if type(__lt) == "table" and type(__lt.cv) == "function" then
						local okRef, cloned = pcall(__lt.cv, rawSvc)
						if okRef and typeof(cloned) == "Instance" then
							svc = cloned
						end
					end
					svc = svc or rawSvc
				end
			end
			if svc then
				pluginServiceCache[name] = svc
			end
			return svc
		end
		const pluginResolverFacade = {}
		pluginResolverFacade.gs = function(selfOrName, maybeName)
			local name = maybeName or selfOrName
			return _plugGetRawService(name)
		end
		pluginResolverFacade.cs = function(selfOrName, maybeName)
			local name = maybeName or selfOrName
			return _plugGetService(name)
		end
		pluginResolverFacade.GetService = pluginResolverFacade.cs
		pluginResolverFacade.getService = pluginResolverFacade.cs
		pluginResolverFacade.GetRawService = pluginResolverFacade.gs
		pluginResolverFacade.getRawService = pluginResolverFacade.gs
		proxyEnv.ServiceResolver = pluginResolverFacade
		proxyEnv.SafeGetService = pluginResolverFacade.cs

		const gameProxy = {}
		function gameProxy:GetService(serviceName)
			return _plugGetService(serviceName)
		end
		function gameProxy:FindService(serviceName)
			return _plugGetService(serviceName)
		end
		function gameProxy:FindFirstChild(name, recursive)
			return _plugGetService(name)
		end
		function gameProxy:WaitForChild(name, timeout)
			const service = _plugGetService(name)
			if service then
				return service
			end
			if timeout ~= nil then
				Wait(math.min(tonumber(timeout) or 0, 0.1))
			end
			return nil
		end
		function gameProxy:HttpGet(url, second)
			const body = remoteSrc[url]
			if body then
				remoteSrc[url] = nil
				return body
			end
			return NAmanage.HttpGetOrError(url, { noCache = if type(second) == "boolean" then second else nil, timeout = 10 })
		end
		function gameProxy:HttpGetAsync(url, second)
			return gameProxy.HttpGet(self, url, second)
		end
		const pluginGameAllowedMembers = {
			PlaceId = true;
			JobId = true;
			GameId = true;
			CreatorId = true;
			CreatorType = true;
			Name = true;
			IsLoaded = true;
			Loaded = true;
		}
		setmetatable(gameProxy, {
			__index = function(_, k)
				if k == "GetService" then
					return gameProxy.GetService
				end
				if k == "FindService" then
					return gameProxy.FindService
				end
				if k == "FindFirstChild" then
					return gameProxy.FindFirstChild
				end
				if k == "WaitForChild" then
					return gameProxy.WaitForChild
				end
				if k == "HttpGet" then
					return gameProxy.HttpGet
				end
				if k == "HttpGetAsync" then
					return gameProxy.HttpGetAsync
				end
				if type(k) == "string" and (pluginServiceNames[k] or k:match("^[%a_][%w_]*$")) then
					local service = gameProxy:GetService(k)
					if service then
						return service
					end
				end
				if not pluginGameAllowedMembers[k] then
					return nil
				end
				const v = rawGame[k]
				if type(v) == "function" then
					return function(_, ...)
						return v(rawGame, ...)
					end
				end
				return v
