	NAmanage.PluginMaker_ServiceVar = function(name)
		name = tostring(name or ""):gsub("[^%w_]", "_")
		if name == "" then
			return nil
		end
		local reserved = {
			["and"] = true; ["break"] = true; ["do"] = true; ["else"] = true; ["elseif"] = true;
			["end"] = true; ["false"] = true; ["for"] = true; ["function"] = true; ["if"] = true;
			["in"] = true; ["local"] = true; ["nil"] = true; ["not"] = true; ["or"] = true;
			["repeat"] = true; ["return"] = true; ["then"] = true; ["true"] = true; ["until"] = true;
			["while"] = true; ["continue"] = true; ["export"] = true; ["type"] = true;
		}
		if name:match("^%d") or reserved[name] then
			name = "Service_"..name
		end
		return name
	end

	NAmanage.PluginMaker_NormalizeServices = function()
		local pm = NAStuff.PluginMaker
		pm.selectedServices = type(pm.selectedServices) == "table" and pm.selectedServices or {}
		pm.customServices = type(pm.customServices) == "table" and pm.customServices or {}
		local clean = {}
		for name, enabled in pm.selectedServices do
			name = NAmanage.PluginMaker_Trim(name)
			if enabled == true and name:match("^[%a_][%w_]*$") then
				clean[name] = true
			end
		end
		pm.selectedServices = clean
		return clean
	end

	NAmanage.PluginMaker_GetServiceCatalog = function()
		local pm = NAStuff.PluginMaker
		local out, seen = {}, {}
		local function add(name)
			name = NAmanage.PluginMaker_Trim(name)
			if name == "" or not name:match("^[%a_][%w_]*$") then
				return
			end
			local key = name:lower()
			if not seen[key] then
				seen[key] = true
				out[#out + 1] = name
			end
		end
		for _, name in NAmanage.PluginMaker_ServiceCatalog do
			add(name)
		end
		for _, name in pm.customServices or {} do
			add(name)
		end
		pcall(function()
			for _, child in game:GetChildren() do
				if typeof(child) == "Instance" then
					add(child.ClassName)
				end
			end
		end)
		table.sort(out, function(a, b)
			local sa = pm.selectedServices and pm.selectedServices[a] == true
			local sb = pm.selectedServices and pm.selectedServices[b] == true
			if sa ~= sb then
				return sa
			end
			return a:lower() < b:lower()
		end)
		return out
	end

	NAmanage.PluginMaker_GetSelectedServices = function()
		local selected = NAmanage.PluginMaker_NormalizeServices()
		local out = {}
		for name, enabled in selected do
			if enabled == true then
				out[#out + 1] = name
			end
		end
		table.sort(out, function(a, b)
			return a:lower() < b:lower()
		end)
		return out
	end

	NAmanage.PluginMaker_ServicePrelude = function()
		const lines = { [=[
local ServiceResolver = ServiceResolver
local function resolve(name)
	if type(ServiceResolver) == "table" then
		local lookup = ServiceResolver.cs or ServiceResolver.gs
		if type(lookup) == "function" then
			local ok, service = pcall(lookup, name)
			if ok and service then return service end
		end
	end
	local ok, service = pcall(game.GetService, game, name)
	if ok then return service end
end
local Services = setmetatable({}, {
	__index = function(self, name)
		local service = resolve(name)
		if service then rawset(self, name, service) end
		return service
	end,
})
]=] }
		for _, name in NAmanage.PluginMaker_GetSelectedServices() do
			const var = NAmanage.PluginMaker_ServiceVar(name)
			if var and var ~= "Services" and var ~= "ServiceResolver" then
				lines[#lines + 1] = "local "..var.." = Services["..NAmanage.PluginMaker_Quote(name).."]"
			end
		end
		if NAStuff.PluginMaker.selectedServices.Players then
			lines[#lines + 1] = "local LocalPlayer = Players and Players.LocalPlayer"
		end
		return table.concat(lines, "\n")
	end

	NAmanage.PluginMaker_AppendRaw = function(lines, code, indent)
		if type(lines) ~= "table" then
			return
		end
		code = tostring(code or "")
		if code == "" then
			return
		end
		indent = tostring(indent or "")
		for line in (code.."\n"):gmatch("(.-)\n") do
			lines[#lines + 1] = indent..line
		end
	end

	NAmanage.PluginMaker_IYContext = function()
		return [=[
local function __na_pm_context(player)
	local input = Services.UserInputService
	local mobile = IsOnMobile == true or IsOnMobile == nil and input and input.TouchEnabled and not input.KeyboardEnabled
	return {
		LocalPlayer = player, Player = player, Services = Services, ServiceResolver = ServiceResolver,
		IsOnMobile = mobile == true, IsOnPC = IsOnPC == true or IsOnPC == nil and not mobile,
		notify = function(_, message, duration)
			if type(DoNotif) == "function" then return DoNotif(message, duration) end
			if type(notify) == "function" then
				if type(execCmd) == "function" then return notify("Plugin", message, duration) end
				return notify(message, duration)
			end
			error("Notifications are unavailable.")
		end,
		run = function(_, ...)
			if type(cmdRun) == "function" then return cmdRun(...) end
			if type(RunCommand) == "function" then return RunCommand(...) end
			if type(execCmd) == "function" then
				local args = ...
				local text = type(args) == "table" and table.concat(args, " ") or table.concat({ ... }, " ")
				return execCmd((text:gsub("\\", "\\\\")), player)
			end
			error("Command runner is unavailable.")
		end,
		addUserButton = function(_, ...)
			if type(addUserButton) == "function" then return addUserButton(...) end
		end,
		removeUserButton = function(_, ...)
			if type(removeUserButton) == "function" then return removeUserButton(...) end
		end,
	}
end
]=]
	end

	NAmanage.PluginMaker_CommandCall = function(text)
		const args = NAmanage.MCPNormalizeArgs(text)
		if not args then return nil end
		const parts = {}
		for i, arg in args do
			parts[i] = "__na_pm_fill("..NAmanage.PluginMaker_Quote(arg)..", args, player)"
		end
		return "local ok, err = ctx:run({"..table.concat(parts, ", ").."}); if ok == false then error(err or \"Command failed.\", 0) end"
	end

	NAmanage.PluginMaker_ActionLines = function(action)
		const kind = action.type
		const val = NAmanage.PluginMaker_Quote(action.value)
		const fill = "__na_pm_fill("..val..", args, player)"
		if kind == "notify" or kind == "mobile_notify" or kind == "pc_notify" then
			const sec = math.clamp(tonumber(action.extra) or 3, 0.1, 30)
			const line = "ctx:notify("..fill..", "..tostring(sec)..")"
			if kind == "mobile_notify" then return { "if ctx.IsOnMobile then "..line.." end" } end
			if kind == "pc_notify" then return { "if ctx.IsOnPC then "..line.." end" } end
			return { line }
		elseif kind == "run" or kind == "mobile_run" or kind == "pc_run" then
			const line = NAmanage.PluginMaker_CommandCall(action.value)
			if kind == "mobile_run" then return { "if ctx.IsOnMobile then "..line.." end" } end
			if kind == "pc_run" then return { "if ctx.IsOnPC then "..line.." end" } end
			return { "do "..line.." end" }
		elseif kind == "recording" then
			return { "ctx:run({\"playrecord\", "..val.."})" }
		elseif kind == "wait" then
			return { "task.wait("..tostring(math.clamp(tonumber(action.value) or 1, 0, 120))..")" }
		elseif kind == "print" then
			return { "print("..fill..")" }
		elseif kind == "copy" then
			return { "if type(setclipboard) == \"function\" then setclipboard("..fill..") end" }
		elseif kind == "add_button" then
			return { "ctx:addUserButton({ Label = "..val..", Command = "..NAmanage.PluginMaker_Quote(action.extra)..", SaveArgs = true })" }
		elseif kind == "remove_button" then
			return { "ctx:removeUserButton("..fill..")" }
		elseif kind == "stop" then
			return { "do return end" }
		elseif kind == "load_url" then
			return { "do", "\tlocal loader = assert(loadstring or load, \"Script loading is unavailable.\")",
				"\tassert(loader(game:HttpGet("..fill..")))()", "end" }
		elseif kind == "custom" then
			const lines = {}
			NAmanage.PluginMaker_AppendRaw(lines, action.value, "")
			return lines
		end
		return {}
	end

	NAmanage.PluginMaker_CommandBody = function(lines, command, indent)
		for _, action in command.actions or {} do
			for _, line in NAmanage.PluginMaker_ActionLines(action) do
				lines[#lines + 1] = indent..line
			end
		end
		NAmanage.PluginMaker_AppendRaw(lines, command.customCode, indent)
	end

	NAmanage.PluginMaker_GenerateNA = function()
		local pm = NAStuff.PluginMaker
		local lines = {
			"local plugin = Plugin.new("..NAmanage.PluginMaker_Quote(NAmanage.PluginMaker_Trim(pm.pluginName))..", "..NAmanage.PluginMaker_Quote(pm.description)..")";
			"";
			NAmanage.PluginMaker_ServicePrelude();
			"";
			NAmanage.PluginMaker_TemplateHelper();
			"";
		}
		if NAmanage.PluginMaker_Trim(pm.startupCode) ~= "" then
			lines[#lines + 1] = ""
			NAmanage.PluginMaker_AppendRaw(lines, pm.startupCode, "")
			lines[#lines + 1] = ""
		end
		for _, command in pm.commands or {} do
			local name = NAmanage.PluginMaker_Trim(command.name)
			if name ~= "" then
				local aliases = NAmanage.PluginMaker_SplitAliases(command.aliases)
				local call = "\nplugin:cmd("..NAmanage.PluginMaker_Quote(name)
				for _, alias in aliases do
					if alias:lower() ~= name:lower() then
						call = call..", "..NAmanage.PluginMaker_Quote(alias)
					end
				end
				call = call..")"
				lines[#lines + 1] = call
				if NAmanage.PluginMaker_Trim(command.argsHint) ~= "" then
					lines[#lines + 1] = "\t:args("..NAmanage.PluginMaker_Quote(command.argsHint)..")"
				end
				lines[#lines + 1] = "\t:info("..NAmanage.PluginMaker_Quote(command.description)..")"
				if command.requiresArgs == true then
					lines[#lines + 1] = "\t:requiresArgs()"
				end
				if command.overrideAliases == true then
					lines[#lines + 1] = "\t:OverrideAliases()"
				end
				if command.userButton == true then
					local label = NAmanage.PluginMaker_Trim(command.userButtonLabel)
					if label == "" then label = name end
					lines[#lines + 1] = "\t:userButton({ Label = "..NAmanage.PluginMaker_Quote(label)..", SaveArgs = "..tostring(command.saveButtonArgs ~= false).." })"
				end
				lines[#lines + 1] = "\t:run(function(ctx, ...)"
				lines[#lines + 1] = "\t\tlocal args = {...}"
				lines[#lines + 1] = "\t\tlocal player = ctx.LocalPlayer"
				NAmanage.PluginMaker_CommandBody(lines, command, "\t\t")
				lines[#lines + 1] = "\tend)"
			end
		end
		return table.concat(lines, "\n")
	end

	NAmanage.PluginMaker_GenerateIY = function()
		local pm = NAStuff.PluginMaker
		local lines = {
			NAmanage.PluginMaker_ServicePrelude();
			"";
			NAmanage.PluginMaker_TemplateHelper();
			NAmanage.PluginMaker_IYContext();
			"";
		}
		if NAmanage.PluginMaker_Trim(pm.startupCode) ~= "" then
			NAmanage.PluginMaker_AppendRaw(lines, pm.startupCode, "")
			lines[#lines + 1] = ""
		end
		for _, command in pm.commands or {} do
			local name = NAmanage.PluginMaker_Trim(command.name)
			if name ~= "" and command.userButton == true then
				local label = NAmanage.PluginMaker_Trim(command.userButtonLabel)
				if label == "" then label = name end
				lines[#lines + 1] = "if type(addUserButton) == \"function\" then addUserButton({ Label = "..NAmanage.PluginMaker_Quote(label)..", Command = "..NAmanage.PluginMaker_Quote(name)..", SaveArgs = "..tostring(command.saveButtonArgs ~= false).." }) end"
			end
		end
		if #lines > 2 then
			lines[#lines + 1] = ""
		end
		lines[#lines + 1] = "return {"
		lines[#lines + 1] = "\tPluginName = "..NAmanage.PluginMaker_Quote(pm.pluginName)..";"
		lines[#lines + 1] = "\tPluginDescription = "..NAmanage.PluginMaker_Quote(pm.description)..";"
		lines[#lines + 1] = "\tCommands = {"
		for _, command in pm.commands or {} do
			local name = NAmanage.PluginMaker_Trim(command.name)
			if name ~= "" then
				local aliases = NAmanage.PluginMaker_SplitAliases(command.aliases)
				lines[#lines + 1] = "\t\t["..NAmanage.PluginMaker_Quote(name).."] = {"
				lines[#lines + 1] = "\t\t\tListName = "..NAmanage.PluginMaker_Quote(name)..";"
				const aliasText = {}
				for _, alias in aliases do
					if alias:lower() ~= name:lower() then
						aliasText[#aliasText + 1] = NAmanage.PluginMaker_Quote(alias)
					end
				end
				lines[#lines + 1] = "\t\t\tAliases = {"..table.concat(aliasText, ", ").."};"
				if NAmanage.PluginMaker_Trim(command.argsHint) ~= "" then
					lines[#lines + 1] = "\t\t\tArgsHint = "..NAmanage.PluginMaker_Quote(command.argsHint)..";"
				end
				lines[#lines + 1] = "\t\t\tDescription = "..NAmanage.PluginMaker_Quote(command.description)..";"
				if command.requiresArgs == true then
					lines[#lines + 1] = "\t\t\tRequiresArguments = true;"
				end
				if command.overrideAliases == true then
					lines[#lines + 1] = "\t\t\tOverrideAliases = true;"
				end
				lines[#lines + 1] = "\t\t\tFunction = function(args, speaker)"
				lines[#lines + 1] = "\t\t\t\tlocal player = speaker"
				lines[#lines + 1] = "\t\t\t\tlocal ctx = __na_pm_context(player)"
				NAmanage.PluginMaker_CommandBody(lines, command, "\t\t\t\t")
				lines[#lines + 1] = "\t\t\tend;"
				lines[#lines + 1] = "\t\t};"
			end
		end
		lines[#lines + 1] = "\t};"
		lines[#lines + 1] = "}"
		return table.concat(lines, "\n")
	end

	NAmanage.PluginMaker_ValidateStep = function(step, format)
		const kind = step.type
		const val = NAmanage.PluginMaker_Trim(step.value)
		local known = false
		for _, def in NAmanage.PluginMaker_Steps do
			if def.key == kind then known = true break end
		end
		if not known then return false, "Unknown step type." end
		if kind == "stop" then return true end
		if kind == "recording" then
			if format == "iy" then return false, "Recorded gameplay needs the .na format." end
			return val ~= "", "The recording is empty."
		end
		if kind == "wait" then
			const sec = tonumber(val)
			return sec ~= nil and sec == sec and sec >= 0 and sec <= 120, "Enter a wait between 0 and 120 seconds."
		end
		if kind == "run" or kind == "mobile_run" or kind == "pc_run" then
			const args, err = NAmanage.MCPNormalizeArgs(val)
			return args ~= nil, err
		end
		if kind == "notify" or kind == "mobile_notify" or kind == "pc_notify" then
			const sec = tonumber(step.extra)
			if NAmanage.PluginMaker_Trim(step.extra) ~= "" and (not sec or sec ~= sec or sec < 0.1 or sec > 30) then
				return false, "Enter a notification duration from 0.1 to 30 seconds."
			end
		elseif kind == "add_button" then
			const args, err = NAmanage.MCPNormalizeArgs(step.extra)
			if not args then return false, err or "Enter the command the button should run." end
		end
		if kind == "load_url" and not val:match("^https?://") then return false, "Enter a script URL starting with https://." end
		if val == "" then return false, "Fill in this step before saving." end
		return true
	end

	NAmanage.PluginMaker_ValidateCommand = function(command, format)
		const name = NAmanage.PluginMaker_Trim(command.name)
		if not name:match("^[%w_%-]+$") then return false, "Use letters, numbers, underscores or hyphens for the command name." end
		if #(command.actions or {}) == 0 and NAmanage.PluginMaker_Trim(command.customCode) == "" then
			return false, "Add a step to "..name.."."
		end
		for i, step in command.actions or {} do
			const ok, err = NAmanage.PluginMaker_ValidateStep(step, format)
			if not ok then return false, name.." step "..i..". "..tostring(err) end
		end
		return true
	end

	NAmanage.PluginMaker_Generate = function()
		const pm = NAStuff.PluginMaker
		if NAmanage.PluginMaker_Trim(pm.pluginName) == "" then return nil, "Enter a plugin name in Details." end
		if type(pm.commands) ~= "table" or #pm.commands == 0 then return nil, "Add a command first." end
		const seen = {}
		for _, command in pm.commands do
			const ok, err = NAmanage.PluginMaker_ValidateCommand(command, pm.format)
			if not ok then return nil, err end
			const name = NAmanage.PluginMaker_Trim(command.name):lower()
			for _, word in { name, table.unpack(NAmanage.PluginMaker_SplitAliases(command.aliases)) } do
				word = word:lower()
				if seen[word] and seen[word] ~= command then return nil, "Two commands use "..word..". Choose a different name or alias." end
				if not word:match("^[%w_%-]+$") then return nil, "Invalid command alias "..word.."." end
				seen[word] = command
			end
		end
		for _, command in pm.commands do
			for _, step in command.actions do
				if step.type == "run" or step.type == "mobile_run" or step.type == "pc_run" then
					const argv = NAmanage.MCPNormalizeArgs(step.value)
					if argv and seen[argv[1]:lower()] == command then
						return nil, "A step in "..command.name.." runs the command itself."
					end
				end
			end
		end
		if pm.format == "iy" then return NAmanage.PluginMaker_GenerateIY() end
		return NAmanage.PluginMaker_GenerateNA()
	end

	NAmanage.PluginMaker_CompileCheck = function(source)
		if type(source) ~= "string" or source == "" then
			return false, "Generated source is empty"
		end
		local loader = loadstring or load
		if type(loader) ~= "function" then
			return true, "Compile checker unavailable"
		end
		local ok, fn, err = pcall(loader, source, "@NAPluginMaker")
		if not ok then
			ok, fn, err = pcall(loader, source)
		end
		if not ok then
			return false, tostring(fn)
		end
		if not fn then
			return false, tostring(err or "Compile failed")
		end
		return true
	end

	NAmanage.PluginMaker_UniquePath = function(path)
		if not NAmanage.PluginMaker_Exists(path) then
			return path
		end
		local stem, ext = path:match("^(.*)(%.[^%.\\/]+)$")
		stem = stem or path
		ext = ext or ""
		for i = 2, 999 do
			local candidate = stem.."_"..tostring(i)..ext
			if not NAmanage.PluginMaker_Exists(candidate) then
				return candidate
			end
		end
		return stem.."_"..tostring(os.time and os.time() or math.random(1000, 9999))..ext
	end

	NAmanage.PluginMaker_Exists = function(path)
		if type(isfile) == "function" then
			const ok, exists = pcall(isfile, path)
			if ok then return exists == true end
		end
		if type(readfile) ~= "function" then return false end
		const ok, text = pcall(readfile, path)
		return ok and type(text) == "string"
	end

	NAmanage.PluginMaker_Fingerprint = function(source)
		local hash = 5381
		for i = 1, #source do hash = (hash * 33 + source:byte(i)) % 4294967296 end
		return #source..":"..hash
	end

	NAmanage.PluginMaker_WriteDraft = function(path, source, name)
		const pm = NAStuff.PluginMaker
		const http = Services.HttpService
		const ok, raw = pcall(http.JSONEncode, http, {
			version = 1, fingerprint = NAmanage.PluginMaker_Fingerprint(source),
			pluginName = pm.pluginName, description = pm.description, fileName = name, format = pm.format,
			commands = pm.commands, selectedServices = pm.selectedServices, customServices = pm.customServices,
			startupCode = pm.startupCode,
		})
		if not ok or #raw > 4000000 then return false end
		return pcall(writefile, path..".builder.json", raw)
	end

	NAmanage.PluginMaker_ReadDraft = function(path, source)
		const okRead, raw = pcall(readfile, path..".builder.json")
		if not okRead or type(raw) ~= "string" or #raw > 4000000 then return nil end
		const http = Services.HttpService
		const ok, data = pcall(http.JSONDecode, http, raw)
		if not ok or type(data) ~= "table" or data.version ~= 1
			or data.fingerprint ~= NAmanage.PluginMaker_Fingerprint(source)
			or type(data.commands) ~= "table" or #data.commands < 1 or #data.commands > 50 then
			return nil
		end
		const commands = {}
		for i, rawCmd in data.commands do
			if type(i) ~= "number" or i < 1 or i > #data.commands or i % 1 ~= 0 then return nil end
			if type(rawCmd) ~= "table" or type(rawCmd.actions) ~= "table" or #rawCmd.actions > 120 then return nil end
			const command = NAmanage.PluginMaker_DefaultCommand()
			for key, def in command do
				if key ~= "actions" and type(rawCmd[key]) == type(def) then command[key] = rawCmd[key] end
			end
			for i, step in rawCmd.actions do
				if type(i) ~= "number" or i < 1 or i > #rawCmd.actions or i % 1 ~= 0 then return nil end
				if type(step) ~= "table" or type(step.type) ~= "string" or type(step.value) ~= "string" then return nil end
				const item = { type = step.type, value = step.value, extra = type(step.extra) == "string" and step.extra or "" }
				if not NAmanage.PluginMaker_ValidateStep(item, data.format) then return nil end
				table.insert(command.actions, item)
			end
			table.insert(commands, command)
		end
		data.commands = commands
		return data
	end

	NAmanage.PluginMaker_Save = function(install, policy)
		const pm = NAStuff.PluginMaker
		const source, genErr = NAmanage.PluginMaker_Generate()
		if not source then return false, genErr end
		const okCompile, compileErr = NAmanage.PluginMaker_CompileCheck(source)
		if not okCompile then return false, "Compile error. "..tostring(compileErr) end
		if type(writefile) ~= "function" then return false, "File saving is unavailable on this executor." end

		const ext = pm.format == "iy" and ".iy" or ".na"
		const name = NAmanage.PluginMaker_Trim(pm.fileName)
		const stem = NAmanage.PluginMaker_SafeFileName(name ~= "" and name or pm.pluginName)
		local path = stem:gsub("%.[nN][aA]$", ""):gsub("%.[iI][yY]$", ""):gsub("%.*$", "")..ext
		if install then
			const dir = pm.format == "iy" and NAfiles.NAIYPLUGINFILEPATH or NAfiles.NAPLUGINFILEPATH
			if type(dir) ~= "string" or dir == "" then return false, "The plugin folder is unavailable." end
			if type(makefolder) == "function" and (type(isfolder) ~= "function" or not isfolder(dir)) then
				const ok = pcall(makefolder, dir)
				if not ok and type(isfolder) == "function" and not isfolder(dir) then
					return false, "Could not create the plugin folder."
				end
			end
			path = dir.."/"..path
		end

		local old
		if NAmanage.PluginMaker_Exists(path) then
			if not policy then
				NAmanage.PluginMaker_OpenSaveConflict(install, path)
				return nil, "conflict"
			elseif policy == "copy" then
				path = NAmanage.PluginMaker_UniquePath(path)
			elseif type(readfile) == "function" then
				const ok, content = pcall(readfile, path)
				if not ok then return false, "Could not read the existing file." end
				old = content
				if policy == "backup" then
					const backup = NAmanage.PluginMaker_UniquePath(path..".bak")
					const good, why = pcall(writefile, backup, old)
					if not good then return false, "Could not back up the file. "..tostring(why) end
				end
			elseif policy == "backup" then
				return false, "Reading the existing file is unavailable."
			end
		end
		const ok, why = pcall(function()
			writefile(path, source)
			if type(readfile) == "function" then assert(readfile(path) == source, "The written file could not be verified.") end
		end)
		if not ok then
			if old then pcall(writefile, path, old) end
			return false, tostring(why)
		end
		const savedName = (path:match("[^\\/]+$") or path):sub(1, -4)
		const okDraft, draftSaved = pcall(NAmanage.PluginMaker_WriteDraft, path, source, savedName)
		pm.fileName = savedName
		pm.dirty = false

		local message = "Saved "..path
		if install then
			if type(NAmanage.PluginSetEnabled) == "function" then NAmanage.PluginSetEnabled(path, true) end
			NAmanage.PluginMaker_ReloadPlugins()
			const key = path:gsub("\\", "/"):lower()
			local meta = (NAmanage._pluginFileMeta or {})[key]
			if not meta then
				for item, entry in NAmanage._pluginFileMeta or {} do
					if item:sub(-#key - 1) == "/"..key then meta = entry break end
				end
			end
			if not meta or not meta.loaded or #meta.commands == 0 then
				return false, message..". NA could not load its commands. Check the plugin errors."
			end
			message = "Installed. Run "..table.concat(meta.commands, ", ").." from the command bar."
		end
		if not okDraft or not draftSaved then message ..= " Editable draft could not be saved." end
		return true, message
	end

	NAmanage.PluginMaker_SaveStatus = function(install, policy)
		const pm = NAStuff.PluginMaker
		if pm.saving then return end
		pm.saving = true
		const ok, done, message = pcall(NAmanage.PluginMaker_Save, install, policy)
		pm.saving = false
		if not ok then NAmanage.PluginMaker_SetStatus(tostring(done), "error") return end
		if done == nil then return end
		NAmanage.PluginMaker_SetStatus(message, done and "success" or "error")
		if done then
			NAmanage.PluginMaker_RebuildEditor(true)
			DoNotif(message, 4, "Plugin Maker")
		end
	end

	NAmanage.PluginMaker_ListPluginFiles = function()
		local out = {}
		if type(listfiles) ~= "function" then
			return out
		end
		local dirs = {
			{ path = NAfiles and NAfiles.NAPLUGINFILEPATH; format = "na" };
			{ path = NAfiles and NAfiles.NAIYPLUGINFILEPATH; format = "iy" };
			{ path = "" };
		}
		for _, info in dirs do
			if type(info.path) == "string" and (info.path == "" or type(isfolder) ~= "function" or isfolder(info.path)) then
				local ok, items = pcall(listfiles, info.path)
				if ok and type(items) == "table" then
					for _, path in items do
						if type(path) == "string" then
							local low = path:lower()
							const fmt = low:match("%.([%a]+)$")
							if (fmt == "na" or fmt == "iy") and (not info.format or fmt == info.format) then
								out[#out + 1] = {
									path = path;
									format = fmt;
									name = path:match("[^\\/]+$") or path;
								}
							end
						end
					end
				end
			end
		end
		table.sort(out, function(a, b)
			return tostring(a.name):lower() < tostring(b.name):lower()
		end)
		return out
	end

