		{ key = "run", label = "Run a command", command = true, fields = { { "value", "Command and arguments", "Example: walkspeed 32" } } },
		{ key = "wait", label = "Wait", fields = { { "value", "Seconds", "1", "1" } } },
		{ key = "recording", label = "Play a recording", editOnly = true, help = "Use Make Plugin in the Action Recorder to replace these recorded steps." },
		{ key = "print", label = "Print to console", advanced = true, fields = { { "value", "Message", "Command started" } } },
		{ key = "copy", label = "Copy text", advanced = true, fields = { { "value", "Text to copy", "Text" } } },
		{ key = "mobile_run", label = "Run a command on mobile", advanced = true, command = true, fields = { { "value", "Command and arguments", "Example: walkspeed 32" } } },
		{ key = "pc_run", label = "Run a command on desktop", advanced = true, command = true, fields = { { "value", "Command and arguments", "Example: walkspeed 32" } } },
		{ key = "mobile_notify", label = "Notify on mobile", advanced = true, fields = { { "value", "Message", "Hello" }, { "extra", "Show for (seconds)", "3", "3" } } },
		{ key = "pc_notify", label = "Notify on desktop", advanced = true, fields = { { "value", "Message", "Hello" }, { "extra", "Show for (seconds)", "3", "3" } } },
		{ key = "add_button", label = "Add an NA user button", advanced = true, fields = { { "value", "Button label", "My button" }, { "extra", "Command and arguments", "Example: walkspeed 32" } } },
		{ key = "remove_button", label = "Remove an NA user button", advanced = true, fields = { { "value", "Button label or ID", "My button" } } },
