	}

	NAmanage.PluginMaker_EditStep = function(command, index)
		const pm = NAStuff.PluginMaker
		const F = NAmanage.BuilderUI
		const actions = command.actions
		const old = index and actions[index]
		const edit = {}
		const function refresh()
			pm.dirty = true
			NAmanage.PluginMaker_RebuildEditor(true)
			const dlg = pm.Frame:FindFirstChild("BuilderDialog")
			if dlg then dlg:Destroy() end
		end
		if index then
			if index > 1 then
				table.insert(edit, { "Move Up", function() actions[index], actions[index - 1] = actions[index - 1], old refresh() end })
			end
			if index < #actions then
				table.insert(edit, { "Move Down", function() actions[index], actions[index + 1] = actions[index + 1], old refresh() end })
			end
			table.insert(edit, { "Delete Step", function() table.remove(actions, index) refresh() end })
		end
		F.step(pm.Frame, {
			defs = NAmanage.PluginMaker_Steps,
			advanced = true,
			step = old and { kind = old.type, value = old.type == "recording" and "" or old.value, extra = old.extra },
			edit = #edit > 0 and edit or nil,
			save = function(kind, fields)
				const step = kind == "recording" and old or { type = kind, value = fields.value or "", extra = fields.extra or "" }
				const ok, msg = NAmanage.PluginMaker_ValidateStep(step, pm.format)
				if not ok then return false, msg end
				actions[index or #actions + 1] = step
				pm.dirty = true
				NAmanage.PluginMaker_RebuildEditor(true)
				return true
			end,
		})
	end

	NAmanage.PluginMaker_Test = function(command, text)
		const pm = NAStuff.PluginMaker
		const ok, err = NAmanage.PluginMaker_ValidateCommand(command, pm.format)
		if not ok then return false, err end
		if pm.testing then return false, "A test is already running." end
		local args = {}
		if NAmanage.PluginMaker_Trim(text) ~= "" then
			local parsed, why = NAmanage.MCPNormalizeArgs(text)
			if not parsed then return false, why end
			args = parsed
		elseif command.requiresArgs then
			return false, "Enter sample arguments for this command."
		end
		const lines = {
			NAmanage.PluginMaker_ServicePrelude(), NAmanage.PluginMaker_TemplateHelper(),
			"return function(ctx, ...)\n\tlocal args = {...}\n\tlocal player = ctx.LocalPlayer",
		}
		NAmanage.PluginMaker_CommandBody(lines, command, "\t")
		lines[#lines + 1] = "end"
		const loader = loadstring or load
		if type(loader) ~= "function" then return false, "Script compilation is unavailable." end
		const build, why = loader(table.concat(lines, "\n"), "@PluginMakerTest")
		if not build then return false, why end
		const ctx = {
			LocalPlayer = Services.Players.LocalPlayer, Player = Services.Players.LocalPlayer,
			Services = Services, ServiceResolver = ServiceResolver, IsOnPC = IsOnPC, IsOnMobile = IsOnMobile,
			notify = function(_, msg, sec) return DoNotif(msg, sec) end,
			run = function(_, ...)
				const argv, why = NAmanage.MCPNormalizeArgs(...)
				if not argv then error(why, 0) end
				const name = argv[1]:lower()
				if not (cmds.Commands[name] or cmds.Aliases[name]) then error("Command not found: "..argv[1], 0) end
				const okRun, msg = cmd.run(argv, { prediction = false })
				if okRun == false then error(msg or "The command failed.", 0) end
				return okRun
			end,
			addUserButton = function() error("Save & Install to test an NA user button.", 0) end,
			removeUserButton = function() error("Save & Install to test an NA user button.", 0) end,
		}
		pm.testing = true
		task.defer(function()
			const good, msg = pcall(function() return build()(ctx, table.unpack(args)) end)
			pm.testing = false
			NAmanage.PluginMaker_SetStatus(good and "Test finished." or tostring(msg), good and "success" or "error")
		end)
		NAmanage.PluginMaker_SetStatus("Testing "..command.name.."...")
		return true
	end

	NAmanage.PluginMaker_CommandOptions = function(command)
		const pm = NAStuff.PluginMaker
		const F = NAmanage.BuilderUI
		const list, close = F.dialog(pm.Frame, "Command Options")
		for _, opt in {
			{ "aliases", "Other names (optional)", "Example: fast, quick" },
			{ "argsHint", "Arguments shown in help (optional)", "Example: [player]" },
			{ "description", "Command description (optional)", "Describe what this command does" },
			{ "userButtonLabel", "User button label (optional)", "Defaults to the command name" },
		} do
			F.field(list, opt[2], opt[3], command[opt[1]], function(value) command[opt[1]] = value pm.dirty = true end)
		end
		for _, opt in {
			{ "requiresArgs", "Require arguments" }, { "overrideAliases", "Replace matching NA aliases" },
			{ "userButton", "Add an NA user button" }, { "saveButtonArgs", "Remember user button arguments" },
		} do
			local btn
			const function label() return opt[2].."  "..(command[opt[1]] and "On" or "Off") end
			btn = F.buttons(list, { { label(), function()
				command[opt[1]] = not command[opt[1]]
				btn:FindFirstChildWhichIsA("TextButton").Text = label()
				pm.dirty = true
			end } })
		end
		F.text(list, "Use {1} for the first argument, {args} for all arguments, or {user} for your username.")
		F.buttons(list, { { "Edit Command Code", function() close() NAmanage.PluginMaker_OpenCodeEditor("command") end } })
		F.buttons(list, { { "Duplicate Command", function()
			if #pm.commands >= 50 then NAmanage.PluginMaker_SetStatus("Limit of 50 commands reached.", "warn") return end
			const copy = table.clone(command)
			copy.name = command.name ~= "" and command.name.."_copy" or ""
			copy.aliases = ""
			copy.actions = table.clone(command.actions)
			table.insert(pm.commands, copy)
			pm.selectedCommand = #pm.commands
			pm.dirty = true
			close()
			NAmanage.PluginMaker_RebuildEditor()
		end } })
		if #pm.commands > 1 then
			F.buttons(list, { { "Delete This Command", function()
				table.remove(pm.commands, pm.selectedCommand)
				pm.dirty = true
				close()
				NAmanage.PluginMaker_RebuildEditor()
			end } })
		end
	end

	NAmanage.PluginMaker_RebuildEditor = function(keepScroll)
		const pm = NAStuff.PluginMaker
		if not (pm.Workspace and pm.Workspace.Parent) then return end
		const F = NAmanage.BuilderUI
		const pos = keepScroll and pm.Editor and pm.Editor.CanvasPosition or Vector2.zero
		if pm.Editor then pm.Editor:Destroy() end
		const list = F.list(pm.Workspace)
		pm.Editor = list
		list.Size = UDim2.fromScale(1, 1)
		NAmanage.PluginMaker_ClearGui(pm.Meta)
		const function go(page)
			pm.page = page
			NAmanage.PluginMaker_RebuildEditor()
		end
		F.buttons(pm.Meta, {
			{ "Details", function() go("details") end, pm.page == "details" },
			{ "Commands", function() go("commands") end, pm.page == "commands" },
			{ "Save & Share", function() go("export") end, pm.page == "export" },
		}, 36)

		if pm.page == "details" then
			F.field(list, "Plugin name", "Example: Quick Controls", pm.pluginName, function(value) pm.pluginName = value pm.dirty = true end)
			F.field(list, "Description (optional)", "What does the plugin do?", pm.description, function(value) pm.description = value pm.dirty = true end)
			F.text(list, "Plugin format")
			const function format(value)
				pm.format = value
				pm.dirty = true
				NAmanage.PluginMaker_RebuildEditor(true)
			end
			F.buttons(list, {
				{ "Nameless Admin (.na)", function() format("na") end, pm.format == "na" },
				{ "Infinite Yield (.iy)", function() format("iy") end, pm.format == "iy" },
			})
			F.buttons(list, { { "Build a Command", function()
				if NAmanage.PluginMaker_Trim(pm.pluginName) == "" then
					NAmanage.PluginMaker_SetStatus("Enter a plugin name first.", "warn")
					return
				end
				go("commands")
			end, true } })
			F.buttons(list, { { "Open Saved Plugin", NAmanage.PluginMaker_OpenFilePicker }, { "New Plugin", function()
				if not pm.dirty then NAmanage.PluginMaker_ResetState() go("details") return end
				const menu, close = F.dialog(pm.Frame, "Start a New Plugin")
				F.text(menu, "Starting over will discard your unsaved changes.")
				F.buttons(menu, { { "Discard and Start New", function() close() NAmanage.PluginMaker_ResetState() go("details") end } })
			end } })
		elseif pm.page == "commands" then
			const command, index = NAmanage.PluginMaker_GetSelectedCommand()
			F.buttons(list, {
				{ "Choose Command ("..index.."/"..#pm.commands..")", function()
					const menu, close = F.dialog(pm.Frame, "Choose a Command")
					for i, item in pm.commands do
						F.buttons(menu, { { item.name ~= "" and item.name or "Unnamed command "..i, function()
							pm.selectedCommand = i
							close()
							go("commands")
						end, i == index } })
					end
				end },
				{ "Add Command", function()
					if #pm.commands >= 50 then NAmanage.PluginMaker_SetStatus("Limit of 50 commands reached.", "warn") return end
					table.insert(pm.commands, NAmanage.PluginMaker_DefaultCommand())
					pm.selectedCommand = #pm.commands
					pm.dirty = true
					go("commands")
				end },
			})
			F.field(list, "Command name", "Example: quickspeed", command.name, function(value) command.name = value pm.dirty = true end)
			F.text(list, "Run this name from the command bar. The steps below run in order.")
			F.buttons(list, {
				{ "Add Step", function()
					if #command.actions >= 120 then NAmanage.PluginMaker_SetStatus("Limit of 120 steps reached.", "warn") return end
					NAmanage.PluginMaker_EditStep(command)
				end, true },
				{ "Test Command", function()
					const menu, close, status = F.dialog(pm.Frame, "Test Command")
					F.text(menu, "Run the steps once using NA's commands.")
					const args = F.field(menu, "Sample arguments (optional)", "Example: me 32", "")
					F.buttons(menu, { { "Run Test", function()
						const ok, err = NAmanage.PluginMaker_Test(command, args.Text)
						if ok then close() else status.Text = tostring(err) end
					end, true } })
				end },
			})
			if #command.actions == 0 then
				F.text(list, "Add a step such as Show a notification or Run a command.")
				F.buttons(list, { { "Use a Hello Example", function()
					if NAmanage.PluginMaker_Trim(pm.pluginName) == "" then pm.pluginName = "Hello Plugin" end
					if command.name == "" then command.name = "sayhello" end
					table.insert(command.actions, { type = "notify", value = "Hello, {user}!", extra = "3" })
					pm.dirty = true
					go("commands")
				end } })
			end
			for i, action in command.actions do
				local label = action.type
				for _, def in NAmanage.PluginMaker_Steps do if def.key == action.type then label = def.label break end end
				const value = action.type == "recording" and "" or NAmanage.PluginMaker_Trim(action.value):gsub("[%c]+", " ")
				F.buttons(list, { { i..". "..label..(value ~= "" and ("  ·  "..value:sub(1, 100)) or ""), function()
					NAmanage.PluginMaker_EditStep(command, i)
				end } }, 42)
			end
			F.buttons(list, {
				{ "Command Options", function() NAmanage.PluginMaker_CommandOptions(command) end },
				{ "Save & Share", function() go("export") end },
			})
		else
			F.text(list, "Output format "..(pm.format == "iy" and ".iy" or ".na"))
			if pm.format == "iy" then F.text(list, "Commands you call must exist in the admin script that loads this plugin.") end
			F.field(list, "File name (optional)", NAmanage.PluginMaker_SafeFileName(pm.pluginName), pm.fileName, function(value) pm.fileName = value pm.dirty = true end)
			F.buttons(list, {
				{ "Save & Install in NA", function() NAmanage.PluginMaker_SaveStatus(true) end, true },
				{ "Export File", function() NAmanage.PluginMaker_SaveStatus(false) end },
			})
			F.text(list, "Install to use your commands in NA now. Export creates a file you can share.")
			F.buttons(list, { { "Preview Source", NAmanage.PluginMaker_OpenPreview }, { "Open Saved Plugin", NAmanage.PluginMaker_OpenFilePicker } })
			F.buttons(list, { { "Advanced", function()
				const menu, close = F.dialog(pm.Frame, "Advanced Plugin Options")
				F.buttons(menu, { { "Choose Services", function() close() NAmanage.PluginMaker_OpenServicePicker() end } })
				F.buttons(menu, { { "Edit Startup Code", function() close() NAmanage.PluginMaker_OpenCodeEditor("startup") end } })
				F.buttons(menu, { { "Manage Installed Plugins", function() close() NAmanage.PluginMaker_OpenInstalledManager() end } })
			end } })
		end
		if pos.Y > 0 then task.defer(function() if list.Parent then list.CanvasPosition = pos end end) end
	end

	NAmanage.PluginMaker_FromRecording = function(blob, name)
		const ok, err = NAmanage.PluginMaker_Open()
		if not ok then return false, err end
		const pm = NAStuff.PluginMaker
		const function start()
			NAmanage.PluginMaker_ResetState()
			pm.pluginName = name ~= "" and name or "Recorded Actions"
			pm.commands[1].name = "play_"..NAmanage.PluginMaker_SafeFileName(pm.pluginName):lower():gsub("[^%w_%-]", "_"):sub(1, 36)
			pm.commands[1].description = "Play a recorded sequence"
			pm.commands[1].actions = { { type = "recording", value = blob } }
			pm.page = "commands"
			pm.dirty = true
			NAmanage.PluginMaker_RebuildEditor()
		end
		if pm.dirty then
			const F = NAmanage.BuilderUI
			const menu, close = F.dialog(pm.Frame, "Make Plugin from Recording")
			F.text(menu, "Creating this plugin will replace your unsaved draft.")
			F.buttons(menu, { { "Replace Draft", function() close() start() end } })
		else
			start()
		end
		return true
	end

	NAmanage.PluginMaker_OpenPreview = function()
		local pm = NAStuff.PluginMaker
		local source, err = NAmanage.PluginMaker_Generate()
		if not source then
			NAmanage.PluginMaker_SetStatus(err, "error")
			return
		end
		local okCompile, compileErr = NAmanage.PluginMaker_CompileCheck(source)
		if not okCompile then
			NAmanage.PluginMaker_SetStatus("Compile error: "..tostring(compileErr), "error")
			return
		end
		if not pm.PreviewOverlay or not pm.PreviewOverlay.Parent then return end
		pm.PreviewBox.Text = source
		pm.PreviewOverlay.Visible = true
		NAmanage.PluginMaker_SetStatus("Generated "..tostring(pm.format == "iy" and ".iy" or ".na").." source successfully", "success")
	end

	NAmanage.PluginMaker_Resize = function(initial)
		local pm = NAStuff.PluginMaker
		local frame = pm.Frame
		if not frame or not frame.Parent then return end
		if initial == true then
			local camera = Services.Workspace and Services.Workspace.CurrentCamera
			local vp = camera and camera.ViewportSize or Vector2.new(900, 600)
			local width = math.max(300, math.min(900, vp.X - 18))
			local height = math.max(280, math.min(620, vp.Y - 28))
			if NAmanage.ExecutorWindowSizing and type(NAmanage.ExecutorWindowSizing.GetSize) == "function" then
				local okMetrics, metrics = pcall(NAmanage.ExecutorWindowSizing.GetSize, 900, 620, {
					minWidth = 520;
					minHeight = 360;
					mobileMinWidth = 300;
					mobileMinHeight = 260;
				})
				if okMetrics and type(metrics) == "table" then
					width = math.min(tonumber(metrics.width) or width, math.max(300, vp.X - 18))
					height = math.min(tonumber(metrics.height) or height, math.max(280, vp.Y - 28))
				end
			end
			frame.Size = UDim2.fromOffset(width, height)
		end
		if initial == true and type(NAmanage.centerFrame) == "function" then
			pcall(NAmanage.centerFrame, frame)
		end
	end

	NAmanage.PluginMaker_BindResize = function()
		local pm = NAStuff.PluginMaker
		local frame = pm.Frame
		if not frame or not frame.Parent then
			return
		end
		if pm.ResizeCleanup then
			pcall(pm.ResizeCleanup)
			pm.ResizeCleanup = nil
		end
		if NAgui and type(NAgui.resizeable) == "function" then
			local minSize = IsOnMobile and Vector2.new(300, 260) or Vector2.new(520, 360)
			pm.ResizeCleanup = NAgui.resizeable(frame, minSize, Vector2.new(5000, 5000))
		end
	end

	NAmanage.PluginMaker_BindDrag = function()
		local pm = NAStuff.PluginMaker
		local frame = pm.Frame
		local topbar = pm.Topbar
		if not frame or not topbar or not Services.UserInputService then return end
		pm.dragging = false
		NAlib.reconnect("plugin_maker_drag_start", topbar.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				pm.dragging = true
				pm.dragStart = input.Position
				pm.dragPos = frame.Position
				NAlib.reconnect("plugin_maker_drag_end", input.Changed:Connect(function()
					if input.UserInputState == Enum.UserInputState.End then
						pm.dragging = false
						NAlib.disconnect("plugin_maker_drag_end")
					end
				end))
			end
		end))
		NAlib.reconnect("plugin_maker_drag_move", Services.UserInputService.InputChanged:Connect(function(input)
			if not pm.dragging or not pm.dragStart or not pm.dragPos then return end
			if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
			local delta = input.Position - pm.dragStart
			frame.Position = UDim2.new(pm.dragPos.X.Scale, pm.dragPos.X.Offset + delta.X, pm.dragPos.Y.Scale, pm.dragPos.Y.Offset + delta.Y)
		end))
	end

